using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<CheckboxActionApp>("Checkbox Action", width: 420, height: 260);

class CheckboxActionApp : Component
{
    public override Element Render()
    {
        var (message, setMessage) = UseState("Action waiting");

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto],
            CheckBox("Trigger action", false, isChecked =>
                setMessage(isChecked == true ? "Checkbox action triggered" : "Action waiting"))
                .Grid(0, 0)
                .Margin(0, 0, 0, 16),
            TextBlock(message)
                .Grid(1, 0)
        )
        .Padding(24)
        .Background(Theme.SolidBackground);
    }
}

