using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<RecordEditorPage>("Record Editor", width: 420, height: 260);

record EditableRecord(string Value);

class RecordEditorPage : Component
{
    public override Element Render()
    {
        var (record, setRecord) = UseState(new EditableRecord("Original record value"));

        return Border(
            Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto],
                TextBlock("Record editor")
                    .FontSize(24)
                    .SemiBold()
                    .Grid(0, 0),

                Border(
                    TextBlock(record.Value)
                        .FontSize(18)
                        .Foreground(Theme.PrimaryText)
                )
                .Padding(16)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Grid(1, 0),

                Button("Edit record", () =>
                    setRecord(record with { Value = "Edited record value" }))
                    .Grid(2, 0)
            )
            .RowSpacing(12)
        )
        .Padding(20)
        .Background(Theme.SubtleFill);
    }
}

