using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;

ReactorApp.Run<App>("Reactor DataGrid Action", width: 900, height: 600);

record ActionRow(string Action, string Description);

class App : Component
{
    static readonly List<ActionRow> Actions =
    [
        new("Send greeting", "Triggers the greeting action string."),
        new("Archive item", "Triggers the archive action string."),
        new("Refresh data", "Triggers the refresh action string.")
    ];

    static readonly ListDataSource<ActionRow> Source = new(
        Actions,
        row => new RowKey(row.Action),
        false);

    static readonly FieldDescriptor[] Columns =
    [
        Column<ActionRow>("Action", row => row.Action, displayName: "Action", width: 180),
        Column<ActionRow>("Description", row => row.Description, displayName: "Description")
    ];

    public override Element Render()
    {
        var (result, setResult) = UseState("Select a row to trigger its action string.");

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Star(), GridSize.Auto],
                Heading("DataGrid action trigger")
                    .Grid(row: 0),
                DataGrid<ActionRow>(
                        Source,
                        Columns,
                        selectionMode: SelectionMode.Single,
                        onSelectionChanged: selected =>
                        {
                            if (selected.Count == 0)
                            {
                                setResult("Select a row to trigger its action string.");
                                return;
                            }

                            setResult($"Triggered action: {selected.First().Value}");
                        })
                    .Grid(row: 1)
                    .Margin(0, 16, 0, 16),
                TextBlock(result)
                    .Grid(row: 2)
                    .Foreground(Theme.SecondaryText))
            .RequestedTheme(ElementTheme.Default)
            .Background(Theme.SolidBackground)
            .Padding(24);
    }
}

