using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<DialogFlowApp>("Dialog Flow DataGrid", width: 760, height: 520);

sealed record DialogAction(string Id, string Name, string Action, string Details);

static class DialogActions
{
    public static readonly IReadOnlyList<DialogAction> Items =
    [
        new("welcome", "Welcome customer", "Send welcome message", "Open a dialog that confirms the welcome-message action string."),
        new("review", "Request review", "Request account review", "Open a dialog that confirms the account-review action string."),
        new("archive", "Archive request", "Archive completed request", "Open a dialog that confirms the archive-request action string."),
        new("notify", "Notify owner", "Notify assigned owner", "Open a dialog that confirms the owner-notification action string."),
    ];
}

sealed class DialogFlowApp : Component
{
    public override Element Render()
    {
        var (selectedAction, setSelectedAction) = UseState<DialogAction?>(null);
        var (isDialogOpen, setDialogOpen) = UseState(false);

        var source = UseMemo(() => new ListDataSource<DialogAction>(
            DialogActions.Items,
            action => (RowKey)action.Id));

        var columns = UseMemo(() => new FieldDescriptor[]
        {
            Column<DialogAction>("Name", action => action.Name, displayName: "Step", width: 180),
            Column<DialogAction>("Action", action => action.Action, displayName: "Action string", width: 220),
            Column<DialogAction>("Details", action => action.Details, width: 280),
        });

        void TriggerSelection(IReadOnlySet<RowKey> keys)
        {
            var key = keys.FirstOrDefault();
            if (string.IsNullOrWhiteSpace(key.Value))
            {
                return;
            }

            var action = DialogActions.Items.First(item => item.Id == key.Value);
            setSelectedAction(action);
            setDialogOpen(true);
        }

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Star(), GridSize.Auto],
                Heading("Dialog flow actions")
                    .Grid(row: 0, column: 0),
                TextBlock("Select a row to trigger its action string and review it in the dialog.")
                    .Foreground(Theme.SecondaryText)
                    .TextWrapping(TextWrapping.Wrap)
                    .Margin(top: 6, bottom: 16)
                    .Grid(row: 1, column: 0),
                Border(
                        DataGrid(
                                source: source,
                                columns: columns,
                                selectionMode: SelectionMode.Single,
                                onSelectionChanged: TriggerSelection,
                                rowHeight: 44)
                            .Height(280))
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
