using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Tabbed Slider", width: 520, height: 360);

class App : Component
{
    public override Element Render()
    {
        var (message, setMessage) = UseState("Move the slider to trigger an action.");
        var (sliderValue, setSliderValue) = UseState(50.0);

        void UpdateSlider(double value)
        {
            setSliderValue(value);
            setMessage($"Slider action triggered: {value:0}");
        }

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Star()],
            TabView(
                TabViewItem(
                    "Slider",
                    Grid(
                        columns: [GridSize.Star()],
                        rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto],
                        Heading("Slider action").Grid(0, 0),
                        Slider(sliderValue, UpdateSlider, minimum: 0, maximum: 100)
                            .Margin(0, 20, 0, 12)
                            .Grid(1, 0),
                        TextBlock(message).Grid(2, 0)
                    )
                    .Padding(24)
                ),
                TabViewItem(
                    "Status",
                    Grid(
                        columns: [GridSize.Star()],
                        rows: [GridSize.Auto, GridSize.Auto],
                        SubHeading("Current string").Grid(0, 0),
                        TextBlock(message)
                            .Margin(0, 12, 0, 0)
                            .Grid(1, 0)
                    )
                    .Padding(24)
                )
            )
            .Grid(0, 0)
        )
        .Padding(16)
        .Background(Theme.SolidBackground);
    }
}

