ReactorApp.Run<App>("ReactorMasterDetail", width: 900, height: 600);

class App : Component
{
    public override Element Render()
    {
        var (selectedDetail, setSelectedDetail) = UseState("Select a master item to view its detail.");

        return Grid(
            columns: [GridSize.Px(280), GridSize.Star()],
            rows: [GridSize.Star()],
            VStack(
                Heading("Master"),
                Button("Overview", () => setSelectedDetail("Overview selected")),
                Button("Settings", () => setSelectedDetail("Settings selected")),
                Button("Activity", () => setSelectedDetail("Activity selected"))
            )
            .Spacing(12)
            .Grid(row: 0, column: 0),

            VStack(
                Heading("Detail"),
                TextBlock(selectedDetail)
            )
            .Spacing(12)
            .Grid(row: 0, column: 1)
        )
        .Padding(24)
        .RequestedTheme(ElementTheme.Default);
    }
}

