using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Core.Theme;

ReactorApp.Run<App>("Master-detail checkbox", width: 900, height: 600);

class App : Component
{
    const string Enabled = "Enabled";
    const string Disabled = "Disabled";

    public override Element Render()
    {
        var (choice, setChoice) = UseState(Disabled);
        var isEnabled = choice == Enabled;

        return Grid(
                columns: [GridSize.Px(280), GridSize.Star()],
                rows: [GridSize.Star()],
                Border(
                        VStack(
                                Heading("Master"),
                                TextBlock("Toggle the option to update the selected string state.")
                                    .Foreground(SecondaryText),
                                CheckBox(
                                        isEnabled,
                                        checkedValue => setChoice(checkedValue ? Enabled : Disabled),
                                        "Use enabled state")
                                    .AutomationName("StateCheckBox")
                            )
                            .Spacing(16)
                    )
                    .Padding(24)
                    .Background(CardBackground)
                    .WithBorder(CardStroke)
                    .CornerRadius(12)
                    .Grid(row: 0, column: 0),
                Border(
                        VStack(
                                Heading("Detail"),
                                Caption("Current string state"),
                                TextBlock(choice)
                                    .Foreground(AccentText)
                            )
                            .Spacing(12)
                    )
                    .Padding(24)
                    .Background(CardBackground)
                    .WithBorder(CardStroke)
                    .CornerRadius(12)
                    .Grid(row: 0, column: 1)
            )
            .ColumnSpacing(16)
            .Padding(24)
            .Background(SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }
}

