using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

ReactorApp.Run<App>("Dialog CheckBox Flow", width: 720, height: 420);

sealed class App : Component
{
    const string CheckedValue = "Checked";
    const string UncheckedValue = "Unchecked";

    public override Element Render()
    {
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (selectedState, setSelectedState) = UseState(UncheckedValue);

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Star()],
                Heading("Dialog CheckBox Flow")
                    .Margin(24, 24, 24, 8)
                    .Grid(row: 0),

                TextBlock($"String state: {selectedState}")
                    .Margin(24, 0, 24, 16)
                    .Grid(row: 1),

                Button("Open dialog", () => setDialogOpen(true))
                    .Margin(24, 0, 24, 24)
                    .VAlign(VerticalAlignment.Top)
                    .Grid(row: 2),

                (ContentDialog(
                    "Choose state",
                    Grid(
                            columns: [GridSize.Auto, GridSize.Star()],
                            rows: [GridSize.Auto, GridSize.Auto],
                            CheckBox(
                                    selectedState == CheckedValue,
                                    isChecked => setSelectedState(isChecked ? CheckedValue : UncheckedValue),
                                    "Use checked string")
                                .Grid(row: 0, column: 0, columnSpan: 2),

                            TextBlock("Current dialog value:")
                                .Margin(0, 12, 8, 0)
                                .Grid(row: 1, column: 0),

                            TextBlock(selectedState)
                                .Margin(0, 12, 0, 0)
                                .Grid(row: 1, column: 1)
                        )
                        .ColumnSpacing(8),
                    primaryButtonText: "OK") with
                {
                    IsOpen = isDialogOpen,
                    DefaultButton = ContentDialogButton.Primary,
                    OnClosed = _ => setDialogOpen(false),
                })
                .RequestedTheme(ElementTheme.Default)
                .Grid(row: 2)
            )
            .RequestedTheme(ElementTheme.Default);
    }
}

