using System.Globalization;
using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Slider Master Detail", width: 900, height: 560);

sealed record DetailItem(string Name, string Description);

class App : Component
{
    static readonly IReadOnlyList<DetailItem> Items =
    [
        new("Overview", "Use the slider to adjust the shared detail value."),
        new("Details", "The same string state is shown here and updated by the slider."),
        new("Settings", "Default theme resources keep the layout aligned with WinUI.")
    ];

    public override Element Render()
    {
        var (selectedName, setSelectedName) = UseState(Items[0].Name);
        var (sliderText, setSliderText) = UseState("50");
        var selectedItem = Items.First(item => item.Name == selectedName);
        var sliderValue = ParseSliderValue(sliderText);

        return Grid(
            columns: [GridSize.Px(260), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            VStack(4,
                TextBlock("Master detail").FontSize(28).SemiBold().Foreground(Theme.PrimaryText),
                TextBlock("Slider value is stored as string state.").Foreground(Theme.SecondaryText)
            )
            .Grid(row: 0, column: 0, columnSpan: 2)
            .Margin(0, 0, 0, 20),

            RenderMaster(selectedName, setSelectedName)
                .Grid(row: 1, column: 0)
                .Margin(0, 0, 20, 0),

            RenderDetail(selectedItem, sliderText, sliderValue, setSliderText)
                .Grid(row: 1, column: 1)
        )
        .Padding(28)
        .Background(Theme.SolidBackground)
        .RequestedTheme(ElementTheme.Default);
    }

    static Element RenderMaster(string selectedName, Action<string> setSelectedName) =>
        Border(
            VStack(10,
                TextBlock("Master").FontSize(18).SemiBold().Foreground(Theme.PrimaryText),
                VStack(8,
                    Items.Select(item =>
                        Button(item.Name, () => setSelectedName(item.Name))
                            .HAlign(HorizontalAlignment.Stretch)
                            .WithKey(item.Name)
                            .Background(item.Name == selectedName ? Theme.ControlFillSecondary : Theme.ControlFillDefault)
                    ).ToArray()
                )
            )
            .Padding(16)
        )
        .Background(Theme.LayerFill)
        .WithBorder(Theme.CardStroke)
        .CornerRadius(12);

    static Element RenderDetail(DetailItem item, string sliderText, double sliderValue, Action<string> setSliderText) =>
        Border(
            Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Star()],
                TextBlock(item.Name).FontSize(24).SemiBold().Foreground(Theme.PrimaryText).Grid(row: 0, column: 0),
                TextBlock(item.Description).Foreground(Theme.SecondaryText).Grid(row: 1, column: 0).Margin(0, 8, 0, 24),
                Slider(sliderValue, 0, 100, value => setSliderText(value.ToString("F0", CultureInfo.InvariantCulture)))
                    .Header("String-backed slider")
                    .StepFrequency(1)
                    .Grid(row: 2, column: 0),
                Border(
                    VStack(8,
                        TextBlock("State").FontSize(16).SemiBold().Foreground(Theme.PrimaryText),
                        TextBlock(sliderText).FontSize(44).SemiBold().Foreground(Theme.Accent),
                        TextBlock($"Stored value type: {sliderText.GetType().Name}").Foreground(Theme.SecondaryText)
                    )
                    .Padding(20)
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(10)
                .Grid(row: 3, column: 0)
                .Margin(0, 24, 0, 0)
            )
            .Padding(20)
        )
        .Background(Theme.LayerFill)
        .WithBorder(Theme.CardStroke)
        .CornerRadius(12);

    static double ParseSliderValue(string value) =>
        double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed)
            ? Math.Clamp(parsed, 0, 100)
            : 0;
}

