                    ).ToArray()
                )
            )
            .Padding(16)
        )
        .Background(Theme.LayerFill)
        .WithBorder(Theme.CardStroke)
        .CornerRadius(12);

    static Element RenderDetail(DetailItem item, string sliderText, double sliderValue, Action<string> setSliderText) =>
        Border(
            Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Star()],
                TextBlock(item.Name).FontSize(24).SemiBold().Foreground(Theme.PrimaryText).Grid(row: 0, column: 0),
                TextBlock(item.Description).Foreground(Theme.SecondaryText).Grid(row: 1, column: 0).Margin(0, 8, 0, 24),
                Slider(sliderValue, 0, 100, value => setSliderText(value.ToString("F0", CultureInfo.InvariantCulture)))
                    .Header("String-backed slider")
                    .StepFrequency(1)
                    .Grid(row: 2, column: 0),
                Border(
                    VStack(8,
