                        TextBlock($"Stored value type: {sliderText.GetType().Name}").Foreground(Theme.SecondaryText)
                    )
                    .Padding(20)
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(10)
                .Grid(row: 3, column: 0)
                .Margin(0, 24, 0, 0)
            )
            .Padding(20)
        )
        .Background(Theme.LayerFill)
        .WithBorder(Theme.CardStroke)
        .CornerRadius(12);

    static double ParseSliderValue(string value) =>
        double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed)
            ? Math.Clamp(parsed, 0, 100)
            : 0;
}

