class TabbedFilterApp : Component
{
    static readonly string[] Items =
    [
        "Apple",
        "Apricot",
        "Banana",
        "Blueberry",
        "Cherry",
        "Clementine",
        "Date",
        "Fig",
        "Grape",
        "Kiwi"
    ];

    public override Element Render()
    {
        var (showAItemsOnly, setShowAItemsOnly) = UseState(false);

        var visibleItems = UseMemo(
            () => showAItemsOnly
                ? Items.Where(item => item.Contains('a', StringComparison.OrdinalIgnoreCase)).ToArray()
                : Items,
            showAItemsOnly);

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            (TitleBar("Tabbed Filter App") with
            {
                Subtitle = showAItemsOnly ? "Showing strings that contain \"a\"" : "Showing all strings"
            }).Grid(row: 0),
            TabView(
                Tab("Strings", ListTab(visibleItems, showAItemsOnly, setShowAItemsOnly)) with { IsClosable = false },
                Tab("Summary", SummaryTab(visibleItems.Length, Items.Length, showAItemsOnly)) with { IsClosable = false }
            ).Grid(row: 1)
        ).RequestedTheme(ElementTheme.Default);
    }

    static Element ListTab(string[] visibleItems, bool showAItemsOnly, Action<bool> setShowAItemsOnly) =>
        Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            HStack(12,
                Button(showAItemsOnly ? "Show all strings" : "Filter strings", () => setShowAItemsOnly(!showAItemsOnly)),
                TextBlock(showAItemsOnly ? "Filtered by strings containing \"a\"" : "No filter applied")
                    .Foreground(SecondaryText)
                    .VAlign(VerticalAlignment.Center)
            ).Margin(24, 20, 24, 12).Grid(row: 0),
            ListView(
                visibleItems.ToList().AsReadOnly(),
                item => item,
                (item, _) => TextBlock(item).Margin(8, 4)
            ).SelectionMode(ListViewSelectionMode.None)
             .Margin(24, 0, 24, 24)
             .Grid(row: 1)
        );

    static Element SummaryTab(int visibleCount, int totalCount, bool showAItemsOnly) =>
        Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto],
            VStack(8,
                TextBlock("List summary").FontSize(20).SemiBold(),
                TextBlock($"{visibleCount} of {totalCount} strings visible"),
                TextBlock(showAItemsOnly ? "The filter is active." : "The filter is not active.")
                    .Foreground(SecondaryText)
            ).Margin(24).Grid(row: 0)
        );
}

