{
    static readonly ListItem[] Items =
    [
        new("Apple", "Fruit", "A crisp fruit that works well as a snack."),
        new("Apricot", "Fruit", "A small stone fruit with a soft orange color."),
        new("Broccoli", "Vegetable", "A green vegetable often served steamed or roasted."),
        new("Carrot", "Vegetable", "A sweet root vegetable with a bright orange color."),
        new("Blueberry", "Fruit", "A small berry commonly used in breakfasts and desserts."),
    ];

    public override Element Render()
    {
        var (showFruitOnly, setShowFruitOnly) = UseState(false);
        var (selectedName, setSelectedName) = UseState(Items[0].Name);

        var filteredItems = Items
            .Where(item => !showFruitOnly || item.Category == "Fruit")
            .ToArray();
        var selectedItem = Items.First(item => item.Name == selectedName);

        return Grid(
            columns: [GridSize.Px(320), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
