        new("Carrot", "Vegetable", "A sweet root vegetable with a bright orange color."),
        new("Blueberry", "Fruit", "A small berry commonly used in breakfasts and desserts."),
    ];

    public override Element Render()
    {
        var (showFruitOnly, setShowFruitOnly) = UseState(false);
        var (selectedName, setSelectedName) = UseState(Items[0].Name);

        var filteredItems = Items
            .Where(item => !showFruitOnly || item.Category == "Fruit")
            .ToArray();
        var selectedItem = Items.First(item => item.Name == selectedName);

        return Grid(
            columns: [GridSize.Px(320), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            Heading("Items")
                .Grid(row: 0, column: 0, columnSpan: 2),
            Border(
                VStack(12,
                    Button(
                        showFruitOnly ? "Show all strings" : "Filter to fruit strings",
                        () =>
                        {
                            var nextFilter = !showFruitOnly;
                            setShowFruitOnly(nextFilter);

                            if (nextFilter && selectedItem.Category != "Fruit")
                            {
                                setSelectedName(Items.First(item => item.Category == "Fruit").Name);
                            }
                        })
                        .AutomationName(showFruitOnly ? "Show all strings" : "Filter to fruit strings")
                        .HAlign(HorizontalAlignment.Left),
                    ListView(
                        filteredItems,
                        item => item.Name,
                        (item, _) => Button(item.Name, () => setSelectedName(item.Name))
                            .HAlign(HorizontalAlignment.Stretch)
                            .AutomationName($"Select {item.Name}")
                            .WithKey(item.Name))
                        .AutomationName("Filtered strings")))
                .Padding(16)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
                .Grid(row: 1, column: 0),
            Border(
                VStack(12,
                    SubHeading(selectedItem.Name),
                    Caption(selectedItem.Category).Foreground(Theme.SecondaryText),
                    TextBlock(selectedItem.Description).TextWrapping()))
                .Padding(24)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
                .Grid(row: 1, column: 1))
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }
}

