using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

ReactorApp.Run<App>("Master Detail", width: 900, height: 600);

class App : Component
{
    private static readonly string[] AllItems =
    [
        "Alpha",
        "Beta",
        "Gamma",
        "Delta",
        "Epsilon",
        "Zeta",
        "Eta",
        "Theta"
    ];

    public override Element Render()
    {
        var (showShortOnly, setShowShortOnly) = UseState(false);
        var (selected, setSelected) = UseState(AllItems[0]);

        var filteredItems = AllItems
            .Where(item => !showShortOnly || item.Length <= 4)
            .ToArray();

        var selectedItem = filteredItems.Contains(selected)
            ? selected
            : filteredItems.FirstOrDefault() ?? string.Empty;
        var selectedIndex = Array.IndexOf(filteredItems, selectedItem);

        return Grid(
            columns: [GridSize.Star(2), GridSize.Star(3)],
            rows: [GridSize.Auto, GridSize.Star()],
            [
                VStack(4,
                    Heading("Strings"),
                    CheckBox(showShortOnly, setShowShortOnly, "Show only short strings"))
                .Grid(row: 0, column: 0)
                .Margin(24, 24, 12, 12),

                SubHeading("Detail")
                    .Grid(row: 0, column: 1)
                    .Margin(12, 24, 24, 12),

                Border(
                    ListBox(filteredItems, selectedIndex, index =>
                    {
                        if (index >= 0 && index < filteredItems.Length)
                        {
                            setSelected(filteredItems[index]);
                        }
                    })
                    .SelectionMode(SelectionMode.Single))
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .Padding(8)
                .Grid(row: 1, column: 0)
                .Margin(24, 0, 12, 24),

                Border(
                    VStack(12,
                        Caption("Selected string").Foreground(Theme.SecondaryText),
                        Heading(string.IsNullOrEmpty(selectedItem) ? "No string selected" : selectedItem),
                        TextBlock(string.IsNullOrEmpty(selectedItem)
                            ? "No items match the current filter."
                            : $"The selected string is \"{selectedItem}\"."))
                    .Padding(24))
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .Grid(row: 1, column: 1)
                .Margin(12, 0, 24, 24)
            ])
        .Background(Theme.SolidBackground)
        .RequestedTheme(ElementTheme.Default);
    }
}

