using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Core.Theme;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master-detail filter", width: 900, height: 600);

record CatalogItem(string Name, string Group, string Description);

class App : Component
{
    static readonly string[] Filters = ["All", "Fruit", "Vegetable", "Herb"];

    static readonly CatalogItem[] Items =
    [
        new("Apple", "Fruit", "A crisp fruit that works well for snacks and pies."),
        new("Banana", "Fruit", "A soft, sweet fruit often used in smoothies."),
        new("Blueberry", "Fruit", "A small berry commonly used in breakfasts and desserts."),
        new("Carrot", "Vegetable", "A crunchy root vegetable with a bright orange color."),
        new("Cucumber", "Vegetable", "A cool vegetable often served fresh in salads."),
        new("Spinach", "Vegetable", "A leafy green that can be eaten raw or cooked."),
        new("Basil", "Herb", "A fragrant herb commonly used with tomato and pasta dishes."),
        new("Mint", "Herb", "A refreshing herb used in drinks, salads, and desserts."),
        new("Rosemary", "Herb", "A woody herb that pairs well with roasted vegetables.")
    ];

    public override Element Render()
    {
        var (filterIndex, setFilterIndex) = UseState(0);
        var (selectedName, setSelectedName) = UseState(Items[0].Name);

        var activeFilter = Filters[filterIndex];
        var filteredItems = Items
            .Where(item => activeFilter == "All" || item.Group == activeFilter)
            .ToArray();
        var selectedItem = filteredItems.FirstOrDefault(item => item.Name == selectedName)
            ?? filteredItems.FirstOrDefault();

        return Grid(
            ["320", "*"],
            ["Auto", "*"],
            [
                (TitleBar("Catalog") with { Subtitle = "Master-detail filter" })
                    .Grid(0, 0, columnSpan: 2),

                Border(
                    VStack(12,
                        ComboBox(Filters, filterIndex, setFilterIndex)
                            .Header("Filter")
                            .Placeholder("Choose a category"),
                        Caption($"{filteredItems.Length} item{(filteredItems.Length == 1 ? "" : "s")}")
                            .Foreground(SecondaryText),
                        ListView(filteredItems, item => item.Name, (item, _) =>
                            ItemRow(item, selectedItem?.Name == item.Name, setSelectedName)))
                    .Padding(16))
                .Background(CardBackground)
                .WithBorder(CardStroke, 1)
                .CornerRadius(8)
                .Margin(16)
                .Grid(1, 0),

                Border(Detail(selectedItem))
                    .Background(CardBackground)
                    .WithBorder(CardStroke, 1)
                    .CornerRadius(8)
                    .Margin(0, 16, 16, 16)
                    .Grid(1, 1)
            ])
            .Background(SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }

    static Element ItemRow(CatalogItem item, bool isSelected, Action<string> selectItem) =>
        Border(
            VStack(4,
                TextBlock(item.Name).Bold().Foreground(PrimaryText),
                Caption(item.Group).Foreground(SecondaryText))
