using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Core.Theme;

ReactorApp.Run<App>("Filtered list", width: 720, height: 480);

enum Filter
{
    All,
    Short,
    Long,
}

class App : Component
{
    private static readonly string[] Items =
    [
        "Mercury",
        "Venus",
        "Earth",
        "Mars",
        "Jupiter",
        "Saturn",
        "Uranus",
        "Neptune",
    ];

    public override Element Render()
    {
        var (filter, setFilter) = UseState(Filter.All);

        var filteredItems = Items
            .Where(item => filter switch
            {
                Filter.Short => item.Length <= 5,
                Filter.Long => item.Length > 5,
                _ => true,
            })
            .ToArray();

        return Grid(
            [GridSize.Px(220), GridSize.Star],
            [GridSize.Auto, GridSize.Star],
            [
                Heading("Planet list")
                    .Grid(row: 0, column: 0, columnSpan: 2)
                    .Margin(0, 0, 0, 16),

                VStack(8,
                    SubHeading("Filter"),
                    RadioButton("All", filter == Filter.All, isChecked =>
                    {
                        if (isChecked)
                        {
                            setFilter(Filter.All);
                        }
                    }, "planet-filter"),
                    RadioButton("Short names", filter == Filter.Short, isChecked =>
                    {
                        if (isChecked)
                        {
                            setFilter(Filter.Short);
                        }
                    }, "planet-filter"),
                    RadioButton("Long names", filter == Filter.Long, isChecked =>
                    {
                        if (isChecked)
                        {
                            setFilter(Filter.Long);
                        }
                    }, "planet-filter"))
                    .Grid(row: 1, column: 0)
                    .Margin(0, 0, 24, 0),

                BuildList(filteredItems)
                    .Grid(row: 1, column: 1),
            ])
            .Padding(24)
            .Background(SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }

    private static Element BuildList(IReadOnlyList<string> items)
    {
        var rows = Enumerable.Repeat(GridSize.Auto, items.Count).ToArray();
        var children = items
            .Select((item, index) =>
                Border(TextBlock(item))
                    .Grid(row: index)
                    .Padding(12)
                    .Margin(0, 0, 0, 8)
                    .Background(CardBackground)
                    .WithBorder(CardStroke)
                    .CornerRadius(8)
                    .WithKey(item))
            .ToArray<Element>();

        return Grid([GridSize.Star], rows, children);
    }
}

