using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Core.Theme;

ReactorApp.Run<App>("String Filter Tabs", width: 900, height: 600);

record ListItem(string Text, string Category);

class App : Component
{
    static readonly IReadOnlyList<ListItem> Items =
    [
        new("Apple", "Fruit"),
        new("Banana", "Fruit"),
        new("Carrot", "Vegetable"),
        new("Cucumber", "Vegetable"),
        new("Grape", "Fruit"),
        new("Pepper", "Vegetable")
    ];

    static readonly string[] Categories = ["All", "Fruit", "Vegetable"];

    public override Element Render() =>
        TabView(
            Tab("Filtered list", Component<FilteredListTab>()),
            Tab("All strings", AllStringsTab())
        )
        .ShowAddButton(false);

    static Element AllStringsTab() =>
        Border(
            Grid([GridSize.Star()], [GridSize.Auto, GridSize.Star()],
                Heading("All strings").Grid(row: 0),
                ListView(
