using Microsoft.UI.Xaml;

ReactorApp.Run<App>("Dialog Flow", width: 720, height: 520);

class App : Component
{
    private static readonly IReadOnlyList<string> Items =
    [
        "Alpha",
        "Apricot",
        "Blue",
        "Cedar",
        "Cranberry",
        "Delta",
        "Fig",
        "Grape",
        "Juniper",
        "Kiwi",
        "Mango",
        "Pineapple"
    ];

    public override Element Render()
    {
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (showShortOnly, setShowShortOnly) = UseState(false);
        var filteredItems = Items
            .Where(item => !showShortOnly || item.Length <= 5)
            .ToList()
            .AsReadOnly();

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            VStack(12,
                Heading("String filter dialog"),
                TextBlock("Open the dialog, then use the toggle to filter the list."),
                Button("Open dialog", () => setDialogOpen(true))
            ).Grid(row: 0),
            ContentDialog(
                "Filter strings",
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Auto, GridSize.Star],
                    ToggleSwitch(
                        showShortOnly,
                        setShowShortOnly,
                        onContent: "Short strings only",
                        offContent: "All strings"
                    ).Grid(row: 0),
                    TextBlock($"{filteredItems.Count} strings shown").Grid(row: 1),
                    ListView(
                        filteredItems,
                        item => item,
                        (item, index) => Grid(
                            columns: [GridSize.Auto, GridSize.Star()],
                            rows: [GridSize.Auto],
                            TextBlock($"{index + 1}.").Grid(column: 0),
                            TextBlock(item).Grid(column: 1)
                        )
                    ).Height(260).Grid(row: 2)
                ),
                "Done"
            ) with
            {
                IsOpen = isDialogOpen,
                OnClosed = _ => setDialogOpen(false),
            }
        ).Padding(32).RequestedTheme(ElementTheme.Default);
    }
}

