using Microsoft.UI.Xaml;

ReactorApp.Run<App>("Master Detail", width: 900, height: 600);

record CustomerRecord(string Id, string Name);

class App : Component
{
    public override Element Render()
    {
        var (records, setRecords) = UseState<IReadOnlyList<CustomerRecord>>(
        [
            new("alpha", "Alpha record"),
            new("bravo", "Bravo record"),
            new("charlie", "Charlie record")
        ]);
        var (selectedId, setSelectedId) = UseState("alpha");
        var (draftName, setDraftName) = UseState("Alpha record");

        var selectedRecord = records.First(record => record.Id == selectedId);

        void SelectRecord(CustomerRecord record)
        {
            setSelectedId(record.Id);
            setDraftName(record.Name);
        }

        void SaveRecord()
        {
            setRecords(records
                .Select(record => record.Id == selectedId
                    ? record with { Name = draftName }
                    : record)
                .ToArray());
        }

        return Grid(
            columns: [GridSize.Px(260), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],

            Heading("Records")
                .Margin(24, 20, 24, 12)
                .Grid(row: 0, column: 0, columnSpan: 2),

            Border(
                VStack(8, records.Select(record =>
                    Button(record.Name, () => SelectRecord(record))
                        .HorizontalAlignment(HorizontalAlignment.Stretch)
                        .WithKey(record.Id))
                    .ToArray<Element?>())
                .Padding(16))
            .Margin(24, 0, 12, 24)
            .Grid(row: 1, column: 0),

            Border(
                VStack(12,
                    SubHeading(selectedRecord.Name),
                    TextBlock("Edit the selected record string, then press the button to save it."),
                    TextField(draftName, setDraftName, placeholder: "Record name"),
                    Button("Save record", SaveRecord)
                        .HorizontalAlignment(HorizontalAlignment.Left)))
            .Padding(24)
            .Margin(12, 0, 24, 24)
            .Grid(row: 1, column: 1))
        .RequestedTheme(ElementTheme.Default);
    }
}

