﻿using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;

ReactorApp.Run<App>("DataGrid Editor", width: 900, height: 600);

record EditableRecord(string Id, string Value);

class App : Component
{
    public override Element Render()
    {
        var (value, setValue) = UseState("Editable string");
        var source = new ListDataSource<EditableRecord>(
            [new EditableRecord("record", value)],
            record => record.Id);

        FieldDescriptor[] columns =
        [
            Column<EditableRecord>(
                nameof(EditableRecord.Value),
                record => record.Value,
                editable: true,
                displayName: "String",
                width: 420)
        ];

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            Heading("Edit record").Grid(row: 0),
            Border(
                    DataGrid(
                        source,
                        columns,
                        onRowChanged: (_, record) =>
                        {
                            setValue(record.Value);
                            return Task.CompletedTask;
                        },
                        editable: true,
                        editMode: EditMode.Cell))
                .Padding(12)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
                .Grid(row: 1))
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }
}

