using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;
using ReactorSelectionMode = Microsoft.UI.Reactor.Controls.SelectionMode;

ReactorApp.Run<MasterDetailApp>("Master Detail", width: 900, height: 560);

record DetailRecord(int Id, string Text);

sealed class DetailRecordSource(List<DetailRecord> records)
    : ListDataSource<DetailRecord>(
        records,
        record => new RowKey(record.Id.ToString()),
        true);

sealed class MasterDetailApp : Component
{
    public override Element Render()
    {
        var (records, setRecords) = UseState<IReadOnlyList<DetailRecord>>([
            new(1, "First record"),
            new(2, "Second record"),
            new(3, "Third record")
        ]);
        var (selectedId, setSelectedId) = UseState<int?>(1);

        var selected = records.FirstOrDefault(record => record.Id == selectedId) ?? records.First();
        var source = new DetailRecordSource(records.ToList());

        Task CommitRow(RowKey _, DetailRecord updated)
        {
            setRecords([.. records.Select(record => record.Id == updated.Id ? updated : record)]);
            return Task.CompletedTask;
        }

        void SelectRecord(IReadOnlySet<RowKey> keys)
        {
            var selectedRecord = records.FirstOrDefault(record => keys.Contains(new RowKey(record.Id.ToString())));
            if (selectedRecord is not null)
            {
                setSelectedId(selectedRecord.Id);
            }
        }

        void UpdateSelectedText(string value)
        {
            setRecords([.. records.Select(record =>
                record.Id == selected.Id ? record with { Text = value } : record)]);
        }

        return Grid(
            columns: [GridSize.Star(2), GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Star()],
            Heading("Records").Grid(0, 0),
            Heading("Detail").Grid(0, 1),
            Border(
                DataGrid(
                    source,
                    AutoColumns<DetailRecord>(overrides: field => field.Name switch
                    {
                        nameof(DetailRecord.Id) => field with
                        {
                            DisplayName = "ID",
                            IsReadOnly = true,
                            Width = 80,
                            Flex = 0
                        },
                        nameof(DetailRecord.Text) => field with
                        {
                            DisplayName = "Text",
                            Width = 360,
                            Flex = 1
                        },
                        _ => field
                    }),
                    selectionMode: ReactorSelectionMode.Single,
                    onSelectionChanged: SelectRecord,
                    onRowChanged: CommitRow,
                    editable: true,
                    editMode: EditMode.Cell,
                    emptyTemplate: TextBlock("No records"))
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(8)
            .Padding(8)
            .Grid(1, 0),
            Border(
                VStack(12,
                    TextBlock($"Record {selected.Id}")
                        .Foreground(Theme.SecondaryText),
                    TextField(selected.Text, UpdateSelectedText, header: "Text")
                        .TextWrapping(TextWrapping.Wrap),
                    TextBlock("Edit the selected record here or directly in the grid.")
                        .Foreground(Theme.TertiaryText))
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(8)
            .Padding(16)
            .Grid(1, 1)
        )
        .Padding(20)
        .Background(Theme.SolidBackground)
        .RequestedTheme(ElementTheme.Default)
        .Set(grid =>
        {
            grid.ColumnSpacing = 16;
            grid.RowSpacing = 12;
        });
    }
}

