using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Record Dialog Grid", width: 760, height: 520);

sealed record EditableRecord(string Id, string Text);

sealed record AppState(EditableRecord Record, EditableRecord Draft, bool IsDialogOpen)
{
    public static AppState Initial { get; } = new(
        new EditableRecord("record", "Editable string value"),
        new EditableRecord("record", "Editable string value"),
        false);
}

abstract record AppAction;
sealed record OpenDialog : AppAction;
sealed record CloseDialog : AppAction;
sealed record UpdateDraft(EditableRecord Record) : AppAction;
sealed record SaveDraft : AppAction;

static class AppReducer
{
    public static AppState Reduce(AppState state, AppAction action) =>
        action switch
        {
            OpenDialog => state with
            {
                Draft = state.Record,
                IsDialogOpen = true
            },

            CloseDialog => state with
            {
                Draft = state.Record,
                IsDialogOpen = false
            },

            UpdateDraft update => state with { Draft = update.Record },

            SaveDraft => state with
            {
                Record = state.Draft,
                IsDialogOpen = false
            },

            _ => state
        };
}

class App : Component
{
    static readonly IReadOnlyList<FieldDescriptor> Columns =
    [
        Column<EditableRecord>(
                nameof(EditableRecord.Text),
                record => record.Text,
                editable: true,
                displayName: "String value")
            .Width(null, 240, null, 1)
    ];

    public override Element Render()
    {
        var (state, dispatch) = UseReducer<AppState, AppAction>(AppReducer.Reduce, AppState.Initial);

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Star()],
                Heading("Record editor")
                    .Grid(0, 0),
                Border(
                        VStack(12,
                            Caption("Current record").Foreground(Theme.SecondaryText),
                            TextBlock(state.Record.Text),
                            Button("Edit in dialog", () => dispatch(new OpenDialog()))))
                    .Padding(16)
                    .CornerRadius(12)
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .Margin(0, 16, 0, 0)
                    .Grid(1, 0),
                RenderDialog(state, dispatch))
            .Padding(24)
            .Background(Theme.SolidBackground);
    }

    static Element RenderDialog(AppState state, Action<AppAction> dispatch)
    {
        var source = new ListDataSource<EditableRecord>(
            [state.Draft],
            record => new RowKey(record.Id),
            true);

        return ContentDialog(
            "Edit record",
            Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Px(160)],
                Caption("Edit the string cell, then save the dialog.")
                    .Foreground(Theme.SecondaryText)
                    .Grid(0, 0),
                DataGrid(
                        source,
                        Columns,
                        onRowChanged: (_, record) =>
                        {
                            dispatch(new UpdateDraft(record));
                            return Task.CompletedTask;
                        },
                        editable: true,
                        editMode: EditMode.Cell,
                        emptyTemplate: TextBlock("No record to edit"))
                    .Grid(1, 0)),
            primaryButtonText: "Save") with
        {
            IsOpen = state.IsDialogOpen,
            SecondaryButtonText = "Cancel",
            DefaultButton = ContentDialogButton.Primary,
            OnClosed = result =>
            {
                dispatch(result == ContentDialogResult.Primary ? new SaveDraft() : new CloseDialog());
            }
        };
    }
}

