using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Tabbed Record Editor", width: 560, height: 420);

record EditableRecord(string Text);

class App : Component
{
    public override Element Render()
    {
        var (record, setRecord) = UseState(new EditableRecord("Default record text"));
        var (isEditing, setIsEditing) = UseState(false);

        void UpdateText(string text) =>
            setRecord(record with { Text = text });

        var editor = Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Star()],
            ToggleSwitch(
                isEditing,
                setIsEditing,
                onContent: "Editing",
                offContent: "Viewing",
                header: "Edit mode")
                .Grid(0, 0),
            (isEditing
                ? TextField(record.Text, UpdateText, placeholder: "Record text")
                    .Header("Record text")
                    .AutomationName("Record text")
                : Border(
                    TextBlock(record.Text)
                        .Foreground(Theme.PrimaryText)
                )
                .Background(Theme.LayerFill)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(12))
                .Grid(1, 0),
            TextBlock(isEditing ? "Toggle off to review the saved record." : "Toggle on to edit the record.")
                .Foreground(Theme.SecondaryText)
                .Grid(2, 0)
        );

        var summary = Grid(
            columns: [GridSize.Auto, GridSize.Star()],
            rows: [GridSize.Auto],
            TextBlock("Record text")
                .SemiBold()
                .Grid(0, 0),
            TextBlock(record.Text)
                .Foreground(Theme.PrimaryText)
                .Grid(0, 1)
        );

        return Border(
            TabView([
                Tab("Editor", editor),
                Tab("Summary", summary)
            ])
        )
        .Padding(20)
        .Background(Theme.SolidBackground);
    }
}

