using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<CheckBoxFormPage>("CheckBox Form", width: 460, height: 320);

class CheckBoxFormPage : Component
{
    public override Element Render()
    {
        var (formText, setFormText) = UseState("Hello from Reactor");
        var (submitOnCheck, setSubmitOnCheck) = UseState(false);
        var (submittedText, setSubmittedText) = UseState("");

        void ToggleSubmit(bool isChecked)
        {
            setSubmitOnCheck(isChecked);
            setSubmittedText(isChecked ? formText.Trim() : "");
        }

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star],
            Heading("CheckBox form")
                .Grid(row: 0, column: 0),
            Border(
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Auto],
                    TextField(
                            formText,
                            value =>
                            {
                                setFormText(value);
                                if (submitOnCheck)
                                {
                                    setSubmittedText(value.Trim());
                                }
                            },
                            placeholder: "Enter a string",
                            header: "String")
                        .Grid(row: 0, column: 0),
                    CheckBox(
                            submitOnCheck,
                            ToggleSubmit,
                            label: "Submit this string")
                        .Margin(0, 16, 0, 0)
                        .Grid(row: 1, column: 0),
                    Caption("Submitted value")
                        .Foreground(Theme.SecondaryText)
                        .Margin(0, 20, 0, 4)
                        .Grid(row: 2, column: 0),
                    TextBlock(string.IsNullOrEmpty(submittedText) ? "Not submitted" : submittedText)
                        .Foreground(string.IsNullOrEmpty(submittedText) ? Theme.SecondaryText : Theme.PrimaryText)
                        .TextWrapping()
                        .Grid(row: 3, column: 0)
                )
            )
            .Padding(20)
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(12)
            .Margin(0, 16, 0, 0)
            .Grid(row: 1, column: 0)
        )
        .Padding(24)
        .Background(Theme.SubtleFill);
    }
}

