using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("ComboBox Form", width: 420, height: 320);

sealed class App : Component
{
    private static readonly string[] Choices =
    [
        "North",
        "South",
        "East",
        "West",
    ];

    public override Element Render()
    {
        var (selectedIndex, setSelectedIndex) = UseState(-1);
        var (submittedValue, setSubmittedValue) = UseState<string?>(null);
        var selectedValue = selectedIndex >= 0 ? Choices[selectedIndex] : string.Empty;

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Auto(), GridSize.Auto(), GridSize.Star()],
            Heading("ComboBox form")
                .Grid(0, 0),

            TextBlock("Choose a string, then submit the form.")
                .Foreground(Theme.SecondaryText)
                .Margin(0, 4, 0, 20)
                .Grid(1, 0),

            Grid(
                columns: [GridSize.Star(), GridSize.Auto()],
                rows: [GridSize.Auto()],
                ComboBox(Choices, selectedIndex, setSelectedIndex)
                    .Header("String")
                    .Placeholder("Select a string")
                    .MinWidth(220)
                    .Grid(0, 0),

                Button("Submit", () => setSubmittedValue(selectedValue))
                    .Disabled(selectedIndex < 0)
                    .Margin(12, 0, 0, 0)
                    .VAlign(VerticalAlignment.Bottom)
                    .Grid(0, 1))
                .Margin(0, 0, 0, 20)
                .Grid(2, 0),

            Border(
                TextBlock(submittedValue is null
                        ? "No string submitted yet."
                        : $"Submitted: {submittedValue}")
                    .Foreground(submittedValue is null ? Theme.SecondaryText : Theme.PrimaryText))
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
                .Padding(16)
                .Grid(3, 0))
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }
}

