using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<StringGridApp>("String Grid", width: 720, height: 480);

record SubmittedString(int Id, string Value);

class StringGridApp : Component
{
    public override Element Render()
    {
        var (entry, setEntry) = UseState("");
        var (submitted, setSubmitted) = UseState<IReadOnlyList<SubmittedString>>([]);

        var canSubmit = !string.IsNullOrWhiteSpace(entry);
        var rows = submitted.ToList();
        var source = new ListDataSource<SubmittedString>(
            rows,
            row => new RowKey(row.Id.ToString()),
            false);

        void Submit()
        {
            var value = entry.Trim();
            if (value.Length == 0)
                return;

            var nextId = submitted.Count == 0 ? 1 : submitted.Max(row => row.Id) + 1;
            setSubmitted([.. submitted, new SubmittedString(nextId, value)]);
            setEntry("");
        }

        return Border(
            Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Star()],

                VStack(12,
                    Heading("Submit a string"),
                    Grid(
                        columns: [GridSize.Star(), GridSize.Auto],
                        rows: [GridSize.Auto],
                        TextField(entry, setEntry, placeholder: "Enter a string", header: "String")
                            .Grid(0, 0),
                        Button("Submit", Submit)
                            .Disabled(!canSubmit)
                            .VAlign(VerticalAlignment.Bottom)
                            .Grid(0, 1)
                    ) with
                    {
                        ColumnSpacing = 12
                    }
                ).Grid(0, 0),

                Border(
                    DataGrid(
                        source,
                        [
                            Column<SubmittedString>("Value", row => row.Value, displayName: "Submitted String")
                                .Width(width: 360, flex: 1)
                        ],
                        emptyTemplate: TextBlock("Submit a string to add the first row.")
                            .Foreground(Theme.SecondaryText),
                        rowHeight: 44)
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(12)
                .Grid(1, 0)
            ) with
            {
                RowSpacing = 20
            }
        )
        .Background(Theme.SolidBackground)
        .Padding(24);
    }
}

