using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

ReactorApp.Run<App>("DialogSliderApp", width: 900, height: 600);

class App : Component
{
    public override Element Render()
    {
        var (dialogOpen, setDialogOpen) = UseState(false);
        var (formText, setFormText) = UseState("");
        var (submitValue, setSubmitValue) = UseState(0.0);
        var (submittedText, setSubmittedText) = UseState("No string submitted yet.");

        void Submit()
        {
            var value = string.IsNullOrWhiteSpace(formText) ? "(empty string)" : formText;
            setSubmittedText($"Submitted: {value}");
            setSubmitValue(0.0);
            setDialogOpen(false);
        }

        var dialogContent =
            Grid(
                new[] { GridSize.Auto, GridSize.Star() },
                new[] { GridSize.Auto, GridSize.Auto, GridSize.Auto },
                TextBlock("String").Grid(row: 0, column: 0).VAlign(VerticalAlignment.Center),
                TextField(formText, setFormText, placeholder: "Enter a string")
                    .Grid(row: 0, column: 1),
                TextBlock("Slide to submit").Grid(row: 1, column: 0).VAlign(VerticalAlignment.Center),
                Slider(
                        submitValue,
                        min: 0,
                        max: 100,
                        onChanged: value =>
                        {
                            setSubmitValue(value);
                            if (value >= 100)
                            {
                                Submit();
                            }
                        })
                    with
                    {
                        Header = "Submit",
                        StepFrequency = 1
                    }
                    .Grid(row: 1, column: 1),
                TextBlock($"{submitValue:0}%").Grid(row: 2, column: 1))
            with
            {
                RowSpacing = 12,
                ColumnSpacing = 16
            };

        return Grid(
                new[] { GridSize.Star() },
                new[] { GridSize.Auto, GridSize.Auto, GridSize.Auto },
                TextBlock("Dialog slider form").FontSize(28).Bold().Grid(row: 0, column: 0),
                TextBlock(submittedText).Margin(0, 12).Grid(row: 1, column: 0),
                Button("Open form", () =>
                    {
                        setSubmitValue(0.0);
                        setDialogOpen(true);
                    })
                    .Grid(row: 2, column: 0),
                ContentDialog("Submit a string", dialogContent, primaryButtonText: "Submit")
                    with
                    {
                        IsOpen = dialogOpen,
                        CloseButtonText = "Cancel",
                        DefaultButton = ContentDialogButton.Primary,
                        OnClosed = result =>
                        {
                            if (result == ContentDialogResult.Primary)
                            {
                                Submit();
                            }
                            else
                            {
                                setSubmitValue(0.0);
                                setDialogOpen(false);
                            }
                        }
                    })
            .Padding(32)
            .RequestedTheme(ElementTheme.Default);
    }
}

