                    )
                    .Spacing(12)
                    .Padding(32)
                    .Width(320)
                    .Grid(row: 1)
            );
    }

    static Element RadioOption(string text, bool isChecked, Action onSelected) =>
        ToggleButton(new Command(text, onSelected), isChecked)
            .Set(control =>
            {
                if (control is ToggleButton toggleButton)
                {
                    toggleButton.Content = text;
                    toggleButton.Style = (Style)Application.Current.Resources["DefaultRadioButtonStyle"];
                }
            });
