ReactorApp.Run<App>("Radio Form", width: 640, height: 420);

class App : Component
{
    public override Element Render()
    {
        var (selected, setSelected) = UseState("Alpha");
        var (submitted, setSubmitted) = UseState("");

        return Grid(
                [GridSize.Star(1)],
                [GridSize.Star(1), GridSize.Auto, GridSize.Star(1)],
                VStack(
                        Heading("Radio form"),
                        Text("Choose a value and submit it."),
                        RadioOption("Alpha", selected == "Alpha", () => setSelected("Alpha")),
                        RadioOption("Beta", selected == "Beta", () => setSelected("Beta")),
                        RadioOption("Gamma", selected == "Gamma", () => setSelected("Gamma")),
                        Button(new Command("Submit", () => setSubmitted(selected))),
                        Text(string.IsNullOrWhiteSpace(submitted) ? "Nothing submitted yet." : $"Submitted: {submitted}")
                    )
                    .Spacing(12)
                    .Padding(32)
                    .Width(320)
                    .Grid(row: 1)
            );
    }

    static Element RadioOption(string text, bool isChecked, Action onSelected) =>
        ToggleButton(new Command(text, onSelected), isChecked)
            .Set(control =>
            {
                if (control is ToggleButton toggleButton)
                {
                    toggleButton.Content = text;
                    toggleButton.Style = (Style)Application.Current.Resources["DefaultRadioButtonStyle"];
                }
            });
}

