class App : Component
{
    public override Element Render()
    {
        var (message, setMessage) = UseState("");
        var (submitted, setSubmitted) = UseState("");
        var (submitToggle, setSubmitToggle) = UseState(false);

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Auto],
            Text("Toggle Form")
                .Grid(row: 0)
                .Margin(0, 0, 0, 16),
            TextField(message, setMessage, placeholder: "Enter a string")
                .Grid(row: 1)
                .AutomationName("StringInput"),
            ToggleButton("Submit string", submitToggle, isChecked =>
                {
                    setSubmitToggle(isChecked);
                    if (isChecked)
                    {
                        setSubmitted(message);
                    }
                })
