using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Core.Theme;

ReactorApp.Run<App>("Reactor Master Detail", width: 900, height: 600);

record Entry(string Value);

class App : Component
{
    public override Element Render()
    {
        var (draft, setDraft) = UseState("");
        var (submitOn, setSubmitOn) = UseState(false);
        var (entries, setEntries) = UseState(new[] { new Entry("First item") });
        var (selectedIndex, setSelectedIndex) = UseState(0);

        var selected = entries.Length > 0 && selectedIndex >= 0 && selectedIndex < entries.Length
            ? entries[selectedIndex]
            : null;

        void Submit(bool isOn)
        {
            setSubmitOn(isOn);

            if (!isOn)
            {
                return;
            }

            var value = draft.Trim();
            if (value.Length == 0)
            {
                setSubmitOn(false);
                return;
            }

            var nextEntries = entries.Append(new Entry(value)).ToArray();
            setEntries(nextEntries);
            setSelectedIndex(nextEntries.Length - 1);
            setDraft("");
            setSubmitOn(false);
        }

        return Grid(
            columns: [GridSize.Px(280), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],

            TitleBar("Master detail") with { Subtitle = "Default theme" },

            Border(
                VStack(12,
                    SubHeading("Master"),
                    entries.Length == 0
                        ? Caption("Submit a string to add an item.")
                        : VStack(6, entries.Select((entry, index) =>
                            Button(entry.Value, () => setSelectedIndex(index))
                                .HAlign(HorizontalAlignment.Stretch)
                                .Disabled(index == selectedIndex)).ToArray())
                ).Padding(16)
            )
            .Background(CardBackground)
            .WithBorder(CardStroke, 1)
            .CornerRadius(8)
            .Margin(16)
            .Grid(row: 1, column: 0),

            Border(
                VStack(16,
                    SubHeading("Detail"),
                    selected is null
                        ? TextBlock("No item selected.")
                        : TextBlock($"Selected: {selected.Value}"),
                    TextField(draft, setDraft, placeholder: "String to submit")
                        .AutomationName("StringInput"),
                    ToggleButton("Submit string", submitOn, Submit)
                        .AutomationName("SubmitToggle")
                ).Padding(16)
            )
            .Background(CardBackground)
            .WithBorder(CardStroke, 1)
            .CornerRadius(8)
            .Margin(0, 16, 16, 16)
            .Grid(row: 1, column: 1)
        )
        .RequestedTheme(ElementTheme.Default)
        .Background(SystemControlBackgroundAltHighBrush);
    }
}

