using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;

ReactorApp.Run<App>("DataGrid Action Counter", width: 760, height: 480);

record ActionRow(string Id, string Action, int TriggerValue);

class App : Component
{
    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);
        var (triggerValue, setTriggerValue) = UseState(0);

        var source = new ListDataSource<ActionRow>(
            [new ActionRow("increment", "Edit this value to trigger the action", triggerValue)],
            row => row.Id);

        FieldDescriptor[] columns =
        [
            Column<ActionRow>(
                nameof(ActionRow.Action),
                row => row.Action,
                displayName: "DataGrid action",
                width: 320),
            Column<ActionRow>(
                nameof(ActionRow.TriggerValue),
                row => row.TriggerValue,
                editable: true,
                displayName: "Trigger value",
                width: 180)
        ];

        return Grid(
            columns: [GridSize.Star(), GridSize.Px(220)],
            rows: [GridSize.Star()],
            Border(
                    DataGrid(
                        source,
                        columns,
                        onRowChanged: (_, row) =>
                        {
                            setTriggerValue(row.TriggerValue);
                            setCounter(counter + 1);
                            return Task.CompletedTask;
                        },
                        editable: true,
                        editMode: EditMode.Cell))
                .Padding(12)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
                .Grid(row: 0, column: 0),
            Border(
                    VStack(
                            TextBlock("Action counter")
                                .Foreground(Theme.SecondaryText),
                            TextBlock(counter.ToString())
                                .FontSize(64)
                                .SemiBold()
                                .AutomationName("ActionCounter"))
                        .Spacing(12))
                .Padding(24)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
                .Grid(row: 0, column: 1))
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }
}

