using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail Counter", width: 920, height: 560);

record CounterAction(string Id, string Name, int Delta, string Description);

class App : Component
{
    static readonly CounterAction[] Actions =
    [
        new("increment-one", "Increment", 1, "Adds one to the counter."),
        new("increment-five", "Boost", 5, "Adds five to the counter."),
        new("decrement-one", "Decrement", -1, "Subtracts one from the counter.")
    ];

    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);
        var (selectedId, setSelectedId) = UseState(Actions[0].Id);
        var selectedAction = Actions.First(action => action.Id == selectedId);
        var source = new ListDataSource<CounterAction>(Actions, action => action.Id);

        FieldDescriptor[] columns =
        [
            Column<CounterAction>(
                nameof(CounterAction.Name),
                action => action.Name,
                displayName: "Action",
                width: 160),
            Column<CounterAction>(
                nameof(CounterAction.Delta),
                action => action.Delta,
                displayName: "Counter change",
                width: 140),
            Column<CounterAction>(
                nameof(CounterAction.Description),
                action => action.Description,
                displayName: "Detail",
                width: 280)
        ];

        void RunSelectedAction(IReadOnlySet<RowKey> selectedKeys)
        {
            var action = Actions.FirstOrDefault(action => selectedKeys.Contains(new RowKey(action.Id)));
            if (action is null)
                return;

            setSelectedId(action.Id);
            setCounter(counter + action.Delta);
        }

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            TitleBar("Master-detail counter") with
            {
                Subtitle = "Select a DataGrid row to run its counter action"
            },
