                            selectionMode: SelectionMode.Single,
                            onSelectionChanged: RunSelectedAction,
                            emptyTemplate: TextBlock("No actions available."))))
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(12)
                .Padding(16)
                .Margin(0, 0, 16, 0),
                Border(
                    VStack(16,
                        SubHeading("Detail"),
                        TextBlock(selectedAction.Name)
                            .FontSize(24)
                            .Foreground(Theme.PrimaryText),
                        TextBlock(selectedAction.Description)
                            .TextWrapping()
                            .Foreground(Theme.SecondaryText),
                        Caption("Current counter"),
                        TextBlock(counter.ToString())
                            .FontSize(48)
                            .Foreground(Theme.AccentText)))
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(12)
                .Padding(24)
                .Grid(column: 1))
            .Grid(row: 1)
            .Padding(24))
        .Background(Theme.SolidBackground)
        .RequestedTheme(ElementTheme.Default);
    }
}

