                    SubHeading("Dialog flow"),
                    TextBlock("Open the dialog, then select the radio option to increment the counter."),
                    Button("Open dialog", OpenDialog).AutomationName("OpenDialogButton")
                )
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(12)
                .Padding(24)
                .Grid(row: 2, column: 0),
            ContentDialog(
                "Choose an action",
                Grid(
                    columns: [GridSize.Star()],
