                    {
                        if (!isChecked)
                        {
                            return;
                        }

                        setCounter(counter + 1);
                        setActionSelected(true);
                    }, groupName: "DialogActions")
                        .Grid(row: 0, column: 0),
                    TextBlock($"Counter will be {counter + (isActionSelected ? 0 : 1)} after selection.")
                        .Foreground(Theme.SecondaryText)
                        .Grid(row: 1, column: 0)
                ),
                primaryButtonText: "Done"
            )
            {
                IsOpen = isDialogOpen,
                OnClosed = _ => setDialogOpen(false),
            }
        )
        .Padding(32)
        .RequestedTheme(ElementTheme.Default);
    }
}

