sealed class CounterDialogApp : Component
{
    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);
        var (isDialogOpen, setDialogOpen) = UseState(false);

        var dialogContent = Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Auto()],
            TextBlock($"Counter value: {counter}")
                .Foreground(Theme.PrimaryText)
                .Grid(row: 0),
            Button($"Increment counter to {counter + 1}", () => setCounter(counter + 1))
                .Grid(row: 1));

        dialogContent = dialogContent with { RowSpacing = 12 };

        var root = Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Auto(), GridSize.Auto()],
            Heading("Dialog counter")
                .Grid(row: 0),
            Caption("Open the dialog and use the button to update the bound counter state.")
                .Foreground(Theme.SecondaryText)
                .Grid(row: 1),
            Button($"Open dialog ({counter})", () => setDialogOpen(true))
                .Grid(row: 2),
            ContentDialog("Counter", dialogContent, primaryButtonText: "Done") with
            {
                IsOpen = isDialogOpen,
                DefaultButton = ContentDialogButton.Primary,
                OnClosed = _ => setDialogOpen(false),
            });

        return (root with { RowSpacing = 16 })
            .Padding(24)
            .Background(Theme.SolidBackground);
    }
}

