using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<MasterDetailApp>("Reactor Master Detail", width: 760, height: 420);

class MasterDetailApp : Component
{
    static readonly string[] CounterChoices =
    [
        "Zero",
        "One",
        "Two",
        "Three",
        "Four",
        "Five"
    ];

    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);

        return Grid(
            columns: [GridSize.Pixel(260), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            Heading("Counter master-detail").Grid(row: 0, column: 0, columnSpan: 2),
            MasterPane(counter, setCounter).Grid(row: 1, column: 0),
            DetailPane(counter).Grid(row: 1, column: 1)
        )
        .Padding(24)
        .Background(Theme.SolidBackground)
        .RequestedTheme(ElementTheme.Default);
    }

    static Element MasterPane(int counter, Action<int> setCounter) =>
        Border(
            VStack(12,
                SubHeading("Master"),
                TextBlock("Choose a counter value").Foreground(Theme.SecondaryText),
                ComboBox(CounterChoices, counter, setCounter)
                    .Header("Counter")
                    .Placeholder("Select a value")
                    .Width(180)
            )
        )
        .Padding(18)
        .CornerRadius(12)
        .Background(Theme.LayerFill)
        .WithBorder(Theme.CardStroke, 1)
        .Margin(0, 20, 16, 0);

    static Element DetailPane(int counter) =>
        Border(
            VStack(12,
                SubHeading("Detail"),
                TextBlock($"Counter: {counter}")
                    .FontSize(36)
                    .SemiBold(),
                TextBlock($"Selected item: {CounterChoices[counter]}")
                    .Foreground(Theme.SecondaryText)
            )
        )
        .Padding(24)
        .CornerRadius(12)
        .Background(Theme.CardBackground)
        .WithBorder(Theme.CardStroke, 1)
        .Margin(0, 20, 0, 0);
}

