ReactorApp.Run<App>("TabbedDataGridCounter", width: 900, height: 600);

record CounterRow(int Count);

class App : Component
{
    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);

        var rows = new List<CounterRow> { new(counter) };
        var source = new ListDataSource<CounterRow>(
            rows,
            row => new RowKey(nameof(CounterRow) + ":" + row.Count));

        var columns = new[]
        {
            new FieldDescriptor
            {
                Name = nameof(CounterRow.Count),
                DisplayName = "Counter",
                FieldType = typeof(int),
                GetValue = row => ((CounterRow)row).Count,
                IsReadOnly = true,
                Width = 160,
                Sortable = false,
                Filterable = false
            }
        };

        return TabView(
            Tab(
                "Counter",
                Grid(
                    ["*"],
                    ["Auto", "*"],
                    HStack(
                        Heading($"Counter: {counter}"),
                        Button("Increment", () => setCounter(counter + 1))
                    )
                    .Spacing(12)
                    .VerticalAlignment(VerticalAlignment.Center)
                    .Margin(16)
                    .Grid(row: 0),

                    DataGrid(
                        source,
                        columns,
                        rowHeight: 44,
                        emptyTemplate: TextBlock("No counter value"))
                    .Margin(16, 0, 16, 16)
                    .Grid(row: 1)))
        )
        .ShowAddButton(false)
        .RequestedTheme(ElementTheme.Default);
    }
}

