using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Counter master-detail", width: 900, height: 560);

sealed record CounterRow(int Value, string Name, bool IsCurrent);

sealed class App : Component
{
    public override Element Render()
    {
        var (counter, setCounter) = UseState(2);
        var rows = Enumerable.Range(0, 6)
            .Select(value => new CounterRow(value, $"Counter {value}", value == counter))
            .ToList();
        var source = new ListDataSource<CounterRow>(rows, row => row.Value);

        FieldDescriptor[] columns =
        [
            new()
            {
                Name = nameof(CounterRow.Value),
                DisplayName = "Value",
                FieldType = typeof(int),
                GetValue = row => ((CounterRow)row).Value,
                Width = 90
            },
            new()
            {
                Name = nameof(CounterRow.Name),
                DisplayName = "Name",
                FieldType = typeof(string),
                GetValue = row => ((CounterRow)row).Name,
                Flex = 1
            },
            new()
            {
                Name = nameof(CounterRow.IsCurrent),
                DisplayName = "Current",
                FieldType = typeof(bool),
                GetValue = row => ((CounterRow)row).IsCurrent,
                FormatValue = value => (bool)value ? "Yes" : "",
                Width = 110
            }
        ];

        return Grid(
                columns: [GridSize.Star(), GridSize.Px(280)],
                rows: [GridSize.Auto, GridSize.Star()],
                Heading("Counter master-detail")
                    .Margin(left: 24, top: 24, right: 24, bottom: 12)
                    .Grid(row: 0, column: 0, columnSpan: 2),
                Border(
                        DataGrid<CounterRow>(
                            source,
                            columns,
                            selectionMode: SelectionMode.Single,
                            onSelectionChanged: keys =>
                            {
                                if (keys.FirstOrDefault() is { Value: var value } && int.TryParse(value, out var selected))
                                {
                                    setCounter(selected);
                                }
                            },
                            rowHeight: 44,
                            emptyTemplate: TextBlock("No counter rows"))
                    )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(12)
                    .Padding(8)
                    .Margin(left: 24, top: 0, right: 12, bottom: 24)
                    .Grid(row: 1, column: 0),
                Border(
                        VStack(12,
                            SubHeading("Detail"),
                            TextBlock($"Selected counter: {counter}"),
                            TextBlock($"Double: {counter * 2}"),
                            TextBlock(rows[counter].IsCurrent ? "This row is bound to the counter state." : "")
                                .TextWrapping(TextWrapping.Wrap)
                                .Foreground(Theme.SecondaryText)
                        )
                        .Padding(16)
                    )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(12)
                    .Margin(left: 12, top: 0, right: 24, bottom: 24)
                    .Grid(row: 1, column: 1)
            )
            .Background(Theme.SubtleFill);
    }
