using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<CounterDialogApp>("Counter Dialog Grid", width: 720, height: 520);

record CounterRow(int Id, string StateName, int Value);

sealed class CounterDialogApp : Component
{
    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);
        var (isDialogOpen, setDialogOpen) = UseState(false);

        var rows = new[]
        {
            new CounterRow(1, "Counter", counter),
        };

        var source = new ListDataSource<CounterRow>(rows, row => (RowKey)row.Id);

        var columns = new FieldDescriptor[]
        {
            Column<CounterRow>("StateName", row => row.StateName, displayName: "State", width: 180),
            Column<CounterRow>("Value", row => row.Value, displayName: "Value", width: 120),
        };

        Element CounterGrid() =>
            DataGrid(
                source: source,
                columns: columns,
                rowHeight: 36
            ).Flex(grow: 1);

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star(), GridSize.Auto],
            (TitleBar("Counter Dialog") with
            {
                Subtitle = "DataGrid bound to component state",
            }).Grid(row: 0),
            Border(
                VStack(16,
                    Heading($"Counter: {counter}"),
                    TextBlock("Open the dialog to view the same state value in a DataGrid.")
                        .Foreground(Theme.SecondaryText),
                    CounterGrid(),
                    HStack(8,
                        Button("Increment", () => setCounter(counter + 1)),
                        Button("Open dialog", () => setDialogOpen(true)))
                ).Padding(20)
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Grid(row: 1),
            (ContentDialog(
                "Counter state",
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Star()],
                    HStack(8,
                        TextBlock($"Current value: {counter}").Flex(grow: 1),
                        Button("Increment", () => setCounter(counter + 1))
                    ).Grid(row: 0),
                    CounterGrid().Grid(row: 1)
                ) with
                {
                    RowSpacing = 12,
                    MinHeight = 260,
                },
                primaryButtonText: "Done"
            ) with
            {
                IsOpen = isDialogOpen,
                DefaultButton = ContentDialogButton.Primary,
                OnClosed = _ => setDialogOpen(false),
            }).Grid(row: 2)
        )
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }
}

