using Microsoft.UI.Xaml;

ReactorApp.Run<CounterMasterDetailApp>("Counter Master Detail", width: 900, height: 600);

record CounterItem(int Id, string Name, int Count);

class CounterMasterDetailApp : Component
{
    static readonly CounterItem[] InitialCounters =
    [
        new(1, "Alpha", 0),
        new(2, "Bravo", 1),
        new(3, "Charlie", 2),
        new(4, "Delta", 3),
        new(5, "Echo", 4),
    ];

    public override Element Render()
    {
        var (showPositiveOnly, setShowPositiveOnly) = UseState(false);
        var (selectedId, setSelectedId) = UseState(InitialCounters[0].Id);
        var (counters, setCounters) = UseState<IReadOnlyList<CounterItem>>(InitialCounters);

        var visibleCounters = counters
            .Where(counter => !showPositiveOnly || counter.Count > 0)
            .ToArray();

        var selectedCounter = visibleCounters.FirstOrDefault(counter => counter.Id == selectedId)
            ?? visibleCounters.First();

        var selectedIndex = Array.FindIndex(visibleCounters, counter => counter.Id == selectedCounter.Id);

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            TitleBar("Counter Master Detail").Grid(row: 0),
            Grid(
                columns: [GridSize.Pixel(280), GridSize.Star()],
                rows: [GridSize.Star()],
                MasterPane(showPositiveOnly, setShowPositiveOnly, visibleCounters, selectedIndex, setSelectedId)
                    .Grid(row: 0, column: 0),
                DetailPane(selectedCounter, counters, setCounters)
                    .Grid(row: 0, column: 1)
            )
            .Padding(24)
            .Grid(row: 1)
        )
        .RequestedTheme(ElementTheme.Default);
    }

    static Element MasterPane(
        bool showPositiveOnly,
        Action<bool> setShowPositiveOnly,
        CounterItem[] visibleCounters,
        int selectedIndex,
        Action<int> setSelectedId) =>
        Border(
            VStack(16,
                Heading("Counters"),
                CheckBox(showPositiveOnly, setShowPositiveOnly)
                    .Content("Show counters above zero"),
                ListBox(
                    visibleCounters.Select(counter => $"{counter.Name}: {counter.Count}").ToArray(),
                    selectedIndex,
                    index => setSelectedId(visibleCounters[index].Id)
                )
                .HAlign(HorizontalAlignment.Stretch)
            )
            .Padding(16)
        )
        .Background(Theme.CardBackground)
        .WithBorder(Theme.CardStroke)
        .CornerRadius(8)
        .Margin(0, 0, 16, 0);

    static Element DetailPane(
        CounterItem selectedCounter,
        IReadOnlyList<CounterItem> counters,
        Action<IReadOnlyList<CounterItem>> setCounters) =>
        Border(
            VStack(16,
                Heading(selectedCounter.Name),
                TextBlock($"Counter value: {selectedCounter.Count}")
                    .FontSize(24),
                Button("Increment", () =>
                    setCounters(counters
                        .Select(counter => counter.Id == selectedCounter.Id
                            ? counter with { Count = counter.Count + 1 }
                            : counter)
                        .ToArray()))
            )
            .Padding(24)
        )
        .Background(Theme.SolidBackground)
        .WithBorder(Theme.CardStroke)
        .CornerRadius(8);
}

