using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;

ReactorApp.Run<App>("TabbedDataGridCounter", width: 900, height: 600);

record CounterItem(int Id, string Name, int Value);

class App : Component
{
    private static readonly CounterItem[] Items =
    [
        new(1, "Alpha", 1),
        new(2, "Bravo", 2),
        new(3, "Charlie", 3),
        new(4, "Delta", 4),
        new(5, "Echo", 5),
        new(6, "Foxtrot", 6),
        new(7, "Golf", 7),
        new(8, "Hotel", 8),
        new(9, "India", 9),
        new(10, "Juliet", 10)
    ];

    private static readonly IReadOnlyList<FieldDescriptor> Columns =
    [
        Column<CounterItem>("Id", item => item.Id, displayName: "Id", width: 80),
        Column<CounterItem>("Name", item => item.Name, displayName: "Name", width: 220),
        Column<CounterItem>("Value", item => item.Value, displayName: "Counter", width: 140)
    ];

    public override Element Render()
    {
        var (minimum, setMinimum) = UseState(3);
        var (counter, setCounter) = UseState(0);

        return Grid(
            [GridSize.Star()],
            [GridSize.Star()],
            [
                TabView(
                    [
                        Tab("Data", RenderDataTab(minimum, setMinimum)),
                        Tab("Counter", RenderCounterTab(counter, setCounter))
                    ]
                ).ShowAddButton(false)
            ]
        ).RequestedTheme(ElementTheme.Default);
    }

    private static Element RenderDataTab(int minimum, Action<int> setMinimum)
    {
        var filteredItems = Items
            .Where(item => item.Value >= minimum)
            .ToList();

        var source = new ListDataSource<CounterItem>(
            filteredItems,
            item => new RowKey(item.Id.ToString()),
            true);

        return Grid(
            [GridSize.Star()],
            [GridSize.Auto, GridSize.Star()],
            [
                HStack(
                    12,
                    [
                        TextBlock("Minimum counter"),
                        NumberBox(
                            minimum,
                            value => setMinimum((int)Math.Clamp(Math.Round(value), 0, Items.Length)),
                            header: "Minimum counter"
                        ).Range(0, Items.Length).SpinButtons(),
                        TextBlock($"{filteredItems.Count} items")
                    ]
                ).Margin(16).Grid(0, 0),

                DataGrid(
                    source,
                    Columns,
                    rowHeight: 44,
                    emptyTemplate: TextBlock("No counters match the filter."),
                    showSearch: true
                ).Margin(16, 0, 16, 16).Grid(1, 0)
            ]
        );
    }

    private static Element RenderCounterTab(int counter, Action<int> setCounter)
    {
        return Grid(
            [GridSize.Star()],
            [GridSize.Auto, GridSize.Auto],
            [
                Heading($"Counter: {counter}").Margin(16).Grid(0, 0),
                HStack(
                    12,
                    [
                        Button("Decrease", () => setCounter(counter - 1)),
                        Button("Increase", () => setCounter(counter + 1))
                    ]
                ).Margin(16, 0, 16, 16).Grid(1, 0)
            ]
        );
    }
}

