using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<CounterApp>("Counter Master Detail", width: 900, height: 560);

record CounterItem(int Id, string Name, string Group, int Count);

class CounterApp : Component
{
    public override Element Render()
    {
        var (filter, setFilter) = UseState("");
        var (selectedKey, setSelectedKey) = UseState<RowKey?>(new RowKey("1"));
        var (items, setItems) = UseState<IReadOnlyList<CounterItem>>(
        [
            new(1, "Alpha", "Work", 2),
            new(2, "Beta", "Work", 5),
            new(3, "Gamma", "Home", 1),
            new(4, "Delta", "Home", 8),
            new(5, "Epsilon", "Ideas", 3),
            new(6, "Zeta", "Ideas", 0),
        ]);

        var filteredItems = items
            .Where(item =>
                string.IsNullOrWhiteSpace(filter) ||
                item.Name.Contains(filter, StringComparison.OrdinalIgnoreCase) ||
                item.Group.Contains(filter, StringComparison.OrdinalIgnoreCase))
            .ToList();

        var dataSource = new ListDataSource<CounterItem>(
            filteredItems,
            item => new RowKey(item.Id.ToString()),
            false);

        var selectedItem = items.FirstOrDefault(item => KeyFor(item).Equals(selectedKey));

        void UpdateSelectedCount(int delta)
        {
            if (selectedItem is null)
                return;

            setItems(items
                .Select(item => item.Id == selectedItem.Id ? item with { Count = Math.Max(0, item.Count + delta) } : item)
                .ToList());
        }

        return Border(
            Grid(
                columns: [GridSize.Star(2), GridSize.Star()],
                rows: [GridSize.Star()],
                Border(
                    FlexColumn(
                        Heading("Counters"),
                        TextField(filter, setFilter, "Filter by name or group")
                            .Header("Filter"),
                        DataGrid(
                            dataSource,
                            [
                                Column<CounterItem>("Name", item => item.Name, displayName: "Name").Width(180, min: 120),
                                Column<CounterItem>("Group", item => item.Group, displayName: "Group").Width(120, min: 90),
                                Column<CounterItem>("Count", item => item.Count, displayName: "Count").Width(90, min: 70),
                            ],
                            selectionMode: SelectionMode.Single,
                            onSelectionChanged: keys => setSelectedKey(keys.FirstOrDefault()),
                            emptyTemplate: TextBlock("No counters match the filter.").Padding(16))
                        .Flex(grow: 1, basis: 0)
                    )
                    with
                    {
                        RowGap = 12,
                    })
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(12)
                    .Padding(16)
                    .Grid(row: 0, column: 0),

                DetailPane(selectedItem, UpdateSelectedCount)
                    .Grid(row: 0, column: 1)
            )
            with
            {
                ColumnSpacing = 16,
            })
            .Padding(16)
        .Background(Theme.SubtleFill)
        .RequestedTheme(ElementTheme.Default);
    }

    static RowKey KeyFor(CounterItem item) => new(item.Id.ToString());

    static Element DetailPane(CounterItem? item, Action<int> updateCount) =>
        Border(
            item is null
                ? FlexColumn(
                    Heading("Detail"),
                    TextBlock("Select a counter from the grid.").Foreground(Theme.SecondaryText))
                    with
                    {
                        RowGap = 12,
                    }
                : FlexColumn(
                    Heading(item.Name),
                    Caption(item.Group).Foreground(Theme.SecondaryText),
                    Border(
                        TextBlock(item.Count.ToString())
                            .Foreground(Theme.PrimaryText)
                            .FontSize(56)
                            .HorizontalAlignment(HorizontalAlignment.Center))
                        .Background(Theme.LayerFill)
                        .CornerRadius(12)
                        .Padding(24),
                    HStack(8,
                        Button("Increment", () => updateCount(1)),
                        Button("Decrement", () => updateCount(-1))))
                    with
                    {
                        RowGap = 16,
                    })
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(12)
            .Padding(16);
}

