using Microsoft.UI.Xaml;

ReactorApp.Run<App>("Master Detail Counter", width: 900, height: 600);

record DetailItem(string Id, string Name, string Description);

class App : Component
{
    static readonly DetailItem[] Items =
    [
        new("alpha", "Alpha", "The first item in the master list."),
        new("bravo", "Bravo", "A second selectable item."),
        new("charlie", "Charlie", "Another item that can be filtered."),
        new("delta", "Delta", "A final item for the detail pane.")
    ];

    public override Element Render()
    {
        var (filter, setFilter) = UseState("");
        var (selectedId, setSelectedId) = UseState(Items[0].Id);
        var (counter, setCounter) = UseState(0);

        var filteredItems = Items
            .Where(item => item.Name.Contains(filter, StringComparison.OrdinalIgnoreCase))
            .ToArray();

        var selectedItem = filteredItems.FirstOrDefault(item => item.Id == selectedId)
            ?? filteredItems.FirstOrDefault();
        var selectedIndex = selectedItem is null
            ? -1
            : Array.FindIndex(filteredItems, item => item.Id == selectedItem.Id);

        return Grid(
            columns: [GridSize.Px(300), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            (TitleBar("Master Detail Counter") with { Subtitle = "Default themed Reactor app" })
                .Grid(row: 0, column: 0, columnSpan: 2),

            Border(
                VStack(12,
                    TextField(filter, setFilter, placeholder: "Filter items")
                        .Header("Filter")
                        .AutomationName("Filter items"),
                    ListBox(
                        filteredItems.Select(item => item.Name).ToArray(),
                        selectedIndex,
                        index =>
                        {
                            if (index >= 0 && index < filteredItems.Length)
                            {
                                setSelectedId(filteredItems[index].Id);
                                setCounter(0);
                            }
                        })
                        .AutomationName("Master list")))
                .Padding(16))
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .CornerRadius(8)
            .Margin(16, 16, 8, 16)
            .Grid(row: 1, column: 0),

            DetailPane(selectedItem, counter, () => setCounter(counter + 1))
                .Grid(row: 1, column: 1)
        )
        .Background(Theme.SolidBackground)
        .RequestedTheme(ElementTheme.Default);
    }

    static Element DetailPane(DetailItem? item, int counter, Action increment)
        => Border(
                item is null
                    ? VStack(
                        SubHeading("No item selected"),
                        TextBlock("Try a different filter.").Foreground(Theme.SecondaryText))
                    : VStack(16,
                        Heading(item.Name),
                        TextBlock(item.Description).Foreground(Theme.SecondaryText),
                        TextBlock($"Counter: {counter}"),
                        Button("Increment", increment)
                            .AutomationName($"Increment {item.Name} counter")))
            .Padding(24))
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .CornerRadius(8)
            .Margin(8, 16, 16, 16);
}

