        new("delta", "Delta", "A final item for the detail pane.")
    ];

    public override Element Render()
    {
        var (filter, setFilter) = UseState("");
        var (selectedId, setSelectedId) = UseState(Items[0].Id);
        var (counter, setCounter) = UseState(0);

        var filteredItems = Items
            .Where(item => item.Name.Contains(filter, StringComparison.OrdinalIgnoreCase))
            .ToArray();

        var selectedItem = filteredItems.FirstOrDefault(item => item.Id == selectedId)
            ?? filteredItems.FirstOrDefault();
        var selectedIndex = selectedItem is null
            ? -1
            : Array.FindIndex(filteredItems, item => item.Id == selectedItem.Id);

