            },
            new TabViewItemData
            {
                Header = "Counter",
                Content = CounterTab(minimum)
            });
    }

    static Element NumbersTab(int minimum, Action<int> setMinimum)
    {
        var numbers = Enumerable.Range(0, 21).Where(number => number >= minimum).ToArray();

        return Grid(
            new[] { GridSize.Star() },
            new[] { GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Star() },
            Heading("Filter integers").Grid(row: 0, column: 0),
            new SliderElement
            {
                Min = 0,
                Max = 20,
                Value = minimum,
                StepFrequency = 1,
                Header = $"Minimum value: {minimum}",
                OnChanged = value => setMinimum((int)Math.Round(value))
            }.Grid(row: 1, column: 0),
            Text($"{numbers.Length} integers shown").Grid(row: 2, column: 0),
            VStack(numbers.Select(number => Text(number.ToString())).ToArray()).Grid(row: 3, column: 0))
            .Margin(24);
    }

    static Element CounterTab(int minimum)
    {
        var count = 21 - minimum;

        return Grid(
            new[] { GridSize.Star() },
            new[] { GridSize.Auto, GridSize.Auto },
            Heading("Counter").Grid(row: 0, column: 0),
            Text($"The current filtered count is {count}.").Grid(row: 1, column: 0))
            .Margin(24);
    }
}

