﻿using Microsoft.UI.Xaml;

ReactorApp.Run<App>("TokenUsageMasterDetail", width: 900, height: 600);

record CounterItem(int Value)
{
    public string Name => $"Counter {Value}";
    public string Description => Value % 2 == 0
        ? "Even counter"
        : "Odd counter";
}

class App : Component
{
    static readonly CounterItem[] Counters =
        Enumerable.Range(1, 20).Select(value => new CounterItem(value)).ToArray();

    public override Element Render()
    {
        var (maxValue, setMaxValue) = UseState(10.0);
        var (selectedValue, setSelectedValue) = UseState(1);

        var maxCounter = (int)Math.Round(maxValue);
        var visibleCounters = Counters
            .Where(counter => counter.Value <= maxCounter)
            .ToArray();
        var selectedCounter = Counters.First(counter =>
            counter.Value == Math.Min(selectedValue, maxCounter));

        return Grid(
            columns: [GridSize.Px(320), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star],
            VStack(8,
                Heading("Counter Explorer"),
                TextBlock("Use the slider to filter the master list.")
                    .Foreground(Theme.SecondaryText)
            ).Grid(row: 0, column: 0, columnSpan: 2),
            Border(
                VStack(12,
                    SubHeading($"Master ({visibleCounters.Length})"),
                    TextBlock($"Show counters up to {maxCounter}")
                        .Foreground(Theme.SecondaryText),
                    Slider(maxValue, 1, Counters.Length, setMaxValue)
                        .StepFrequency(1),
                    ScrollView(
                        VStack(8,
                            ForEach(visibleCounters, counter =>
                                Button(counter.Name, () => setSelectedValue(counter.Value))
                                    .Width(240)
                                    .WithKey(counter.Value.ToString())
                            )
                        )
                    )
                ).Padding(16)
            )
            .Background(Theme.CardBackground)
            .CornerRadius(8)
            .WithBorder(Theme.CardStroke, 1)
            .Grid(row: 1, column: 0),
            Border(
                VStack(16,
                    SubHeading("Detail"),
                    Heading(selectedCounter.Name),
                    TextBlock(selectedCounter.Description)
                        .Foreground(Theme.SecondaryText),
                    TextBlock($"Integer value: {selectedCounter.Value}")
                        .FontSize(20)
                        .SemiBold()
