using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

ReactorApp.Run<App>("ReactorMasterDetail", width: 900, height: 600);

class App : Component
{
    private static readonly DetailItem[] Items =
    [
        new("alpha", "Alpha", "First item in the master list.", 0),
        new("bravo", "Bravo", "Filtered in because it has a count.", 2),
        new("charlie", "Charlie", "Another uncounted item.", 0),
        new("delta", "Delta", "Filtered in because it has a count.", 5),
    ];

    public override Element Render()
    {
        var (showCountedOnly, setShowCountedOnly) = UseState(false);
        var (selectedId, setSelectedId) = UseState(Items[0].Id);
        var (counter, setCounter) = UseState(0);

        var visibleItems = showCountedOnly
            ? Items.Where(item => item.Count > 0).ToArray()
            : Items;
        var selectedIndex = Array.FindIndex(visibleItems, item => item.Id == selectedId);
        var selectedItem = selectedIndex >= 0 ? visibleItems[selectedIndex] : null;

        return (Grid(
            [GridSize.Px(300), GridSize.Star()],
            [GridSize.Auto, GridSize.Star()],
            Header(showCountedOnly, setShowCountedOnly).Grid(row: 0, column: 0, columnSpan: 2),
            MasterList(visibleItems, selectedIndex, setSelectedId).Grid(row: 1, column: 0),
            Detail(selectedItem, counter, () => setCounter(counter + 1)).Grid(row: 1, column: 1))
            with
            {
                RowSpacing = 16,
                ColumnSpacing = 16,
            })
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }

    private static Element Header(bool showCountedOnly, Action<bool> setShowCountedOnly) =>
        Grid(
            [GridSize.Star(), GridSize.Auto],
            [GridSize.Auto],
            VStack(
                Heading("Master-detail"),
                Text("Select an item, filter the master list, and update the integer counter.")
                    .Foreground(Theme.SecondaryText))
                .Grid(column: 0),
            ToggleSwitch(
                showCountedOnly,
                setShowCountedOnly,
                onContent: "Counted",
                offContent: "All",
                header: "Filter")
                .Grid(column: 1))
            with
            {
                ColumnSpacing = 16,
            };

    private static Element MasterList(IReadOnlyList<DetailItem> items, int selectedIndex, Action<string> setSelectedId) =>
        Border(
            VStack(
                Text("Items").SemiBold(),
                (ListView(
                    items,
                    item => item.Id,
                    (item, _) => Grid(
                        [GridSize.Star(), GridSize.Auto],
                        [GridSize.Auto, GridSize.Auto],
                        Text(item.Name).SemiBold().Grid(row: 0, column: 0),
                        Text(item.Description)
                            .Foreground(Theme.SecondaryText)
                            .TextWrapping()
                            .Grid(row: 1, column: 0, columnSpan: 2),
                        Text(item.Count.ToString())
                            .Foreground(Theme.SecondaryText)
                            .Grid(row: 0, column: 1))
                        with
                        {
                            ColumnSpacing = 12,
                            RowSpacing = 4,
                        })
                    with
                    {
                        SelectedIndex = selectedIndex,
                        OnSelectionChanged = index =>
                        {
                            if (index >= 0 && index < items.Count)
                            {
                                setSelectedId(items[index].Id);
                            }
                        },
                    }))
            .Spacing(12))
        .Padding(16)
        .CornerRadius(8)
        .Background(Theme.CardBackground)
        .WithBorder(Theme.CardStroke);

    private static Element Detail(DetailItem? selectedItem, int counter, Action incrementCounter) =>
        Border(
            selectedItem is null
                ? VStack(
                    Heading("No item selected"),
                    Text("Select an item from the master list.").Foreground(Theme.SecondaryText))
                : VStack(
                    Heading(selectedItem.Name),
                    Text(selectedItem.Description).TextWrapping(),
                    Text($"Item count: {selectedItem.Count}").Foreground(Theme.SecondaryText),
                    Text($"Counter: {counter}").FontSize(32).SemiBold(),
                    Button("Increment counter", incrementCounter).HAlign(HorizontalAlignment.Left))
                .Spacing(12))
        .Padding(24)
        .CornerRadius(8)
        .Background(Theme.CardBackground)
        .WithBorder(Theme.CardStroke);
}

record DetailItem(string Id, string Name, string Description, int Count);

