                .Foreground(Theme.SecondaryText)
                .Grid(row: 1, column: 0),
            VStack(12,
                Button("Open filter dialog", () => setShowDialog(true)),
                TextBlock("Use the dialog toggle and counter to filter the list.")
            ).Grid(row: 2, column: 0),
            ContentDialog(
                "Filter items",
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Star],
                    ToggleSwitch(
                        filterEnabled,
                        setFilterEnabled,
                        onContent: "Filtering values at or above the counter",
                        offContent: "Showing all values"
                    ).Grid(row: 0, column: 0),
                    HStack(8,
                        TextBlock($"Counter: {counter}")
