using Microsoft.UI.Xaml;

ReactorApp.Run<App>("Master-detail counter", width: 860, height: 520);

sealed record CounterRecord(int Id, string Name, int Counter);

sealed class App : Component
{
    public override Element Render()
    {
        var (records, setRecords) = UseState<IReadOnlyList<CounterRecord>>(
        [
            new(1, "Alpha", 0),
            new(2, "Beta", 1),
            new(3, "Gamma", 0)
        ]);
        var (selectedIndex, setSelectedIndex) = UseState(0);

        var selected = records[selectedIndex];
        var masterItems = records
            .Select(record => $"{record.Name} - counter {record.Counter}")
            .ToArray();

        void SetSelectedCounter(bool isChecked)
        {
            var updated = selected with { Counter = isChecked ? 1 : 0 };
            setRecords(records.Select(record => record.Id == updated.Id ? updated : record).ToArray());
        }

        return Grid(
                columns: [GridSize.Px(280), GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Star()],
                TitleBar("Master-detail counter") with { Subtitle = "Select a record and edit its int counter" },
                MasterPane(masterItems, selectedIndex, setSelectedIndex)
                    .Grid(row: 1, column: 0),
                DetailPane(selected, SetSelectedCounter)
                    .Grid(row: 1, column: 1))
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }

    static Element MasterPane(string[] items, int selectedIndex, Action<int> setSelectedIndex)
    {
        return Border(
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Star()],
                    VStack(8,
                        SubHeading("Master"),
                        Caption("Records")),
                    ListBox(items, selectedIndex, setSelectedIndex)
                        .Grid(row: 1)
                        .Margin(top: 12)))
            .Padding(16)
            .Margin(right: 16)
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .CornerRadius(12);
    }

    static Element DetailPane(CounterRecord record, Action<bool> setCounter)
    {
        return Border(
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Star()],
                    SubHeading("Detail"),
                    TextBlock(record.Name)
                        .Grid(row: 1)
                        .Margin(top: 12),
                    TextBlock($"Counter: {record.Counter}")
                        .Grid(row: 2)
                        .Margin(top: 8)
                        .Foreground(Theme.SecondaryText),
                    CheckBox(record.Counter > 0, setCounter, "Counter enabled")
                        .Grid(row: 3)
                        .Margin(top: 20)
                        .AutomationName("Counter checkbox")))
            .Padding(16)
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .CornerRadius(12);
    }
}

