using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<CounterApp>("Counter Dialog", width: 560, height: 420);

sealed record CounterRecord(int Count, bool IsEnabled);

class CounterApp : Component
{
    public override Element Render()
    {
        var (record, setRecord) = UseState(new CounterRecord(3, true));
        var (isDialogOpen, setIsDialogOpen) = UseState(false);
        var (draftCount, setDraftCount) = UseState(0.0);
        var (draftEnabled, setDraftEnabled) = UseState(false);

        void OpenEditor()
        {
            setDraftCount(record.Count);
            setDraftEnabled(record.IsEnabled);
            setIsDialogOpen(true);
        }

        void SaveRecord()
        {
            setRecord(record with
            {
                Count = (int)Math.Round(draftCount),
                IsEnabled = draftEnabled,
            });
            setIsDialogOpen(false);
        }

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Star(), GridSize.Auto],
                Heading("Counter record").Grid(row: 0, column: 0),
                Border(
                        Grid(
                            columns: [GridSize.Auto, GridSize.Star],
                            rows: [GridSize.Auto, GridSize.Auto],
                            Caption("Counter").Grid(row: 0, column: 0),
                            TextBlock(record.Count.ToString())
                                .FontSize(36)
                                .SemiBold()
                                .Grid(row: 0, column: 1)
                                .Margin(16, 0, 0, 12),
                            Caption("Enabled").Grid(row: 1, column: 0),
                            TextBlock(record.IsEnabled ? "Yes" : "No")
                                .FontSize(20)
                                .Grid(row: 1, column: 1)
                                .Margin(16, 0, 0, 0)))
                    .Padding(20)
                    .CornerRadius(12)
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .Grid(row: 1, column: 0)
                    .Margin(0, 18, 0, 18),
                Button("Edit record", OpenEditor)
                    .Grid(row: 2, column: 0),
                ContentDialog(
                    "Edit counter record",
                    Grid(
                        columns: [GridSize.Star()],
                        rows: [GridSize.Auto, GridSize.Auto],
                        NumberBox(draftCount, setDraftCount, header: "Counter")
                            .SpinButtons()
                            .Grid(row: 0, column: 0),
                        CheckBox(draftEnabled, setDraftEnabled, label: "Enabled")
                            .Grid(row: 1, column: 0)
                            .Margin(0, 12, 0, 0)),
                    primaryButtonText: "Save") with
                {
                    IsOpen = isDialogOpen,
                    SecondaryButtonText = "Cancel",
                    OnClosed = result =>
                    {
                        if (result == ContentDialogResult.Primary)
                        {
                            SaveRecord();
                            return;
                        }

                        setIsDialogOpen(false);
                    },
                })
            .Padding(24)
            .Background(Theme.SolidBackground);
    }
}

