using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Counter Grid", width: 900, height: 600);

record CounterRecord(int Id, int Counter);

class App : Component
{
    public override Element Render()
    {
        var (record, setRecord) = UseState(new CounterRecord(1, 0));

        var source = new ListDataSource<CounterRecord>(
            [record],
            item => (RowKey)item.Id);

        var columns = new FieldDescriptor[]
        {
            Column<CounterRecord>("Id", item => item.Id, width: 80),
            Column<CounterRecord>("Counter", item => item.Counter, editable: true, width: 160),
        };

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Star()],
                (TitleBar("Counter Grid") with
                {
                    Subtitle = "Edit the counter value in the grid",
                }).Grid(row: 0),
                TabView(
                    Tab("Editor",
                        Grid(
                            columns: [GridSize.Star()],
                            rows: [GridSize.Auto, GridSize.Star, GridSize.Auto],
                            TextBlock("Counter record").FontSize(20).SemiBold().Margin(0, 0, 0, 12).Grid(row: 0),
                            DataGrid<CounterRecord>(
                                    source,
                                    columns,
                                    editable: true,
                                    editMode: EditMode.Cell,
                                    onRowChanged: (_, updatedRecord) =>
                                    {
                                        setRecord(updatedRecord);
                                        return Task.CompletedTask;
                                    })
                                .Grid(row: 1),
                            TextBlock($"Current counter: {record.Counter}").Margin(0, 12, 0, 0).Grid(row: 2)
                        ).Padding(24)
                    ) with
                    {
                        IsClosable = false,
                    },
                    Tab("Details",
                        Grid(
                            columns: [GridSize.Auto, GridSize.Star()],
                            rows: [GridSize.Auto, GridSize.Auto],
                            TextBlock("Id").SemiBold().Grid(row: 0, column: 0),
                            TextBlock(record.Id.ToString()).Margin(12, 0, 0, 8).Grid(row: 0, column: 1),
                            TextBlock("Counter").SemiBold().Grid(row: 1, column: 0),
                            TextBlock(record.Counter.ToString()).Margin(12, 0, 0, 0).Grid(row: 1, column: 1)
                        ).Padding(24)
                    ) with
                    {
