using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

ReactorApp.Run<App>("Dialog Counter Grid", width: 720, height: 480);

sealed record CounterRecord(int Id, int Counter);

sealed record AppState(CounterRecord Record, CounterRecord Draft, bool IsDialogOpen)
{
    public static AppState Initial { get; } = new(
        new CounterRecord(1, 0),
        new CounterRecord(1, 0),
        false);
}

abstract record AppAction;
sealed record OpenEditor : AppAction;
sealed record CloseEditor : AppAction;
sealed record UpdateDraft(CounterRecord Record) : AppAction;
sealed record SaveDraft : AppAction;

static class AppReducer
{
    public static AppState Reduce(AppState state, AppAction action) =>
        action switch
        {
            OpenEditor => state with
            {
                Draft = state.Record,
                IsDialogOpen = true
            },

            CloseEditor => state with
            {
                Draft = state.Record,
                IsDialogOpen = false
            },

            UpdateDraft update => state with { Draft = update.Record },

            SaveDraft => state with
            {
                Record = state.Draft,
                IsDialogOpen = false
            },

            _ => state
        };
}

sealed class CounterRecordSource(List<CounterRecord> records)
    : ListDataSource<CounterRecord>(records, record => new RowKey(record.Id.ToString()), true);

sealed class App : Component
{
    static readonly IReadOnlyList<FieldDescriptor> Columns =
    [
        Column<CounterRecord>(
                nameof(CounterRecord.Id),
                record => record.Id,
                displayName: "ID",
                width: 80)
            .ReadOnly(),
        Column<CounterRecord>(
            nameof(CounterRecord.Counter),
            record => record.Counter,
            editable: true,
            displayName: "Counter",
            width: 180)
    ];

    public override Element Render()
    {
        var (state, dispatch) = UseReducer<AppState, AppAction>(AppReducer.Reduce, AppState.Initial);

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Star()],
                Heading("Counter record")
                    .Grid(row: 0),
                TextBlock($"Current counter: {state.Record.Counter}")
                    .Foreground(Theme.SecondaryText)
                    .Grid(row: 1),
                VStack(12,
                        Button("Edit counter", () => dispatch(new OpenEditor()))
                            .AutomationName("Edit counter"),
                        EditorDialog(state, dispatch))
                    .Grid(row: 2))
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default) with
            {
                RowSpacing = 12
            };
    }

    static Element EditorDialog(AppState state, Action<AppAction> dispatch)
    {
        var source = new CounterRecordSource([state.Draft]);

        return ContentDialog(
            "Edit counter",
            Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Px(180)],
                    TextBlock("Edit the counter cell, then save the dialog.")
                        .Foreground(Theme.SecondaryText)
                        .Grid(row: 0),
                    DataGrid(
                            source,
                            Columns,
                            onRowChanged: (_, updated) =>
                            {
                                dispatch(new UpdateDraft(updated));
                                return Task.CompletedTask;
                            },
                            editable: true,
                            editMode: EditMode.Cell,
                            emptyTemplate: TextBlock("No counter record"))
                        .Grid(row: 1))
                with
                {
                    RowSpacing = 12
                },
            primaryButtonText: "Save") with
        {
            IsOpen = state.IsDialogOpen,
            SecondaryButtonText = "Cancel",
            DefaultButton = ContentDialogButton.Primary,
            OnClosed = result =>
            {
                dispatch(result == ContentDialogResult.Primary ? new SaveDraft() : new CloseEditor());
            }
        };
    }
}

