using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Text;

ReactorApp.Run<App>("Counter records", width: 900, height: 600);

record CounterRecord
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public int Counter { get; init; }
}

class App : Component
{
    private static readonly IReadOnlyList<CounterRecord> InitialRecords =
    [
        new() { Id = "first", Name = "First record", Counter = 2 },
        new() { Id = "second", Name = "Second record", Counter = 5 },
        new() { Id = "third", Name = "Third record", Counter = 8 },
    ];

    public override Element Render()
    {
        var (records, setRecords) = UseState(InitialRecords);
        var (selectedId, setSelectedId) = UseState(InitialRecords[0].Id);
        var selected = records.First(record => record.Id == selectedId);

        void UpdateSelectedCounter(int delta) =>
            setRecords(records
                .Select(record => record.Id == selectedId
                    ? record with { Counter = record.Counter + delta }
                    : record)
                .ToArray());

        Element?[] masterChildren =
        [
            TextBlock("Master").FontWeight(FontWeights.SemiBold),
            ..records.Select(record =>
                RadioButton(
                    $"{record.Name} ({record.Counter})",
                    record.Id == selectedId,
                    isChecked =>
                    {
                        if (isChecked)
                        {
                            setSelectedId(record.Id);
                        }
                    },
                    "records")
                .WithKey(record.Id)),
        ];

        return Grid(
            [GridSize.Px(280), GridSize.Star()],
            [GridSize.Auto, GridSize.Star],
            Heading("Counter records")
                .Grid(row: 0, column: 0, columnSpan: 2),

            VStack(masterChildren)
            .Padding(16)
            .Grid(row: 1, column: 0),

            VStack(
                TextBlock("Detail").FontWeight(FontWeights.SemiBold),
                TextBlock(selected.Name).FontSize(24),
                TextBlock($"Counter: {selected.Counter}").FontSize(20),
                HStack(
                    Button("Decrease", () => UpdateSelectedCounter(-1)),
                    Button("Increase", () => UpdateSelectedCounter(1))))
            .Padding(16)
            .Grid(row: 1, column: 1))
        .Padding(24)
        .RequestedTheme(ElementTheme.Default);
    }
}

