using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<CounterMasterDetailApp>("Counter Records", width: 820, height: 520);

record CounterRecord(int Id, string Name, int Counter);

class CounterMasterDetailApp : Component
{
    static readonly CounterRecord[] InitialRecords =
    [
        new(1, "Alpha", 0),
        new(2, "Beta", 5),
        new(3, "Gamma", 12),
    ];

    public override Element Render()
    {
        var (records, setRecords) = UseState<IReadOnlyList<CounterRecord>>(InitialRecords);
        var (selectedIndex, setSelectedIndex) = UseState(0);
        var (isEditing, setIsEditing) = UseState(false);

        var index = Math.Clamp(selectedIndex, 0, records.Count - 1);
        var selected = records[index];

        void SetCounter(int value) =>
            setRecords(records.Select(record =>
                record.Id == selected.Id ? record with { Counter = value } : record).ToArray());

        return (Grid(
            columns: [GridSize.Auto, GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],

            (TitleBar("Counter Records") with
            {
                Subtitle = "Master-detail editor"
            }).Grid(row: 0, columnSpan: 2),

            Border(
                VStack(12,
                    TextBlock("Records").SemiBold(),
                    ListBox(
                        records.Select(record => $"{record.Name} - {record.Counter}").ToArray(),
                        index,
                        nextIndex =>
                        {
                            setSelectedIndex(nextIndex);
                            setIsEditing(false);
                        })
                    .Width(220)
                ).Padding(16)
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .Grid(row: 1, column: 0),

            Border(
                VStack(16,
                    TextBlock(selected.Name).FontSize(28).SemiBold(),
                    TextBlock($"Record ID: {selected.Id}").Foreground(Theme.SecondaryText),
                    TextBlock($"Counter: {selected.Counter}").FontSize(20),

                    ToggleSwitch(isEditing, setIsEditing, onContent: "Editing", offContent: "Viewing")
                        .Header("Edit mode"),

                    NumberBox(selected.Counter, value => SetCounter((int)value), "Counter")
                        .SpinButtons()
                        .Disabled(!isEditing),

                    HStack(8,
                        Button("-1", () => SetCounter(selected.Counter - 1)).Disabled(!isEditing),
                        Button("+1", () => SetCounter(selected.Counter + 1)).Disabled(!isEditing)
                    )
                ).Padding(24)
            )
            .Background(Theme.SolidBackground)
            .Grid(row: 1, column: 1)
        ) with
        {
            RequestedTheme = ElementTheme.Default
        });
    }
}

