using Microsoft.UI.Xaml;

ReactorApp.Run<App>("ReactorMasterDetail", width: 900, height: 600);

class App : Component
{
    public override Element Render()
    {
        var (counterText, setCounterText) = UseState("0");
        var (submittedCounter, setSubmittedCounter) = UseState(0);
        var (message, setMessage) = UseState("Submit the form to update the detail.");

        void SubmitCounter()
        {
            if (!int.TryParse(counterText, out var counter))
            {
                setMessage("Enter a whole number.");
                return;
            }

            setSubmittedCounter(counter);
            setMessage($"Counter {counter} submitted.");
        }

        return Grid(
            [GridSize.Px(320), GridSize.Star()],
            [GridSize.Star()],
            VStack(
                Heading("Master"),
                TextBlock("Counter"),
                TextField(counterText, setCounterText, placeholder: "Enter an int counter")
                    .AutomationName("Counter"),
                Button("Submit", SubmitCounter)
                    .AutomationName("Submit counter"),
                TextBlock(message)
            )
            .Padding(24)
            .Spacing(12)
            .GridColumn(0),
            VStack(
                Heading("Detail"),
                TextBlock("Submitted counter"),
                Heading(submittedCounter.ToString())
                    .AutomationName("Submitted counter")
            )
            .Padding(24)
            .Spacing(12)
            .GridColumn(1)
        )
        .RequestedTheme(ElementTheme.Default);
    }
}

