using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Xaml;

ReactorApp.Run<App>("ReactorCounterGrid", width: 900, height: 600);

record CounterSubmission(int Id, int Counter);

class CounterSubmissionSource(IReadOnlyList<CounterSubmission> rows) : IDataSource<CounterSubmission>
{
    public DataSourceCapabilities Capabilities => default;

    public Task<DataPage<CounterSubmission>> GetPageAsync(DataRequest request, CancellationToken cancellationToken)
    {
        return Task.FromResult(new DataPage<CounterSubmission>(rows, continuationToken: null, totalCount: rows.Count));
    }

    public RowKey GetRowKey(CounterSubmission item) => new(item.Id.ToString());
}

class App : Component
{
    public override Element Render()
    {
        var (counterText, setCounterText) = UseState("0");
        var (submissions, setSubmissions) = UseState<IReadOnlyList<CounterSubmission>>([]);
        var (message, setMessage) = UseState("Enter an integer counter and submit it.");

        void Submit()
        {
            if (!int.TryParse(counterText, out var counter))
            {
                setMessage("Counter must be a valid integer.");
                return;
            }

            setSubmissions([.. submissions, new CounterSubmission(submissions.Count + 1, counter)]);
            setCounterText((counter + 1).ToString());
            setMessage($"Submitted counter {counter}.");
        }

        var source = new CounterSubmissionSource(submissions);

        return Grid(
            columns: [GridSize.Star(1)],
            rows: [GridSize.Auto, GridSize.Star(1)],
            Heading("Counter submissions")
                .Margin(24, 24, 24, 12)
                .Grid(row: 0),
            Grid(
                columns: [GridSize.Auto, GridSize.Px(160), GridSize.Auto],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Star(1)],
                TextBlock("Counter")
                    .VAlign(VerticalAlignment.Center)
                    .Grid(row: 0, column: 0),
                TextField(counterText, setCounterText, placeholder: "Enter an integer")
                    .AutomationName("CounterInput")
                    .Grid(row: 0, column: 1),
                Button("Submit", Submit)
                    .AutomationName("SubmitCounter")
                    .Grid(row: 0, column: 2),
                TextBlock(message)
                    .Grid(row: 1, columnSpan: 3),
                DataGrid(
                    source,
                    columns:
                    [
                        Column<CounterSubmission>("Id", row => row.Id).Width(80),
                        Column<CounterSubmission>("Counter", row => row.Counter).Width(160)
                    ],
                    selectionMode: SelectionMode.None,
                    editable: false,
                    emptyTemplate: TextBlock("Submit a counter to add a row."))
                    .AutomationName("CounterGrid")
                    .Grid(row: 2, columnSpan: 3)
            )
            .Margin(24, 0, 24, 24)
            .Grid(row: 1)
        )
        .RequestedTheme(ElementTheme.Default);
    }
}

