using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Tabbed Counter Form", width: 900, height: 600);

record CounterSubmission(int Id, int Counter);

class App : Component
{
    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);
        var (nextId, setNextId) = UseState(1);
        var (submissions, updateSubmissions) = UseReducer(new List<CounterSubmission>());

        void Submit()
        {
            var submission = new CounterSubmission(nextId, counter);
            updateSubmissions(items => [.. items, submission]);
            setNextId(nextId + 1);
        }

        var source = new LocalDataSource<CounterSubmission>(
            submissions,
            item => new RowKey(item.Id.ToString()));

        FieldDescriptor[] columns =
        [
            Column<CounterSubmission>("Id", item => item.Id, displayName: "ID", width: 120),
            Column<CounterSubmission>("Counter", item => item.Counter, displayName: "Counter", width: 180)
        ];

        return TabView(
            Tab("Form",
                Grid(
                    columns: [GridSize.Px(160), GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto],
                    TextBlock("Counter").VAlign(VerticalAlignment.Center).Grid(row: 0, column: 0),
                    NumberBox(counter, value => setCounter((int)value), header: "Integer counter")
                        .Range(0, int.MaxValue)
                        .SpinButtons()
                        .Grid(row: 0, column: 1),
                    Button("Submit", Submit).Grid(row: 1, column: 1),
                    Caption($"Submitted rows: {submissions.Count}").Grid(row: 2, column: 1)
                ).Padding(24)),
            Tab("Submissions",
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Star()],
                    DataGrid(
                        source,
                        columns,
                        rowHeight: 44,
                        emptyTemplate: TextBlock("Submit the form to add counter rows.").Padding(16))
                    .Grid(row: 0, column: 0)
                ).Padding(24))
        ).RequestedTheme(ElementTheme.Default);
    }
}

class LocalDataSource<T>(IReadOnlyList<T> items, Func<T, RowKey> keySelector) : IDataSource<T>
{
    public DataSourceCapabilities Capabilities => DataSourceCapabilities.None;

    public Task<DataPage<T>> GetPageAsync(DataRequest request, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();

        var offset = int.TryParse(request.ContinuationToken, out var parsedOffset) ? parsedOffset : 0;
        var pageSize = request.PageSize <= 0 ? items.Count : request.PageSize;
        var page = items.Skip(offset).Take(pageSize).ToArray();
        var nextOffset = offset + page.Length;
        var continuationToken = nextOffset < items.Count ? nextOffset.ToString() : null;

        return Task.FromResult(new DataPage<T>(page, continuationToken, items.Count));
    }

    public RowKey GetRowKey(T item) => keySelector(item);
}

