                    .Foreground(Theme.SecondaryText))
                .Grid(row: 0, column: 0),
            Border(
                HStack(12,
                    TextBlock("Current counter").SemiBold(),
                    Heading(counter.ToString())))
                .Padding(16)
                .CornerRadius(12)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .Grid(row: 1, column: 0),
            Border(
                DataGrid(
                    source,
                    columns,
                    selectionMode: SelectionMode.None,
                    rowHeight: 48,
                    emptyTemplate: Caption("No forms available.")))
                .Padding(12)
                .CornerRadius(12)
                .Background(Theme.LayerFill)
                .WithBorder(Theme.CardStroke)
                .Grid(row: 2, column: 0),
            RenderSubmitDialog(pendingValue, setCounter, setPendingValue))
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }

    static IReadOnlyList<FieldDescriptor> CreateColumns(Action<int?> setPendingValue) =>
    [
        Column<CounterFormRow>("Form", row => row.Form, displayName: "Form", width: 180),
        Column<CounterFormRow>("CurrentValue", row => row.CurrentValue, displayName: "Current", width: 120),
        Column<CounterFormRow>("SubmittedValue", row => row.SubmittedValue, displayName: "Submitted value", width: 160),
        Column<CounterFormRow>("SubmitAction", row => row.SubmittedValue, displayName: "Submit", width: 120)
            .NotSortable()
            .NotFilterable()
            .CellRenderer(value => Button("Submit", () => setPendingValue((int)value))),
    ];

    static Element RenderSubmitDialog(
        int? pendingValue,
        Action<int> setCounter,
        Action<int?> setPendingValue) =>
        ContentDialog(
            "Submit counter form?",
            Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto],
                TextBlock(pendingValue is null
                    ? "No counter value is pending."
                    : $"Submit {pendingValue} as the new counter value?")
                    .Grid(row: 0, column: 0),
                Caption("Confirm to save the integer counter submitted from the DataGrid.")
                    .Foreground(Theme.SecondaryText)
                    .Grid(row: 1, column: 0)) with
            {
                RowSpacing = 8,
            },
            primaryButtonText: "Confirm") with
        {
            IsOpen = pendingValue is not null,
            SecondaryButtonText = "Cancel",
            DefaultButton = ContentDialogButton.Primary,
            OnClosed = result =>
            {
                if (result == ContentDialogResult.Primary && pendingValue is int value)
                {
                    setCounter(value);
                }

                setPendingValue(null);
            },
        };
