using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<RadioCounterPage>("Radio Counter", width: 420, height: 360);

sealed class RadioCounterPage : Component
{
    const string StepGroupName = "counter-step";

    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);
        var (selectedStep, setSelectedStep) = UseState(1);
        var (submittedStep, setSubmittedStep) = UseState(0);

        void SubmitCounter()
        {
            setCounter(counter + selectedStep);
            setSubmittedStep(selectedStep);
        }

        Element StepOption(int value) =>
            RadioButton(
                    $"Add {value}",
                    isChecked: selectedStep == value,
                    onChecked: isChecked =>
                    {
                        if (isChecked)
                        {
                            setSelectedStep(value);
                        }
                    },
                    groupName: StepGroupName)
                .Margin(0, 4);

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto(), GridSize.Star()],
                Heading("Radio counter")
                    .Foreground(Theme.PrimaryText)
                    .Grid(0, 0),
                Border(
                        Grid(
                            columns: [GridSize.Star(), GridSize.Star()],
                            rows:
                            [
                                GridSize.Auto(),
                                GridSize.Auto(),
                                GridSize.Auto(),
                                GridSize.Auto()
                            ],
                            VStack(4,
                                    Caption("Counter").Foreground(Theme.SecondaryText),
                                    TextBlock(counter.ToString())
                                        .FontSize(48)
                                        .SemiBold()
                                        .TextAlignment(TextAlignment.Center)
                                        .Foreground(Theme.PrimaryText))
                                .Grid(0, 0, 4, 1),
                            VStack(8,
                                    SubHeading("Choose increment")
                                        .Foreground(Theme.PrimaryText),
                                    StepOption(1),
                                    StepOption(2),
                                    StepOption(5))
                                .Grid(0, 1),
                            Button("Submit", SubmitCounter)
                                .AutomationName("Submit counter")
                                .Background(Theme.Accent)
                                .MinWidth(120)
                                .Grid(1, 1),
                            Caption(submittedStep == 0
                                    ? "Pick a value, then submit the form."
                                    : $"Submitted +{submittedStep}.")
                                .Foreground(Theme.SecondaryText)
                                .Grid(2, 1)))
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(12)
                    .Padding(20)
                    .Grid(1, 0))
            .Background(Theme.SolidBackground)
            .Padding(24);
    }
}

