class Program
{
    static void Main(string[] args)
    {
        ReactorApp.Run<App>("Dialog Counter", width: 520, height: 420);
    }
}

class App : Component
{
    public override Element Render()
    {
        var (counter, setCounter) = UseState(0);
        var (dialogOpen, setDialogOpen) = UseState(false);
        var (radioSelected, setRadioSelected) = UseState(true);

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Star],
            Heading("Dialog counter").Grid(row: 0),
            TextBlock($"Counter: {counter}").Grid(row: 1).Margin(0, 12, 0, 20),
            Button("Open form", () =>
            {
                setRadioSelected(true);
                setDialogOpen(true);
            }).Grid(row: 2).HAlign(HorizontalAlignment.Left),
            ContentDialog(
                "Submit counter form",
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Auto],
                    TextBlock("Choose the form action, then submit.").Grid(row: 0),
                    RadioButton(
                        "Increment the counter",
                        radioSelected,
                        isChecked => setRadioSelected(isChecked),
                        groupName: "counter-action").Grid(row: 1).Margin(0, 16, 0, 0)
                ),
                primaryButtonText: "Submit") with
            {
                IsOpen = dialogOpen,
                OnClosed = result =>
                {
                    setDialogOpen(false);

                    if (result == ContentDialogResult.Primary && radioSelected)
                    {
                        setCounter(counter + 1);
                    }
                }
            }
        ).Padding(32).RequestedTheme(ElementTheme.Default);
    }
}

