using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<CounterDialogApp>("Counter Dialog", width: 640, height: 420);

class CounterDialogApp : Component
{
    public override Element Render()
    {
        var (showDialog, setShowDialog) = UseState(false);
        var (counter, setCounter) = UseState(0);
        var (submittedCounter, setSubmittedCounter) = UseState<int?>(null);
        var (submitToggle, setSubmitToggle) = UseState(false);

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Star()],

            Heading("Counter dialog").Grid(row: 0),

            TextBlock("Open the dialog, set an integer counter, then turn on the submit toggle.")
                .Foreground(Theme.SecondaryText)
                .Margin(0, 8, 0, 0)
                .Grid(row: 1),

            (Border(
                VStack(8,
                    TextBlock("Last submitted counter").SemiBold(),
                    TextBlock(submittedCounter is null ? "No counter submitted yet." : submittedCounter.Value.ToString())
                        .FontSize(28)
                )
            ) with
            {
                Padding = new Thickness(16),
                CornerRadius = 8,
                Background = Theme.CardBackground,
                BorderBrush = Theme.CardStroke,
                BorderThickness = 1,
            }).Margin(0, 20, 0, 0).Grid(row: 2),

            Button("Open form", () =>
            {
                setSubmitToggle(false);
                setShowDialog(true);
            })
                .HAlign(HorizontalAlignment.Left)
                .Margin(0, 20, 0, 0)
                .Grid(row: 3),

            (ContentDialog("Counter form", RenderCounterForm(counter, setCounter, submitToggle, isOn =>
            {
                setSubmitToggle(isOn);

                if (isOn)
                {
                    setSubmittedCounter(counter);
                    setShowDialog(false);
                }
            }), "Close") with
            {
                IsOpen = showDialog,
                OnClosed = _ =>
                {
                    setShowDialog(false);
                    setSubmitToggle(false);
                },
            }).Grid(row: 3)
        )
        .Padding(32)
        .RequestedTheme(ElementTheme.Default);
    }

    private static Element RenderCounterForm(
        int counter,
        Action<int> setCounter,
        bool submitToggle,
        Action<bool> setSubmitToggle)
    {
        return Grid(
            columns: [GridSize.Px(120), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto],

            TextBlock("Counter")
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 0, column: 0),

            (NumberBox(counter, value => setCounter(CoerceCounter(value)), header: "Integer value") with
            {
                Minimum = 0,
                Maximum = 100,
                SmallChange = 1,
                LargeChange = 10,
                SpinButtonPlacement = NumberBoxSpinButtonPlacementMode.Inline,
            }).Grid(row: 0, column: 1),

            TextBlock("Submit")
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 1, column: 0),

            ToggleSwitch(
                submitToggle,
                setSubmitToggle,
                onContent: "Submitted",
                offContent: "Ready",
                header: "Submit form")
                .Grid(row: 1, column: 1),

            TextBlock("Turning the toggle on submits the counter and closes the dialog.")
                .Foreground(Theme.SecondaryText)
                .FontSize(12)
                .Grid(row: 2, column: 0, columnSpan: 2)
        ) with
        {
            RowSpacing = 12,
            ColumnSpacing = 16,
        };
    }

    private static int CoerceCounter(double value) =>
        double.IsFinite(value) ? Math.Clamp((int)Math.Round(value), 0, 100) : 0;
}

