using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Automation;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Reactor Master Detail", width: 920, height: 560);

enum DetailAction
{
    Inspect,
    Approve,
    Archive
}

class App : Component
{
    static readonly DetailAction[] Actions = Enum.GetValues<DetailAction>();
    static readonly string[] ActionNames = Actions.Select(action => action.ToString()).ToArray();

    public override Element Render()
    {
        var (selectedIndex, setSelectedIndex) = UseState(0);
        var (lastRun, setLastRun) = UseState("No action has run yet.");

        var selectedAction = Actions[selectedIndex];

        return Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Star()],
                TitleBar("Master Detail") with { Subtitle = "Default theme" },
                Grid(
                    columns: [GridSize.Px(280), GridSize.Star()],
                    rows: [GridSize.Star()],
                    MasterPane(selectedIndex, setSelectedIndex).Grid(column: 0),
                    DetailPane(selectedAction, lastRun, () => setLastRun($"{selectedAction} action triggered.")).Grid(column: 1)
                ).Grid(row: 1))
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);
    }

    static Element MasterPane(int selectedIndex, Action<int> setSelectedIndex) =>
        Border(
                VStack(12,
                    SubHeading("Master"),
                    TextBlock("Choose the enum action to use in the detail pane.")
                        .Foreground(Theme.SecondaryText),
                    ComboBox(ActionNames, selectedIndex, setSelectedIndex)
                        .Header("Action")
                        .AutomationName("Action selection")
                        .MinWidth(220)))
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .CornerRadius(8)
            .Padding(16)
            .Margin(24);

    static Element DetailPane(DetailAction selectedAction, string lastRun, Action triggerAction) =>
        Border(
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Star()],
                    SubHeading("Detail").Grid(row: 0),
                    TextBlock($"Selected enum: {selectedAction}")
                        .Foreground(Theme.PrimaryText)
                        .Margin(0, 12, 0, 0)
                        .Grid(row: 1),
                    Button("Trigger action", triggerAction)
                        .AutomationName($"Trigger {selectedAction} action")
                        .Margin(0, 16, 0, 0)
                        .HAlign(HorizontalAlignment.Left)
                        .Grid(row: 2),
                    TextBlock(lastRun)
                        .Foreground(Theme.SecondaryText)
                        .HeadingLevel(AutomationHeadingLevel.Level3)
                        .Margin(0, 20, 0, 0)
                        .Grid(row: 3)))
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .CornerRadius(8)
            .Padding(20)
            .Margin(0, 24, 24, 24);
}

