using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;

using static Microsoft.UI.Reactor.Core.Theme;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("DataGrid Action", width: 900, height: 600);

enum QueueAction
{
    Review,
    Approve,
    Reject
}

record QueueItem(int Id, string Request, string Owner, QueueAction LastAction, string Status);

class App : Component
{
    static readonly string[] ActionNames = Enum.GetNames<QueueAction>();

    public override Element Render()
    {
        var (items, setItems) = UseState<IReadOnlyList<QueueItem>>([
            new(1001, "Access package", "Mia", QueueAction.Review, "Waiting"),
            new(1002, "Release gate", "Noah", QueueAction.Review, "Waiting"),
            new(1003, "Budget change", "Ava", QueueAction.Review, "Waiting")
        ]);
        var (selectedAction, setSelectedAction) = UseState(QueueAction.Review);
        var (selectedRowKey, setSelectedRowKey) = UseState<RowKey?>(null);

        var selectedItem = selectedRowKey is null
            ? null
            : items.FirstOrDefault(item => new RowKey(item.Id.ToString()) == selectedRowKey);

        var actionGrid = Grid(
            [GridSize.Star(), GridSize.Px(180), GridSize.Px(140)],
            [GridSize.Auto, GridSize.Auto],
            [
                VStack(
                    SubHeading("Action queue"),
                    Caption(StatusText(selectedItem, selectedAction)).Foreground(SecondaryText)
                ).Grid(row: 0, column: 0),

                ComboBox(ActionNames, (int)selectedAction, index => setSelectedAction((QueueAction)index))
                    .Header("Action")
                    .Grid(row: 0, column: 1),

                Button("Trigger", () =>
                {
                    if (selectedItem is null)
                    {
                        return;
                    }

                    setItems(items.Select(item => item.Id == selectedItem.Id
                        ? item with
                        {
                            LastAction = selectedAction,
                            Status = $"{selectedAction} triggered"
                        }
                        : item).ToArray());
                })
                .Grid(row: 0, column: 2),

                Caption("The DataGrid uses single selection; the ComboBox provides the enum value.")
                    .Foreground(TertiaryText)
                    .Grid(row: 1, column: 0, columnSpan: 3)
            ]);

        var actionPanel = (actionGrid with
        {
            ColumnSpacing = 16,
            RowSpacing = 8
        }).Padding(16);

        var dataGrid = DataGrid(
            new InMemoryDataSource<QueueItem>(items, item => new RowKey(item.Id.ToString())),
            [
                Column<QueueItem>("Id", item => item.Id, displayName: "ID", width: 80),
                Column<QueueItem>("Request", item => item.Request, displayName: "Request", width: 220),
                Column<QueueItem>("Owner", item => item.Owner, displayName: "Owner", width: 140),
                Column<QueueItem>("LastAction", item => item.LastAction, displayName: "Last Action", width: 160),
                Column<QueueItem>("Status", item => item.Status, displayName: "Status", width: 200)
            ],
            selectionMode: SelectionMode.Single,
            onSelectionChanged: keys => setSelectedRowKey(keys.FirstOrDefault()));

        return Grid(
            [GridSize.Star()],
