using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;

ReactorApp.Run<App>("Tabbed DataGrid Actions", width: 900, height: 600);

enum GridAction
{
    Approve,
    Review,
    Archive
}

record ActionItem(string Id, GridAction Action, string Description);

class App : Component
{
    private static readonly List<ActionItem> ActionItems =
    [
        new("approve", GridAction.Approve, "Approve the selected item."),
        new("review", GridAction.Review, "Send the item to review."),
        new("archive", GridAction.Archive, "Archive the item.")
    ];

    private static readonly ListDataSource<ActionItem> ActionsSource =
        new(ActionItems, item => new RowKey(item.Id), false);

    private static readonly FieldDescriptor[] ActionColumns =
    [
        Column<ActionItem>("Action", item => item.Action, displayName: "Action", width: 160),
        Column<ActionItem>("Description", item => item.Description, displayName: "Description", width: 420)
    ];

    public override Element Render()
    {
        var (selectedAction, setSelectedAction) = UseState<GridAction?>(null);
        var (message, setMessage) = UseState("Select an action row to trigger it.");

        void TriggerAction(IReadOnlySet<RowKey> selectedKeys)
        {
            var selectedItem = ActionItems.FirstOrDefault(item => selectedKeys.Contains(new RowKey(item.Id)));

            if (selectedItem is null)
            {
                setSelectedAction(null);
                setMessage("Select an action row to trigger it.");
                return;
            }

            setSelectedAction(selectedItem.Action);
            setMessage($"{selectedItem.Action} triggered.");
        }

        return TabView(
            Tab("Actions", ActionsTab(selectedAction, message, TriggerAction)),
            Tab("Status", StatusTab(selectedAction, message))
        ).RequestedTheme(ElementTheme.Default);
    }

    private static Element ActionsTab(
        GridAction? selectedAction,
        string message,
        Action<IReadOnlySet<RowKey>> triggerAction)
    {
        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star(), GridSize.Auto],
            Heading("Action selector")
                .Grid(row: 0)
                .Margin(0, 0, 0, 12),
            Border(
                DataGrid(
                    ActionsSource,
                    ActionColumns,
                    selectionMode: SelectionMode.Single,
                    onSelectionChanged: triggerAction,
                    emptyTemplate: TextBlock("No actions available."),
                    showSearch: false
                )
            )
                .Grid(row: 1)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8),
            VStack(4,
                Caption("Selected enum"),
                TextBlock(selectedAction?.ToString() ?? "None"),
                Caption(message)
                    .Foreground(Theme.SecondaryText)
            )
                .Grid(row: 2)
                .Margin(0, 12, 0, 0)
        )
            .Padding(24)
            .Background(Theme.SolidBackground);
    }

    private static Element StatusTab(GridAction? selectedAction, string message)
    {
        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto],
            Heading("Status").Grid(row: 0),
            Border(
                VStack(8,
                    TextBlock($"Current action: {selectedAction?.ToString() ?? "None"}"),
                    Caption(message).Foreground(Theme.SecondaryText)
                )
                    .Padding(16)
            )
                .Grid(row: 1)
                .Margin(0, 16, 0, 0)
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
        )
            .Padding(24)
            .Background(Theme.SolidBackground);
    }
}

