using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

ReactorApp.Run<App>("Dialog DataGrid Flow", width: 980, height: 640);

enum WorkflowAction
{
    Approve,
    Review,
    Archive
}

record WorkItem(string Id, string Title, string Owner, string Status);

class App : Component
{
    static readonly IReadOnlyList<WorkItem> Items =
    [
        new("REQ-101", "Validate intake packet", "Mia", "Ready"),
        new("REQ-102", "Confirm compliance notes", "Noah", "Waiting"),
        new("REQ-103", "Publish customer summary", "Ava", "Ready"),
        new("REQ-104", "Archive closed request", "Liam", "Complete")
    ];

    static readonly string[] ActionLabels = Enum.GetNames<WorkflowAction>();

    public override Element Render()
    {
        var (selectedItem, setSelectedItem) = UseState<WorkItem?>(null);
        var (selectedAction, setSelectedAction) = UseState(WorkflowAction.Approve);
        var (dialogOpen, setDialogOpen) = UseState(false);
        var (lastResult, setLastResult) = UseState("Select a row, choose an action, then run it.");

        var source = new ListDataSource<WorkItem>(Items, item => item.Id);
        var columns = new FieldDescriptor[]
        {
            Column<WorkItem>("Id", item => item.Id, displayName: "Request", width: 120),
            Column<WorkItem>("Title", item => item.Title, displayName: "Title", width: 280),
            Column<WorkItem>("Owner", item => item.Owner, displayName: "Owner", width: 120),
            Column<WorkItem>("Status", item => item.Status, displayName: "Status", width: 120)
        };

        void OpenDialog(IReadOnlySet<RowKey> keys)
        {
            var key = keys.FirstOrDefault();
            var item = Items.FirstOrDefault(item => item.Id == key.Value);

            if (item is null)
            {
                return;
            }

            setSelectedItem(item);
            setSelectedAction(WorkflowAction.Approve);
            setDialogOpen(true);
        }

        var body = Grid(
            ["2*", "*"],
            ["Auto", "*", "Auto"],
            [
                VStack(4,
                    Heading("Request workflow"),
                    TextBlock("Selecting a DataGrid row opens a dialog where an enum-backed action can be chosen."))
                    .Grid(row: 0, column: 0, columnSpan: 2)
                    .Margin(0, 0, 0, 16),

                DataGrid(
                    source,
                    columns,
                    selectionMode: SelectionMode.Single,
                    onSelectionChanged: OpenDialog,
                    rowHeight: 44,
                    emptyTemplate: TextBlock("No requests available."))
                    .Grid(row: 1, column: 0)
                    .MinHeight(360),

                Border(
                    VStack(12,
                        SubHeading("Selected action"),
                        TextBlock(selectedItem is null
                            ? "No request selected"
                            : $"{selectedItem.Id}: {selectedItem.Title}"),
                        RadioButtons(
                            ActionLabels,
                            (int)selectedAction,
                            index => setSelectedAction((WorkflowAction)index))
                            .Disabled(selectedItem is null),
                        Button("Run selected action", () => setDialogOpen(true))
                            .Disabled(selectedItem is null)))
                    .Grid(row: 1, column: 1)
                    .Margin(16, 0, 0, 0)
                    .Padding(16)
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke)
                    .CornerRadius(8),

                TextBlock(lastResult)
                    .Grid(row: 2, column: 0, columnSpan: 2)
                    .Margin(0, 16, 0, 0)
                    .Foreground(Theme.SecondaryText)
            ])
            .Padding(24)
            .Background(Theme.SolidBackground)
            .RequestedTheme(ElementTheme.Default);

        return Group(
            body,
            new ContentDialogElement(
                selectedItem is null ? "Choose action" : $"Run {selectedAction}",
                VStack(12,
                    TextBlock(selectedItem is null
                        ? "Select a request before running an action."
                        : $"{selectedAction} will be applied to {selectedItem.Id}."),
                    RadioButtons(
                        ActionLabels,
                        (int)selectedAction,
                        index => setSelectedAction((WorkflowAction)index))),
                "Run")
            {
                IsOpen = dialogOpen,
                CloseButtonText = "Cancel",
                OnClosed = result =>
                {
                    setDialogOpen(false);

                    if (result == ContentDialogResult.Primary && selectedItem is not null)
                    {
                        setLastResult($"{selectedAction} triggered for {selectedItem.Id}.");
                    }
                }
            });
    }
}

