﻿using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Core.Theme;

ReactorApp.Run<App>("ReactorEnumTextBoxApp", width: 720, height: 420);

enum TextAction
{
    Echo,
    Uppercase,
    CharacterCount
}

class App : Component
{
    static readonly string[] ActionNames = Enum.GetNames<TextAction>();

    public override Element Render()
    {
        var (inputText, setInputText) = UseState("");
        var (selectedAction, setSelectedAction) = UseState(TextAction.Echo);
        var (result, setResult) = UseState("Type text, choose an action, then run it.");

        void RunSelectedAction()
        {
            setResult(selectedAction switch
            {
                TextAction.Echo => inputText,
                TextAction.Uppercase => inputText.ToUpperInvariant(),
                TextAction.CharacterCount => $"{inputText.Length} characters",
                _ => inputText
            });
        }

        return Border(
            (Grid(
                columns: ["180", "*"],
                rows: ["Auto", "Auto", "Auto", "Auto", "Auto"],
                [
                    Heading("Text action").Grid(row: 0, column: 0, columnSpan: 2),
                    Caption("Enter text and choose the enum action to run.")
                        .Foreground(SecondaryText)
                        .Grid(row: 1, column: 0, columnSpan: 2),

                    TextBlock("TextBox").Grid(row: 2, column: 0),
                    TextField(inputText, setInputText, placeholder: "Text to process")
                        .AutomationName("TextBoxInput")
                        .OnKeyDown((_, e) =>
                        {
                            if (e.Key == Windows.System.VirtualKey.Enter)
                            {
                                RunSelectedAction();
                                e.Handled = true;
                            }
                        })
                        .Grid(row: 2, column: 1),

                    TextBlock("Action").Grid(row: 3, column: 0),
                    ComboBox(ActionNames, (int)selectedAction, index => setSelectedAction((TextAction)index))
                        .AutomationName("ActionSelection")
                        .Grid(row: 3, column: 1),

                    Button("Run action", RunSelectedAction)
                        .Grid(row: 4, column: 0),
                    Border(TextBlock(result).Foreground(PrimaryText))
                        .Background(CardBackground)
                        .WithBorder(CardStroke, 1)
                        .CornerRadius(8)
                        .Padding(12)
                        .Grid(row: 4, column: 1)
                ]) with
            {
                RowSpacing = 12,
                ColumnSpacing = 16
            })
            .Background(CardBackground)
            .WithBorder(CardStroke, 1)
            .CornerRadius(12)
            .Padding(24)
            .Margin(32)
            .RequestedTheme(ElementTheme.Default);
    }
}

