                        TextField(
                                state.InputText,
                                value => UpdateState(current => current with { InputText = value }),
                                placeholder: "Text to send with the action",
                                header: "TextBox trigger")
                            .OnKeyDown((_, args) =>
                            {
                                if (args.Key == Windows.System.VirtualKey.Enter)
                                {
                                    TriggerAction();
                                }
