namespace ReactorRadioEnumApp;

using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

class Program
{
    static void Main(string[] args)
    {
        ReactorApp.Run<App>("ReactorRadioEnumApp", width: 900, height: 600);
    }
}

enum ActionChoice
{
    Start,
    Pause,
    Stop
}

class App : Component
{
    public override Element Render()
    {
        var (choice, setChoice) = UseState(ActionChoice.Start);
        var (message, setMessage) = UseState("Start selected");

        return Grid(
            ["Auto", "*"],
            ["Auto", "Auto", "Auto", "Auto"],
            Heading("Radio action selector")
                .Grid(row: 0, column: 0, columnSpan: 2),
            OptionButton(ActionChoice.Start, choice, setChoice, setMessage)
                .Grid(row: 1, column: 0),
            OptionButton(ActionChoice.Pause, choice, setChoice, setMessage)
                .Grid(row: 2, column: 0),
            OptionButton(ActionChoice.Stop, choice, setChoice, setMessage)
                .Grid(row: 3, column: 0),
            TextBlock(message)
                .Grid(row: 1, column: 1, rowSpan: 3)
                .VerticalAlignment(VerticalAlignment.Center)
        )
        .Margin(32)
        .RequestedTheme(ElementTheme.Default);
    }

    static RadioButtonElement OptionButton(
        ActionChoice option,
        ActionChoice selected,
        Action<ActionChoice> setChoice,
        Action<string> setMessage)
    {
        return new RadioButtonElement(
            option.ToString(),
            option == selected,
            isChecked =>
            {
                if (isChecked)
                {
                    setChoice(option);
                    setMessage($"{option} selected");
                }
            },
            "ActionChoice");
    }
}

