using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Core.Theme;

ReactorApp.Run<MasterDetailApp>("Master Detail Radio", width: 900, height: 600);

enum DetailSelection
{
    Overview,
    Activity,
    Settings,
}

record AppState(DetailSelection Selection, string LastAction)
{
    public static AppState Initial => new(DetailSelection.Overview, "Loaded Overview");
}

abstract record AppAction;
record SelectDetail(DetailSelection Selection) : AppAction;

static class AppReducer
{
    public static AppState Reduce(AppState state, AppAction action) => action switch
    {
        SelectDetail select => state with
        {
            Selection = select.Selection,
            LastAction = $"Selected {LabelFor(select.Selection)}"
        },
        _ => state
    };

    public static string LabelFor(DetailSelection selection) => selection switch
    {
        DetailSelection.Overview => "Overview",
        DetailSelection.Activity => "Activity",
        DetailSelection.Settings => "Settings",
        _ => selection.ToString()
    };
}

class MasterDetailApp : Component
{
    public override Element Render()
    {
        var (state, dispatch) = UseReducer<AppState, AppAction>(AppReducer.Reduce, AppState.Initial);

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            (TitleBar("Master Detail") with
            {
                Subtitle = "RadioButton enum selection"
            }).Grid(row: 0),
            (Grid(
                columns: [GridSize.Auto, GridSize.Star()],
                rows: [GridSize.Star()],
                MasterPane(state.Selection, dispatch)
                    .Grid(row: 0, column: 0),
                DetailPane(state)
                    .Grid(row: 0, column: 1)
            ) with
            {
                ColumnSpacing = 16
            }).Padding(24).Grid(row: 1)
        ).RequestedTheme(ElementTheme.Default);
    }

    static Element MasterPane(DetailSelection selected, Action<AppAction> dispatch) =>
        Border(
            VStack(12,
                SubHeading("Master"),
                Caption("Choose a section").Foreground(SecondaryText),
                RadioOption(DetailSelection.Overview, selected, dispatch),
                RadioOption(DetailSelection.Activity, selected, dispatch),
                RadioOption(DetailSelection.Settings, selected, dispatch)
            ).Padding(20)
        )
        .Width(240)
        .Background(CardBackground)
        .WithBorder(CardStroke)
        .CornerRadius(8);

    static Element RadioOption(
        DetailSelection option,
        DetailSelection selected,
        Action<AppAction> dispatch) =>
        RadioButton(
            AppReducer.LabelFor(option),
            selected == option,
            isChecked =>
            {
                if (isChecked)
                {
                    dispatch(new SelectDetail(option));
                }
            },
            groupName: "detail-selection");

    static Element DetailPane(AppState state) =>
        Border(
            Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Star],
                Heading(AppReducer.LabelFor(state.Selection))
                    .Grid(row: 0),
                Caption(state.LastAction)
                    .Foreground(SecondaryText)
                    .Margin(0, 8, 0, 20)
                    .Grid(row: 1),
                TextBlock(DescriptionFor(state.Selection))
                    .TextWrapping()
                    .Grid(row: 2)
            ).Padding(24)
        )
        .Background(CardBackground)
        .WithBorder(CardStroke)
        .CornerRadius(8);

    static string DescriptionFor(DetailSelection selection) => selection switch
    {
        DetailSelection.Overview => "Overview shows the selected record summary in the detail pane.",
        DetailSelection.Activity => "Activity shows recent work for the selected record.",
        DetailSelection.Settings => "Settings shows editable preferences for the selected record.",
        _ => string.Empty
    };
}

