﻿using Microsoft.UI.Xaml;

ReactorApp.Run<App>("DialogRadioFlow", width: 900, height: 600);

enum DialogAction
{
    Approve,
    Defer,
    Reject
}

class App : Component
{
    public override Element Render()
    {
        var (selectedAction, setSelectedAction) = UseState(DialogAction.Approve);
        var (actionMessage, setActionMessage) = UseState("Approve action is ready.");

        Element ActionOption(DialogAction action, string label, string description)
            => RadioButton(label, selectedAction == action, isChecked =>
                {
                    if (!isChecked)
                    {
                        return;
                    }

                    setSelectedAction(action);
                    setActionMessage($"{label} action is ready.");
                },
                groupName: "dialog-action")
                .Grid((int)action + 2, 0);

        return Grid(
            columns: [GridSize.Auto(), GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Auto(), GridSize.Auto(), GridSize.Auto(), GridSize.Auto(), GridSize.Auto()],
            [
                Heading("Review dialog").Grid(0, 0, columnSpan: 2),

                TextBlock("Choose the action this dialog should run.")
                    .Grid(1, 0, columnSpan: 2),

                ActionOption(DialogAction.Approve, "Approve", "Continue with the approval action."),
                TextBlock("Continue with the approval action.")
                    .Grid(2, 1),

                ActionOption(DialogAction.Defer, "Defer", "Pause this item for later review."),
                TextBlock("Pause this item for later review.")
                    .Grid(3, 1),

                ActionOption(DialogAction.Reject, "Reject", "Stop the request and mark it rejected."),
                TextBlock("Stop the request and mark it rejected.")
                    .Grid(4, 1),

                TextBlock(actionMessage)
                    .Grid(5, 0, columnSpan: 2)
            ])
            .RequestedTheme(ElementTheme.Default)
            .Margin(32);
    }
}

