using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

ReactorApp.Run<App>("ReactorDialogFlow", width: 900, height: 600);

class App : Component
{
    private static readonly string[] ActionNames = Enum.GetNames<DialogAction>();

    public override Element Render()
    {
        var (selectedAction, setSelectedAction) = UseState(DialogAction.Approve);
        var (isToggleOn, setIsToggleOn) = UseState(false);
        var (isDialogOpen, setIsDialogOpen) = UseState(false);
        var (lastResult, setLastResult) = UseState("Toggle the flow on to review and run the selected action.");

        return Grid(
            columns: ["220", "*"],
            rows: ["Auto", "Auto", "Auto", "Auto", "*"],
            Heading("Dialog action flow")
                .Grid(row: 0, column: 0, columnSpan: 2),
            TextBlock("Select action")
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 1, column: 0),
            ComboBox(
                    ActionNames,
                    selectedIndex: (int)selectedAction,
                    onSelectionChanged: index => setSelectedAction((DialogAction)index))
                with
                {
                    Header = "Enum value"
                }
                .Grid(row: 1, column: 1),
            TextBlock("Trigger")
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 2, column: 0),
            ToggleSwitch(
                    isToggleOn,
                    isOn =>
                    {
                        setIsToggleOn(isOn);
                        setIsDialogOpen(isOn);
                    },
                    onContent: "Dialog flow armed",
                    offContent: "Dialog flow idle",
                    header: "Run selected action")
                .Grid(row: 2, column: 1),
            TextBlock("Result")
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 3, column: 0),
            TextBlock(lastResult)
                .TextWrapping(TextWrapping.Wrap)
                .Grid(row: 3, column: 1),
            ContentDialog(
                    title: $"{selectedAction} action",
                    content: VStack(
                        12,
                        TextBlock($"The toggle opened this dialog for the {selectedAction} enum selection."),
                        TextBlock("Choose Run to complete the action or Cancel to return to the grid.").TextWrapping(TextWrapping.Wrap)),
                    primaryButtonText: "Run")
                with
                {
                    IsOpen = isDialogOpen,
                    CloseButtonText = "Cancel",
                    DefaultButton = ContentDialogButton.Primary,
                    OnClosed = result =>
                    {
                        setLastResult(result == ContentDialogResult.Primary
                            ? $"{selectedAction} completed."
                            : $"{selectedAction} canceled.");
                        setIsDialogOpen(false);
                        setIsToggleOn(false);
                    }
                })
            with
            {
                RowSpacing = 16,
                ColumnSpacing = 24
            }
            .Padding(32)
            .RequestedTheme(ElementTheme.Default);
    }
}

enum DialogAction
{
    Approve,
    Retry,
    Archive
}

