using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;

ReactorApp.Run<App>("ReactorSample", width: 900, height: 600);

enum OrderState
{
    New,
    Processing,
    Complete,
}

record Order(int Id, string Customer, OrderState State);

class App : Component
{
    static readonly Order[] Orders =
    [
        new(1, "Contoso", OrderState.New),
        new(2, "Northwind", OrderState.Processing),
        new(3, "Tailspin", OrderState.Complete),
        new(4, "Fabrikam", OrderState.New),
        new(5, "Adventure Works", OrderState.Processing),
    ];

    static readonly string[] OrderStateNames = Enum.GetNames<OrderState>();

    public override Element Render()
    {
        var (selectedState, setSelectedState) = UseState(OrderState.New);

        var visibleOrders = UseMemo(
            () => Orders.Where(order => order.State == selectedState).ToArray(),
            selectedState);

        var source = UseMemo(
            () => new ListDataSource<Order>(visibleOrders, order => (RowKey)order.Id),
            visibleOrders);

        return (Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Star],
            Heading("Orders").Grid(row: 0),
            HStack(8,
                TextBlock("State:"),
                ComboBox(
                    OrderStateNames,
                    (int)selectedState,
                    index => setSelectedState((OrderState)index))
                    .Width(180)
