using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<TabbedDataGridApp>("Tabbed DataGrid App", width: 900, height: 620);

enum RequestState
{
    Proposed,
    Active,
    Complete
}

sealed record RequestItem(string Id, string Title, string Owner, RequestState State);

sealed class RequestDataSource(IReadOnlyList<RequestItem> items) : IDataSource<RequestItem>
{
    public DataSourceCapabilities Capabilities => DataSourceCapabilities.None;

    public Task<DataPage<RequestItem>> GetPageAsync(DataRequest request, CancellationToken cancellationToken)
    {
        var page = request.PageSize > 0 ? items.Take(request.PageSize).ToArray() : items;
        return Task.FromResult(new DataPage<RequestItem>(page, continuationToken: null, totalCount: items.Count));
    }

    public RowKey GetRowKey(RequestItem item) => new(item.Id);
}

class TabbedDataGridApp : Component
{
    static readonly RequestItem[] Requests =
    [
        new("REQ-101", "Capture sign-off", "Avery", RequestState.Proposed),
        new("REQ-102", "Build enum filter", "Blake", RequestState.Active),
        new("REQ-103", "Verify clean build", "Casey", RequestState.Complete),
        new("REQ-104", "Review grid layout", "Drew", RequestState.Active),
        new("REQ-105", "Publish notes", "Emery", RequestState.Proposed),
    ];

    static readonly RequestState[] States = Enum.GetValues<RequestState>();
    static readonly string[] StateLabels = States.Select(state => state.ToString()).ToArray();
    static readonly IReadOnlyList<FieldDescriptor> RequestColumns =
    [
        Column<RequestItem>("Id", item => item.Id, displayName: "ID", width: 110),
        Column<RequestItem>("Title", item => item.Title, width: 280),
        Column<RequestItem>("Owner", item => item.Owner, width: 140),
        Column<RequestItem>("State", item => item.State, displayName: "Status", width: 140)
            .CellRenderer(value => TextBlock(value?.ToString() ?? string.Empty)),
    ];

    public override Element Render()
    {
        var (selectedState, setSelectedState) = UseState(RequestState.Active);
        var selectedIndex = Array.IndexOf(States, selectedState);
        var visibleRequests = Requests.Where(request => request.State == selectedState).ToArray();

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            VStack(4,
                TextBlock("Tabbed request tracker").Title(),
                TextBlock("Choose a status; the DataGrid is bound to that enum state.")
                    .Foreground(Theme.SecondaryText)
            )
            .Grid(row: 0, column: 0),
            TabView(
                Tab("Requests",
                    Grid(
                        columns: [GridSize.Star()],
                        rows: [GridSize.Auto, GridSize.Star()],
                        ComboBox(StateLabels, selectedIndex, index => setSelectedState(States[index]))
                            .Header("Request status")
                            .Grid(row: 0, column: 0),
                        Border(
                            DataGrid(
                                source: new RequestDataSource(visibleRequests),
                                columns: RequestColumns,
                                selectionMode: SelectionMode.Single,
                                rowHeight: 44,
                                emptyTemplate: TextBlock($"No {selectedState} requests.").Foreground(Theme.SecondaryText)
                            )
                        )
                        .Padding(12)
                        .CornerRadius(8)
                        .Background(Theme.CardBackground)
                        .WithBorder(Theme.CardStroke, 1)
                        .Grid(row: 1, column: 0)
                        .Margin(0, 12, 0, 0)
                    )
                    .Padding(16)),
                Tab("Selection",
                    Border(
                        VStack(8,
                            TextBlock("Current enum selection").SemiBold(),
                            TextBlock(selectedState.ToString()).Title(),
                            TextBlock($"{visibleRequests.Length} matching request(s)")
                                .Foreground(Theme.SecondaryText)
                        )
                    )
                    .Padding(20)
                    .CornerRadius(8)
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .Margin(16))
            )
            .ShowAddButton(false)
            .Grid(row: 1, column: 0)
            .Margin(0, 18, 0, 0)
        )
        .Padding(24)
        .Background(Theme.SolidBackground);
    }
}

