using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog DataGrid Enum Flow", width: 920, height: 600);

enum RequestDecision
{
    Approve,
    Review,
    Reject
}

sealed record RequestItem(string Id, string Title, string Owner, string Status);

static class RequestItems
{
    public static readonly IReadOnlyList<RequestItem> All =
    [
        new("REQ-101", "Validate intake packet", "Mia", "Ready"),
        new("REQ-102", "Confirm compliance notes", "Noah", "Waiting"),
        new("REQ-103", "Publish customer summary", "Ava", "Ready"),
        new("REQ-104", "Archive closed request", "Liam", "Complete")
    ];

    public static RequestItem? Find(RowKey key) =>
        All.FirstOrDefault(item => item.Id == key.Value);
}

sealed class RequestDataSource : ListDataSource<RequestItem>
{
    public RequestDataSource()
        : base(RequestItems.All.ToList(), item => new RowKey(item.Id), false)
    {
    }
}

class App : Component
{
    static readonly string[] DecisionLabels = Enum.GetNames<RequestDecision>();

    public override Element Render()
    {
        var (selectedRequest, setSelectedRequest) = UseState<RequestItem?>(null);
        var (selectedDecision, setSelectedDecision) = UseState(RequestDecision.Approve);
        var (dialogOpen, setDialogOpen) = UseState(false);
        var (lastResult, setLastResult) = UseState("Select a request in the grid to choose a decision.");

        void OpenDecisionDialog(IReadOnlySet<RowKey> keys)
        {
            var request = RequestItems.Find(keys.FirstOrDefault());

            if (request is null)
            {
                return;
            }

            setSelectedRequest(request);
            setSelectedDecision(RequestDecision.Approve);
            setDialogOpen(true);
        }

        return Group(
            Grid(
                columns: [GridSize.Star(2), GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Star(), GridSize.Auto],
                VStack(4,
                    Heading("Request decisions"),
                    Caption("Pick a row from the DataGrid, then choose an enum-backed decision in the dialog.")
                        .Foreground(Theme.SecondaryText))
                    .Grid(0, 0, columnSpan: 2)
                    .Margin(0, 0, 0, 16),
                Border(
                    DataGrid(
                        new RequestDataSource(),
                        CreateColumns(),
                        selectionMode: SelectionMode.Single,
                        onSelectionChanged: OpenDecisionDialog,
                        rowHeight: 44,
                        emptyTemplate: Caption("No requests available.")))
                    .Padding(12)
                    .CornerRadius(12)
                    .Background(Theme.LayerFill)
                    .WithBorder(Theme.CardStroke)
                    .Grid(1, 0),
                Border(
                    VStack(12,
                        SubHeading("Current selection"),
                        TextBlock(selectedRequest is null
                            ? "No request selected"
                            : $"{selectedRequest.Id}: {selectedRequest.Title}"),
                        TextBlock($"Decision state: {selectedDecision}")
                            .Foreground(Theme.SecondaryText),
                        Button("Open dialog", () => setDialogOpen(true))
                            .Disabled(selectedRequest is null)))
                    .Padding(16)
                    .CornerRadius(12)
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke)
                    .Grid(1, 1)
                    .Margin(16, 0, 0, 0),
                Caption(lastResult)
                    .Foreground(Theme.SecondaryText)
                    .Grid(2, 0, columnSpan: 2)
                    .Margin(0, 16, 0, 0))
                .Padding(24)
                .Background(Theme.SolidBackground)
                .RequestedTheme(ElementTheme.Default),
            ContentDialog(
                selectedRequest is null ? "Choose decision" : $"Decision for {selectedRequest.Id}",
                VStack(12,
                    TextBlock(selectedRequest is null
                        ? "Select a request before choosing a decision."
                        : $"{selectedRequest.Title} is ready for a decision."),
                    RadioButtons(
                        DecisionLabels,
                        (int)selectedDecision,
                        index => setSelectedDecision((RequestDecision)index))),
                primaryButtonText: "Apply") with
            {
                IsOpen = dialogOpen,
                CloseButtonText = "Cancel",
                OnClosed = result =>
                {
                    setDialogOpen(false);

                    if (result == ContentDialogResult.Primary && selectedRequest is not null)
                    {
                        setLastResult($"{selectedDecision} applied to {selectedRequest.Id}.");
                    }
                }
            });
    }

    static IReadOnlyList<FieldDescriptor> CreateColumns() =>
    [
        Column<RequestItem>("Id", request => request.Id, displayName: "Request", width: 120),
        Column<RequestItem>("Title", request => request.Title, displayName: "Title", width: 300),
        Column<RequestItem>("Owner", request => request.Owner, displayName: "Owner", width: 120),
        Column<RequestItem>("Status", request => request.Status, displayName: "Status", width: 120)
    ];
}

