using Microsoft.UI.Xaml;
using Microsoft.UI.Reactor.Layout;

ReactorApp.Run<App>("Master Detail Slider", width: 900, height: 600);

enum DetailSelection
{
    Overview,
    Metrics,
    Activity,
    Settings
}

class App : Component
{
    private static readonly DetailSelection[] Selections = Enum.GetValues<DetailSelection>();

    public override Element Render()
    {
        var (selection, setSelection) = UseState(DetailSelection.Overview);
        var selectedIndex = Array.IndexOf(Selections, selection);

        void SelectDetail(double value)
        {
            var index = Math.Clamp((int)Math.Round(value), 0, Selections.Length - 1);
            setSelection(Selections[index]);
        }

        var detailTitle = selection switch
        {
            DetailSelection.Overview => "Project overview",
            DetailSelection.Metrics => "Usage metrics",
            DetailSelection.Activity => "Recent activity",
            DetailSelection.Settings => "Configuration",
            _ => selection.ToString()
        };

        var detailText = selection switch
        {
            DetailSelection.Overview => "A concise summary of the selected project appears here.",
            DetailSelection.Metrics => "Key measurements and trends for the selected project appear here.",
            DetailSelection.Activity => "Recent updates, notes, and changes for the selected project appear here.",
            DetailSelection.Settings => "Configuration details for the selected project appear here.",
            _ => string.Empty
        };

        return Grid(
                columns: [GridSize.Px(320), GridSize.Star()],
                rows: [GridSize.Star()],
                Border(
                        VStack(16,
                            Heading("Master"),
                            TextBlock("Move the slider to choose which detail pane is selected.")
                                .Foreground(Theme.SecondaryText),
                            Slider(selectedIndex, min: 0, max: Selections.Length - 1, onChanged: SelectDetail)
                                .Header("Detail selection")
                                .StepFrequency(1)
                                .SmallChange(1)
                                .LargeChange(1),
                            SubHeading(selection.ToString())))
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke)
                    .Padding(24)
                    .Grid(row: 0, column: 0),
                Border(
                        VStack(16,
                            Heading("Detail"),
                            SubHeading(detailTitle),
                            TextBlock(detailText)
                                .Foreground(Theme.SecondaryText),
                            TextBlock($"Enum state: {selection}")
                                .Foreground(Theme.PrimaryText)))
                    .Background(Theme.SolidBackground)
                    .Padding(32)
                    .Grid(row: 0, column: 1))
            .RequestedTheme(ElementTheme.Default);
    }
}

