using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

ReactorApp.Run<App>("DialogFlowApp", width: 640, height: 460);

enum DialogChoice
{
    Basic,
    Advanced,
    Custom
}

class App : Component
{
    public override Element Render()
    {
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (selectedChoice, setSelectedChoice) = UseState(DialogChoice.Basic);
        var (confirmedChoice, setConfirmedChoice) = UseState(DialogChoice.Basic);

        return (Grid(
            [GridSize.Star()],
            [GridSize.Auto, GridSize.Auto, GridSize.Auto, GridSize.Star()],
            Heading("Dialog flow"),
            TextBlock($"Current selection: {LabelFor(selectedChoice)}")
                .Foreground(Theme.SecondaryText)
                .Grid(row: 1),
            TextBlock($"Confirmed selection: {LabelFor(confirmedChoice)}")
                .Foreground(Theme.SecondaryText)
                .Grid(row: 2),
            Button("Choose option", () => setDialogOpen(true))
                .HAlign(HorizontalAlignment.Left)
                .Grid(row: 3),
            ContentDialog(
                "Choose a dialog path",
                DialogChoiceGrid(selectedChoice, setSelectedChoice),
                "Continue") with
            {
                IsOpen = isDialogOpen,
                SecondaryButtonText = "Cancel",
                DefaultButton = ContentDialogButton.Primary,
                OnClosed = result =>
                {
                    if (result == ContentDialogResult.Primary)
                    {
                        setConfirmedChoice(selectedChoice);
                    }

                    setDialogOpen(false);
                },
            }
        ) with
        {
            RowSpacing = 12,
        }).Margin(32).RequestedTheme(ElementTheme.Default);
    }

    private static Element DialogChoiceGrid(
        DialogChoice selectedChoice,
        Action<DialogChoice> setSelectedChoice)
    {
        return Grid(
            [GridSize.Auto, GridSize.Star],
            [GridSize.Auto, GridSize.Auto, GridSize.Auto],
            TextBlock("Basic")
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 0, column: 0),
            RadioButton(
                "Start with defaults",
                selectedChoice == DialogChoice.Basic,
                isChecked =>
                {
                    if (isChecked) setSelectedChoice(DialogChoice.Basic);
                },
                "dialogChoice")
                .Grid(row: 0, column: 1),
            TextBlock("Advanced")
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 1, column: 0),
            RadioButton(
                "Review extra settings",
                selectedChoice == DialogChoice.Advanced,
                isChecked =>
                {
                    if (isChecked) setSelectedChoice(DialogChoice.Advanced);
                },
                "dialogChoice")
                .Grid(row: 1, column: 1),
            TextBlock("Custom")
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 2, column: 0),
            RadioButton(
                "Configure manually",
                selectedChoice == DialogChoice.Custom,
                isChecked =>
                {
                    if (isChecked) setSelectedChoice(DialogChoice.Custom);
                },
                "dialogChoice")
                .Grid(row: 2, column: 1)
        ) with
        {
            RowSpacing = 8,
            ColumnSpacing = 16,
        };
    }

    private static string LabelFor(DialogChoice choice) => choice switch
    {
        DialogChoice.Basic => "Basic",
        DialogChoice.Advanced => "Advanced",
        DialogChoice.Custom => "Custom",
        _ => choice.ToString(),
    };
}

