using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<EnumFilterApp>("Enum Filter Grid", width: 760, height: 560);

enum WorkCategory
{
    All,
    Design,
    Build,
    Test
}

sealed record WorkItem(string Title, string Description, WorkCategory Category);

class EnumFilterApp : Component
{
    static readonly IReadOnlyList<WorkItem> Items =
    [
        new("Sketch onboarding", "Map the first-run flow and empty states.", WorkCategory.Design),
        new("Create component shell", "Build the reusable page structure.", WorkCategory.Build),
        new("Review spacing", "Check card rhythm against the default theme.", WorkCategory.Design),
        new("Wire state", "Connect the filter selection to the visible list.", WorkCategory.Build),
        new("Smoke test filters", "Confirm every category shows the expected rows.", WorkCategory.Test),
        new("Verify build", "Keep the sample compiling cleanly.", WorkCategory.Test)
    ];

    public override Element Render()
    {
        var (selectedCategory, setSelectedCategory) = UseState(WorkCategory.All);
        var filteredItems = selectedCategory == WorkCategory.All
            ? Items
            : Items.Where(item => item.Category == selectedCategory).ToList();

        Element FilterButton(WorkCategory category) =>
            Button(category.ToString(), () => setSelectedCategory(category))
                .AutomationName($"Show {category} items");

        Element ItemCard(WorkItem item) =>
            Border(
                VStack(6,
                    Caption(item.Category.ToString()).Foreground(Theme.SecondaryText),
                    TextBlock(item.Title).SemiBold().Foreground(Theme.PrimaryText),
                    TextBlock(item.Description).Foreground(Theme.SecondaryText)
                )
                .Padding(14)
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(10);

        var rows = Enumerable
            .Repeat(GridSize.Auto, 2 + Math.Max(1, (int)Math.Ceiling(filteredItems.Count / 2.0)))
            .ToArray();

        var children = new List<Element>
        {
            VStack(4,
                Heading("Work items"),
                TextBlock("Choose a category to filter the list.")
                    .Foreground(Theme.SecondaryText)
            )
            .Grid(0, 0, columnSpan: 2),

            HStack(8, Enum.GetValues<WorkCategory>().Select(FilterButton).ToArray())
                .Grid(1, 0, columnSpan: 2)
        };

        children.AddRange(filteredItems.Select((item, index) =>
            ItemCard(item).Grid(2 + index / 2, index % 2)));

        return Grid(
            columns: [GridSize.Star(), GridSize.Star()],
            rows: rows,
            children.ToArray()
        )
        .Padding(24)
        .RowSpacing(12)
        .ColumnSpacing(12)
        .Background(Theme.SolidBackground);
    }
}

