        new(3, "Implement token export", WorkStage.Active, "Casey", "Wire the export command to the current token usage selection."),
        new(4, "Tune warning thresholds", WorkStage.Active, "Devon", "Adjust thresholds so heavy usage is visible before limits are hit."),
        new(5, "Ship settings polish", WorkStage.Done, "Emery", "Final pass on labels, spacing, and default values."),
        new(6, "Validate detail pane", WorkStage.Done, "Finley", "Checked that master selection keeps the detail pane synchronized."),
    ];

