                        ])
                    .Padding(16))
                .Background(CardBackground)
                .WithBorder(CardStroke, 1)
                .CornerRadius(8)
                .Margin(16, 16, 8, 16)
                .Grid(row: 1, column: 0),

                Border(
                    Grid(
                        ["120", "*"],
                        ["Auto", "Auto", "Auto", "Auto"],
                        [
