using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using static Microsoft.UI.Reactor.Core.Theme;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("DataGrid Action", width: 720, height: 480);

record ActionRow(int Id, string Name, string Value);

class App : Component
{
    public override Element Render()
    {
        var rows = UseMemo(() => new[]
        {
            new ActionRow(1, "Greet", "Hello from the DataGrid"),
            new ActionRow(2, "Confirm", "Action confirmed"),
            new ActionRow(3, "Reset", "Ready"),
        });

        var source = UseMemo(() =>
            new ListDataSource<ActionRow>(rows, row => (RowKey)row.Id), rows);

        var (message, setMessage) = UseState("Select a row to trigger its string action.");
        Action<string> triggerAction = value => setMessage(value);

        return Grid(
            columns: ["*"],
            rows: ["Auto", "Auto", "*"],
            Heading("DataGrid Action")
                .Grid(row: 0),
            Border(
                TextBlock(message)
                    .Foreground(PrimaryText)
                    .Padding(4)
            )
                .Background(CardBackground)
                .WithBorder(CardStroke, 1)
                .CornerRadius(8)
                .Padding(12)
                .Margin(0, 12, 0, 12)
                .Grid(row: 1),
            DataGrid(
                source: source,
                columns:
                [
                    Column<ActionRow>("Id", row => row.Id, width: 80),
                    Column<ActionRow>("Name", row => row.Name, displayName: "Action", width: 180),
                    Column<ActionRow>("Value", row => row.Value, displayName: "String", width: 320),
                ],
                selectionMode: SelectionMode.Single,
                onSelectionChanged: selected =>
                {
                    var selectedId = selected.FirstOrDefault()?.Value;
                    var selectedRow = rows.FirstOrDefault(row => Equals(row.Id, selectedId));
                    if (selectedRow is not null)
                    {
                        triggerAction(selectedRow.Value);
                    }
                },
                rowHeight: 36
            )
                .Grid(row: 2)
        ).Padding(24);
    }
}

