        var (submittedValue, setSubmittedValue) = UseState("");

        return Grid(
            columns: new[] { "Auto", "*" },
            rows: new[] { "Auto", "Auto", "Auto", "Auto" },
            children: new Element[]
            {
                Heading("String form")
                    .Grid(row: 0, column: 0, columnSpan: 2)
                    .Margin(bottom: 16),

                TextBlock("Value")
                    .Grid(row: 1, column: 0)
                    .Margin(right: 12)
                    .VAlign(VerticalAlignment.Center),

                TextField(value, setValue, placeholder: "Enter a string")
                    .Grid(row: 1, column: 1),

                Button("Submit", () => setSubmittedValue(value))
                    .Grid(row: 2, column: 1)
                    .Margin(top: 12)
                    .HAlign(HorizontalAlignment.Left),

                TextBlock(string.IsNullOrEmpty(submittedValue)
                        ? "No string submitted yet."
                        : $"Submitted: {submittedValue}")
                    .Grid(row: 3, column: 0, columnSpan: 2)
                    .Margin(top: 16)
                    .Foreground(Theme.SecondaryText)
            })
            .Padding(24)
            .Background(Theme.SolidBackground);
    }
}

