class App : Component
{
    public override Element Render()
    {
        var (isSelected, setIsSelected) = UseState(false);
        var (actionText, setActionText) = UseState("Choose the radio button to trigger the action.");

        return Grid(
            columns: ["*"],
            rows: ["Auto", "Auto", "*"],
            Heading("Radio button action").Grid(0, 0),
            RadioButton(
                "Trigger string action",
                isSelected,
                isChecked =>
                {
                    setIsSelected(isChecked);
                    if (isChecked)
                    {
                        setActionText("The RadioButton triggered this string action.");
                    }
                },
                groupName: "actions").Grid(1, 0).Margin(top: 16),
            Border(TextBlock(actionText).Foreground(Theme.PrimaryText))
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(2, 0)
                .Margin(top: 16)
        ).Padding(24);
    }
}

