using System.Linq;
using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail", width: 820, height: 520);

class App : Component
{
    static readonly string[] Items = ["Alpha", "Beta", "Gamma"];

    public override Element Render()
    {
        var (selected, setSelected) = UseState(Items[0]);
        var (status, setStatus) = UseState("No action triggered.");

        void TriggerAction(string value) =>
            setStatus($"Action triggered for {value}.");

        Element[] masterButtons = Items
            .Select<Element>(item =>
                Button(item, () => setSelected(item))
                    .AutomationName($"Select {item}")
                    .WithKey(item))
            .ToArray();

        return Grid(
            columns: [GridSize.Px(240), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            children:
            [
                Heading("Master Detail")
                    .Grid(row: 0, column: 0, columnSpan: 2),

                Border(
                    VStack(8,
                    [
                        SubHeading("Master"),
                        ..masterButtons
                    ])
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1, column: 0),

                Border(
                    VStack(12,
                    [
                        SubHeading("Detail"),
                        TextBlock($"Selected: {selected}")
                            .Foreground(Theme.PrimaryText),
                        Caption(status)
                            .Foreground(Theme.SecondaryText),
                        Button("Trigger action", () => TriggerAction(selected))
                            .AutomationName($"Trigger action for {selected}")
                            .Background(Theme.Accent)
                    ])
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1, column: 1),
            ]
        ).Padding(24);
    }
}

