using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog Flow", width: 560, height: 360);

class App : Component
{
    public override Element Render()
    {
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (actionMessage, setActionMessage) = UseState("No action has run yet.");

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Star(), GridSize.Auto()],
            Border(
                VStack(16,
                    Heading("Dialog flow"),
                    TextBlock("Use the button to open the dialog and trigger the string action."),
                    Button("Open dialog", () => setDialogOpen(true)),
                    TextBlock(actionMessage).Foreground(Theme.SecondaryText)
                )
                .Padding(24)
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(12)
            .Padding(24)
            .Margin(24)
            .Grid(row: 0, column: 0),

            ContentDialog(
                "Run action",
                TextBlock("Select Run to trigger the action string."),
                primaryButtonText: "Run") with
            {
                IsOpen = isDialogOpen,
                SecondaryButtonText = "Cancel",
                OnClosed = result =>
                {
                    if (result.ToString() == "Primary")
                    {
                        setActionMessage("Action string triggered.");
                    }

                    setDialogOpen(false);
                },
            }
        )
        .Background(Theme.SolidBackground);
    }
}

