using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<DialogFlowApp>("Dialog Flow", width: 520, height: 360);

class DialogFlowApp : Component
{
    public override Element Render()
    {
        var (isChecked, setIsChecked) = UseState(false);
        var (isDialogOpen, setIsDialogOpen) = UseState(false);
        var (actionText, setActionText) = UseState("Waiting for the CheckBox action.");

        void TriggerAction(bool value)
        {
            setIsChecked(value);

            if (value)
            {
                setActionText("CheckBox action triggered a string.");
                setIsDialogOpen(true);
            }
        }

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Auto],
            Heading("Dialog flow")
                .Grid(row: 0, column: 0),
            CheckBox(isChecked, TriggerAction, label: "Trigger string action")
                .Grid(row: 1, column: 0),
            TextBlock(actionText)
                .Foreground(Theme.SecondaryText)
                .Grid(row: 2, column: 0),
            ContentDialog(
                "Action triggered",
                TextBlock(actionText),
                primaryButtonText: "OK") with
            {
                IsOpen = isDialogOpen,
                OnClosed = _ =>
                {
                    setIsDialogOpen(false);
                    setIsChecked(false);
                },
            }
        ) with
        {
            RowSpacing = 12,
        }
        .Padding(24)
        .Background(Theme.DefaultBackground);
    }
}

