using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog Combo Grid", width: 640, height: 420);

class App : Component
{
    private static readonly string[] Actions =
    [
        "Archive selected item",
        "Send notification",
        "Create follow-up task"
    ];

    public override Element Render()
    {
        var (selectedIndex, setSelectedIndex) = UseState(-1);
        var (pendingAction, setPendingAction) = UseState<string?>(null);
        var (lastResult, setLastResult) = UseState("Choose an action to start the dialog flow.");

        void SelectAction(int index)
        {
            setSelectedIndex(index);

            if (index >= 0 && index < Actions.Length)
            {
                setPendingAction(Actions[index]);
            }
        }

        return Grid(
            columns: ["*", "2*"],
            rows: ["Auto", "Auto", "*"],
            [
                Heading("Dialog action flow")
                    .Grid(row: 0, column: 0, columnSpan: 2),

                TextBlock("Action")
                    .Foreground(Theme.SecondaryText)
                    .Grid(row: 1, column: 0)
                    .Margin(top: 18, right: 16),

                ComboBox(Actions, selectedIndex, SelectAction)
                    .Placeholder("Select an action")
                    .Grid(row: 1, column: 1)
                    .Margin(top: 12),

                Border(
                    VStack(8,
                        TextBlock("Status").SemiBold(),
                        TextBlock(lastResult).Foreground(Theme.SecondaryText)
                    )
                )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(16)
                    .Grid(row: 2, column: 0, columnSpan: 2)
                    .Margin(top: 24),

                ContentDialog(
                    "Confirm action",
                    TextBlock(pendingAction is null
                        ? "No action selected."
                        : $"Run \"{pendingAction}\"?"),
                    primaryButtonText: "Run") with
                {
                    IsOpen = pendingAction is not null,
                    SecondaryButtonText = "Cancel",
                    OnClosed = result =>
                    {
                        if (pendingAction is not null && result == ContentDialogResult.Primary)
                        {
                            setLastResult($"Ran: {pendingAction}");
                        }
                        else
                        {
                            setLastResult("Action cancelled.");
                        }

                        setPendingAction(null);
                    }
                }
            ])
            .Padding(24)
            .Background(Theme.ApplicationPageBackground);
    }
}

