using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Tabbed DataGrid Actions", width: 900, height: 560);

sealed record ActionRow(string Id, string Name, string ActionText);

class App : Component
{
    private static readonly List<ActionRow> Rows =
    [
        new("alpha", "Alpha", "Archive Alpha"),
        new("beta", "Beta", "Promote Beta"),
        new("gamma", "Gamma", "Review Gamma")
    ];

    private static readonly IDataSource<ActionRow> Source =
        new ListDataSource<ActionRow>(Rows, row => new RowKey(row.Id), false);

    public override Element Render()
    {
        var (lastAction, setLastAction) = UseState("No action triggered");
        Action<string> triggerAction = actionText => setLastAction(actionText);

        IReadOnlyList<FieldDescriptor> columns =
        [
            Column<ActionRow>("Name", row => row.Name, displayName: "Item", width: 220),
            Column<ActionRow>("ActionText", row => row.ActionText, displayName: "Action", width: 240),
            Column<ActionRow>("Trigger", row => row.ActionText, displayName: "Trigger", width: 160)
                .CellRenderer(value => Button("Trigger", () => triggerAction(value?.ToString() ?? string.Empty)))
        ];

        return Grid(
            columns: [GridSize.Star(1)],
            rows: [GridSize.Auto, GridSize.Star(1)],
            VStack(4,
                Heading("DataGrid actions"),
                Caption(lastAction).Foreground(Theme.SecondaryText)
            ).Grid(row: 0, column: 0),
            TabView(
            [
                Tab("Actions",
                    DataGrid<ActionRow>(
                        Source,
                        columns,
                        selectionMode: SelectionMode.None,
                        rowHeight: 44,
                        editable: false
                    ).Margin(0, 12, 0, 0)
                )
            ]).ShowAddButton(false).Grid(row: 1, column: 0)
        ).Padding(24);
    }
}

