using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail DataGrid", width: 960, height: 560);

record Customer(int Id, string Name, string Plan, string Contact);

class App : Component
{
    static readonly Customer[] Customers =
    [
        new(1, "Avery Stone", "Enterprise", "avery@example.com"),
        new(2, "Blake Rivera", "Business", "blake@example.com"),
        new(3, "Casey Morgan", "Starter", "casey@example.com"),
        new(4, "Drew Patel", "Business", "drew@example.com"),
    ];

    static readonly FieldDescriptor[] Columns =
    [
        Column<Customer>("Id", customer => customer.Id, width: 64),
        Column<Customer>("Name", customer => customer.Name, width: 180),
        Column<Customer>("Plan", customer => customer.Plan, width: 140),
        Column<Customer>("Contact", customer => customer.Contact, width: 220),
    ];

    public override Element Render()
    {
        var source = UseMemo(() => new ListDataSource<Customer>(Customers, customer => (RowKey)customer.Id));
        var (selectedId, setSelectedId) = UseState<int?>(Customers[0].Id);
        var (actionText, setActionText) = UseState($"Action: selected {Customers[0].Name}");

        var selected = Customers.First(customer => customer.Id == selectedId);

        return Grid(
            columns: ["2*", "*"],
            rows: ["Auto", "*"],
            (TitleBar("Master Detail DataGrid") with
            {
                Subtitle = "Select a row to trigger a string action",
            }).Grid(row: 0, columnSpan: 2),

            Border(
                DataGrid(
                    source: source,
                    columns: Columns,
                    selectionMode: SelectionMode.Single,
                    onSelectionChanged: keys =>
                    {
                        if (keys.Count == 0)
                        {
                            return;
                        }

                        var id = Convert.ToInt32(keys.First().Value);
                        var customer = Customers.First(customer => customer.Id == id);
                        setSelectedId(id);
                        setActionText($"Action: selected {customer.Name}");
                    },
                    rowHeight: 40
                ).Flex(grow: 1, basis: 0)
            )
            .Background(CardBackground)
            .WithBorder(CardStroke, 1)
            .CornerRadius(8)
            .Padding(12)
            .Margin(24, 24, 12, 24)
            .Grid(row: 1, column: 0),

            Border(
                VStack(12,
                    SubHeading("Detail"),
                    TextBlock(selected.Name).SemiBold().Foreground(PrimaryText),
                    TextBlock($"Plan: {selected.Plan}").Foreground(SecondaryText),
                    TextBlock($"Contact: {selected.Contact}").Foreground(SecondaryText),
                    Border(TextBlock(actionText).Foreground(PrimaryText))
                        .Background(SubtleFill)
                        .CornerRadius(6)
                        .Padding(12)
                )
            )
            .Background(CardBackground)
            .WithBorder(CardStroke, 1)
            .CornerRadius(8)
            .Padding(16)
            .Margin(12, 24, 24, 24)
            .Grid(row: 1, column: 1)
        ).Background(AppBackground);
    }
}

