{
    public override Element Render()
    {
        var (text, setText) = UseState("");
        var (lastAction, setLastAction) = UseState("Type in the TextBox to trigger an action.");

        void TriggerAction(string value)
        {
            setText(value);
            setLastAction(string.IsNullOrWhiteSpace(value)
                ? "Action triggered with an empty string."
                : $"Action triggered with: {value}");
        }

        return Grid(
            columns: [GridSize.Star],
            rows: [GridSize.Star],
            [
                TabView([
                    Tab("Action",
                        Grid(
                            columns: [GridSize.Star],
                            rows: [GridSize.Auto, GridSize.Auto],
                            [
                                TextField(text, TriggerAction, placeholder: "Enter a string", header: "TextBox")
                                    .Grid(row: 0, column: 0),
                                TextBlock(lastAction)
                                    .Foreground(Theme.SecondaryText)
                                    .Margin(0, 12, 0, 0)
                                    .Grid(row: 1, column: 0),
                            ])
                            .Padding(24)),
                    Tab("Result",
                        Grid(
                            columns: [GridSize.Star],
                            rows: [GridSize.Auto, GridSize.Auto],
                            [
                                TextBlock("Last action").SemiBold()
