using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master detail", width: 900, height: 560);

sealed record DetailItem(string Id, string Name, string Description);

class App : Component
{
    static readonly IReadOnlyList<DetailItem> Items =
    [
        new("dashboard", "Dashboard", "A summary view for daily status and key activity."),
        new("reports", "Reports", "Generate and review structured reports."),
        new("settings", "Settings", "Configure default behavior for the app.")
    ];

    public override Element Render()
    {
        var (selectedId, setSelectedId) = UseState(Items[0].Id);
        var (actionText, setActionText) = UseState("");
        var (lastAction, setLastAction) = UseState("No action triggered yet.");

        void TriggerAction(string value)
        {
            setActionText(value);
            setLastAction(string.IsNullOrWhiteSpace(value)
                ? "No action triggered yet."
                : $"Action triggered with: {value}");
        }

        var selected = Items.First(item => item.Id == selectedId);

        return Grid(
            columns: ["280", "*"],
            rows: ["*"],
            RenderMaster(selectedId, setSelectedId, actionText, TriggerAction).Grid(column: 0),
            RenderDetail(selected, lastAction).Grid(column: 1)
        ).Padding(24);
    }

    static Element RenderMaster(
        string selectedId,
        Action<string> selectItem,
        string actionText,
        Action<string> triggerAction)
    {
        return Border(
            VStack(12,
                Heading("Master"),
                Caption("Choose an item"),
                VStack(8, Items.Select(item =>
                    Button(item.Name, () => selectItem(item.Id))
                        .Background(item.Id == selectedId ? Theme.SubtleFill : Theme.CardBackground)
                        .WithKey(item.Id)
                ).ToArray()),
                TextField(actionText, triggerAction, placeholder: "Type to trigger action", header: "Action text")
            )
        )
        .Background(Theme.CardBackground)
        .WithBorder(Theme.CardStroke, 1)
        .CornerRadius(8)
        .Padding(16);
    }

    static Element RenderDetail(DetailItem item, string lastAction)
    {
        return Border(
            VStack(12,
                Heading(item.Name),
                TextBlock(item.Description).Foreground(Theme.PrimaryText),
                Caption(lastAction).Foreground(Theme.SecondaryText)
            )
        )
        .Background(Theme.CardBackground)
        .WithBorder(Theme.CardStroke, 1)
        .CornerRadius(8)
        .Padding(16)
        .Margin(left: 16);
    }
}

