using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog Flow", width: 520, height: 360);

class App : Component
{
    public override Element Render()
    {
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (dialogText, setDialogText) = UseState("");
        var (submittedText, setSubmittedText) = UseState("No action submitted yet.");

        return Grid(
            columns: [GridSize.Star],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Star],
            Heading("Dialog flow")
                .Grid(row: 0),
            Button("Open dialog", () => setDialogOpen(true))
                .Grid(row: 1),
            Border(
                VStack(8,
                    Caption("Action result"),
                    TextBlock(submittedText).Foreground(Theme.PrimaryText)
                )
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 2),
            ContentDialog(
                "Run string action",
                Grid(
                    columns: [GridSize.Star],
                    rows: [GridSize.Auto],
                    TextField(dialogText, setDialogText, placeholder: "Enter a string", header: "String value")
                        .Grid(row: 0)
                ),
                primaryButtonText: "Run") with
            {
                IsOpen = isDialogOpen,
                SecondaryButtonText = "Cancel",
                OnClosed = result =>
                {
                    if (result == ContentDialogResult.Primary)
                    {
                        setSubmittedText($"Action triggered with: {dialogText}");
                    }

                    setDialogOpen(false);
                    setDialogText("");
                },
            }
        )
            .Background(Theme.SolidBackground)
            .Padding(24);
    }
}

