ReactorApp.Run<App>("Master detail", width: 860, height: 520);

sealed record DetailItem(string Id, string Title, string Summary, string Status);

class App : Component
{
    static readonly DetailItem[] Items =
    [
        new("alpha", "Alpha", "Primary record for reviewing incoming work.", "Ready"),
        new("bravo", "Bravo", "Secondary record with active follow-up details.", "In progress"),
        new("charlie", "Charlie", "Archived record kept for reference.", "Complete"),
    ];

    public override Element Render()
    {
        var (selectedId, setSelectedId) = UseState(Items[0].Id);
        var (lastAction, setLastAction) = UseState($"Selected {Items[0].Title}");
        var selected = Items.First(item => item.Id == selectedId);

        void SelectItem(string id)
        {
            var item = Items.First(candidate => candidate.Id == id);
            setSelectedId(item.Id);
            setLastAction($"Selected {item.Title}");
        }

        return Grid(
            columns: [GridSize.Px(280), GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Star()],
            children:
            [
                Heading("Records")
                    .Margin(left: 24, top: 24, right: 12, bottom: 12)
                    .Grid(row: 0, column: 0),

                Heading("Details")
                    .Margin(left: 12, top: 24, right: 24, bottom: 12)
                    .Grid(row: 0, column: 1),

                Border(
                    VStack(8, Items.Select(item =>
                        RadioButton(
                            item.Title,
                            isChecked: item.Id == selectedId,
                            onChecked: isChecked =>
                            {
                                if (isChecked)
                                {
                                    SelectItem(item.Id);
                                }
                            },
                            groupName: "records"
                        ).WithKey(item.Id)
                    ).ToArray())
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Margin(left: 24, top: 0, right: 12, bottom: 24)
                .Grid(row: 1, column: 0),

                Border(
                    VStack(12,
                        SubHeading(selected.Title),
                        TextBlock(selected.Summary).Foreground(Theme.PrimaryText),
                        Caption($"Status: {selected.Status}").Foreground(Theme.SecondaryText),
                        Caption(lastAction).Foreground(Theme.SecondaryText)
                    )
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(20)
                .Margin(left: 12, top: 0, right: 24, bottom: 24)
                .Grid(row: 1, column: 1),
            ]);
    }
}

