using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog Radio Flow", width: 560, height: 420);

class App : Component
{
    public override Element Render()
    {
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (selectedAction, setSelectedAction) = UseState("Archive");
        var (lastAction, setLastAction) = UseState("No action selected yet.");

        void ChooseAction(string action)
        {
            setSelectedAction(action);
            setLastAction($"Selected action: {action}");
        }

        return Border(
            Grid(
                columns: [GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto, GridSize.Star()],
                Heading("Dialog action flow")
                    .Foreground(Theme.PrimaryText)
                    .Grid(row: 0, column: 0),
                TextBlock(lastAction)
                    .Foreground(Theme.SecondaryText)
                    .Margin(0, 12, 0, 20)
                    .Grid(row: 1, column: 0),
                Button("Choose action", () => setDialogOpen(true))
                    .Grid(row: 2, column: 0),
                ContentDialog(
                    "Choose an action",
                    Grid(
                        columns: [GridSize.Star(), GridSize.Star()],
                        rows: [GridSize.Auto, GridSize.Auto],
                        RadioButton("Archive", selectedAction == "Archive", isChecked =>
                            {
                                if (isChecked)
                                    ChooseAction("Archive");
                            },
                            groupName: "actions")
                            .Grid(row: 0, column: 0),
                        RadioButton("Notify", selectedAction == "Notify", isChecked =>
                            {
                                if (isChecked)
                                    ChooseAction("Notify");
                            },
                            groupName: "actions")
                            .Grid(row: 0, column: 1),
                        RadioButton("Escalate", selectedAction == "Escalate", isChecked =>
                            {
                                if (isChecked)
                                    ChooseAction("Escalate");
                            },
                            groupName: "actions")
                            .Grid(row: 1, column: 0),
                        TextBlock($"Action string: {selectedAction}")
                            .Foreground(Theme.AccentText)
                            .Margin(0, 16, 0, 0)
                            .Grid(row: 1, column: 1)
                    ).Padding(4),
                    primaryButtonText: "Done") with
                {
                    IsOpen = isDialogOpen,
                    OnClosed = _ => setDialogOpen(false),
                }
            )
        )
        .Background(Theme.CardBackground)
        .WithBorder(Theme.CardStroke)
        .CornerRadius(8)
        .Padding(24)
        .Margin(24);
    }
}

