using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Tabbed Toggle", width: 720, height: 420);

class App : Component
{
    public override Element Render()
    {
        var (isEnabled, setIsEnabled) = UseState(false);
        var (actionText, setActionText) = UseState("No action has run yet.");

        void ToggleAction(bool value)
        {
            setIsEnabled(value);
            setActionText(value ? "Toggle action: enabled" : "Toggle action: disabled");
        }

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star],
            Heading("Tabbed Toggle")
                .Margin(0, 0, 0, 16)
                .Grid(row: 0, column: 0),
            TabView(
                Tab("Toggle",
                    Border(
                        Grid(
                            columns: [GridSize.Auto, GridSize.Star()],
                            rows: [GridSize.Auto, GridSize.Auto],
                            ToggleSwitch(isEnabled, ToggleAction, onContent: "On", offContent: "Off", header: "Run action")
                                .Grid(row: 0, column: 0),
                            TextBlock(actionText)
                                .Foreground(Theme.SecondaryText)
                                .Margin(24, 0, 0, 0)
                                .VAlign(VerticalAlignment.Center)
                                .Grid(row: 0, column: 1),
                            TextBlock("Switching the toggle updates the action string.")
                                .Foreground(Theme.SecondaryText)
                                .Margin(0, 16, 0, 0)
                                .Grid(row: 1, column: 0, columnSpan: 2)
                        )
                    )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(20)),
                Tab("Status",
                    Border(
                        VStack(8,
                            SubHeading("Current state"),
                            TextBlock(isEnabled ? "The toggle is on." : "The toggle is off."),
                            TextBlock(actionText).Foreground(Theme.SecondaryText)
                        )
                    )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(20))
            )
            .ShowAddButton(false)
            .Grid(row: 1, column: 0)
        ).Padding(24);
    }
}

