        new("alpha", "Alpha", "Primary workspace details."),
        new("beta", "Beta", "Secondary workspace details."),
        new("gamma", "Gamma", "Tertiary workspace details.")
    ];

    public override Element Render()
    {
        var (selectedIndex, setSelectedIndex) = UseState(0);
        var (isActionEnabled, setIsActionEnabled) = UseState(false);
        var (actionStatus, setActionStatus) = UseState("No action triggered.");

        var selected = Items[selectedIndex];

        return Grid(
            columns: [GridSize.Px(220), GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            Heading("Master Detail").Margin(24, 20, 24, 12).Grid(columnSpan: 2),
            Border(
                VStack(12,
                    SubHeading("Master"),
                    ListBox(Items.Select(item => item.Title).ToArray(), selectedIndex, index =>
                    {
                        setSelectedIndex(index);
                        setIsActionEnabled(false);
                        setActionStatus($"Selected {Items[index].Title}.");
                    })
                )
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(8)
            .Padding(16)
            .Margin(left: 24, top: 0, right: 8, bottom: 24)
            .Grid(row: 1, column: 0),
            Border(
                VStack(16,
                    SubHeading(selected.Title),
                    TextBlock(selected.Description).Foreground(Theme.SecondaryText),
                    ToggleSwitch(
                        isActionEnabled,
                        isOn =>
                        {
                            setIsActionEnabled(isOn);
                            setActionStatus($"{selected.Title} action {(isOn ? "enabled" : "disabled")}.");
                        },
                        onContent: "Action enabled",
                        offContent: "Action disabled",
                        header: "Action"),
                    TextBlock(actionStatus).Foreground(Theme.PrimaryText)
                )
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(8)
            .Padding(20)
            .Margin(left: 8, top: 0, right: 24, bottom: 24)
            .Grid(row: 1, column: 1)
        ).Background(Theme.SolidBackground);
    }
}

