using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Tabbed Combo", width: 720, height: 480);

class App : Component
{
    private static readonly string[] Choices = ["Default", "Comfortable", "Compact"];

    public override Element Render()
    {
        var (selectedChoice, setSelectedChoice) = UseState(Choices[0]);
        var selectedIndex = Array.IndexOf(Choices, selectedChoice);

        return (Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Star()],
            Heading("Tabbed Combo")
                .Grid(row: 0, column: 0),
            TabView(
                Tab("Picker",
                    (Grid(
                        columns: [GridSize.Auto(), GridSize.Star()],
                        rows: [GridSize.Auto(), GridSize.Auto()],
                        TextBlock("Choice")
                            .Grid(row: 0, column: 0),
                        ComboBox(Choices, selectedIndex, index => setSelectedChoice(Choices[index]))
                            .Grid(row: 0, column: 1),
                        TextBlock($"Selected: {selectedChoice}")
                            .Foreground(Theme.SecondaryText)
                            .Grid(row: 1, column: 1)
                    )
                    with
                    {
                        ColumnSpacing = 12,
                        RowSpacing = 12
                    })
                    .Padding(24)
                ),
                Tab("Summary",
                    Border(
                        VStack(8,
                            SubHeading("Current selection"),
                            TextBlock(selectedChoice)
                        )
                    )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(16)
                )
            )
            .ShowAddButton(false)
            .Grid(row: 1, column: 0)
        )
        with
        {
            RowSpacing = 16
        })
        .Padding(24)
        .Background(Theme.SolidBackground);
    }
}

