using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail", width: 760, height: 460);

sealed record DetailItem(string Name, string Description, string Notes);

class App : Component
{
    private static readonly DetailItem[] Items =
    [
        new("Overview", "A concise summary of the selected record.", "Use the master ComboBox to choose the detail content."),
        new("Planning", "The planning record focuses on milestones and next steps.", "The selected name is stored as component state."),
        new("Delivery", "The delivery record shows the final handoff details.", "The detail pane updates when the string state changes.")
    ];

    public override Element Render()
    {
        var (selectedName, setSelectedName) = UseState(Items[0].Name);
        var selectedIndex = Math.Max(0, Array.FindIndex(Items, item => item.Name == selectedName));
        var selectedItem = Items[selectedIndex];

        return Grid(
            columns: [GridSize.Px(260), GridSize.Star],
            rows: [GridSize.Auto, GridSize.Star],
            children:
            [
                Heading("Master Detail")
                    .Grid(row: 0, column: 0, columnSpan: 2)
                    .Margin(0, 0, 0, 20),

                Border(
                    VStack(12,
                        TextBlock("Master").SemiBold(),
                        ComboBox(
                                Items.Select(item => item.Name).ToArray(),
                                selectedIndex,
                                index => setSelectedName(Items[index].Name))
                            .Header("Selected item")
                            .MinWidth(200),
                        Caption($"Current state: {selectedName}")
                            .Foreground(Theme.SecondaryText)
                    )
                )
                    .Grid(row: 1, column: 0)
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke)
                    .CornerRadius(8)
                    .Padding(16)
                    .Margin(0, 0, 16, 0),

                Border(
                    VStack(12,
                        TextBlock("Detail").SemiBold(),
                        SubHeading(selectedItem.Name),
                        TextBlock(selectedItem.Description)
                            .Foreground(Theme.PrimaryText),
                        Caption(selectedItem.Notes)
                            .Foreground(Theme.SecondaryText)
                    )
                )
                    .Grid(row: 1, column: 1)
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke)
                    .CornerRadius(8)
                    .Padding(16)
            ])
            .Background(Theme.SolidBackground)
            .Padding(24);
    }
}

