ReactorApp.Run<App>("Dialog ComboBox Flow", width: 520, height: 360);

class App : Component
{
    private static readonly string[] Choices = ["Alpha", "Beta", "Gamma"];

    public override Element Render()
    {
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (selectedChoice, setSelectedChoice) = UseState(Choices[0]);

        var selectedIndex = Array.IndexOf(Choices, selectedChoice);

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Auto, GridSize.Star()],
            [
                Heading("Dialog flow")
                    .Grid(0, 0),

                TextBlock($"Selected: {selectedChoice}")
                    .Foreground(Theme.SecondaryText)
                    .Grid(1, 0),

                Button("Open dialog", () => setDialogOpen(true))
                    .HAlign(HorizontalAlignment.Left)
                    .Grid(2, 0),

                ContentDialog(
                    "Choose an option",
                    Grid(
                        columns: [GridSize.Star()],
                        rows: [GridSize.Auto, GridSize.Auto],
                        [
                            ComboBox(Choices, selectedIndex, index =>
                                {
                                    if (index >= 0 && index < Choices.Length)
                                    {
                                        setSelectedChoice(Choices[index]);
                                    }
                                })
                                .Header("Option")
                                .Placeholder("Select an option")
                                .Grid(0, 0),

                            TextBlock($"Current value: {selectedChoice}")
                                .Foreground(Theme.SecondaryText)
                                .Margin(0, 12, 0, 0)
                                .Grid(1, 0),
                        ]),
                    primaryButtonText: "Done") with
                {
                    IsOpen = isDialogOpen,
                    OnClosed = _ => setDialogOpen(false),
                }
            ])
            .Padding(24)
            .Background(Theme.SolidBackground);
    }
}

