using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("DataGrid State Binding", width: 720, height: 420);

class App : Component
{
    public override Element Render()
    {
        var (value, setValue) = UseState("Bound from Reactor state");
        var registry = UseMemo(() => new TypeRegistry(), Array.Empty<object>());
        var row = new BoundValueRow { Value = value };
        var source = new ListDataSource<BoundValueRow>(
            new List<BoundValueRow> { row },
            _ => new RowKey("state-value"),
            true);

        return Grid(
            columns: ["*"],
            rows: ["Auto", "*"],
            children:
            [
                VStack(4,
                    Heading("State-bound DataGrid"),
                    Caption($"Current value: {value}").Foreground(Theme.SecondaryText)
                ).Grid(row: 0),

                Border(
                    DataGrid(
                        source,
                        registry,
                        onRowChanged: (_, updatedRow) =>
                        {
                            setValue(updatedRow.Value);
                            return Task.CompletedTask;
                        },
                        editable: true,
                        emptyTemplate: TextBlock("No value"))
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(12)
                .Grid(row: 1)
            ])
            .Background(Theme.AppBackground)
            .Padding(24);
    }
}

sealed class BoundValueRow
{
    public string Value { get; set; } = "";
}

