using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Tabbed DataGrid", width: 720, height: 480);

sealed record StateRow(int Id, string Value);

class App : Component
{
    public override Element Render()
    {
        var (value, setValue) = UseState("Bound string value");
        var source = new ListDataSource<StateRow>(
            [new StateRow(1, value)],
            row => (RowKey)row.Id);

        return TabView(
            Tab("Data", RenderDataTab(value, setValue, source)),
            Tab("Preview", RenderPreviewTab(value))
        )
        .ShowAddButton(false)
        .Background(Theme.SolidBackground)
        .Padding(16);
    }

    static Element RenderDataTab(
        string value,
        Action<string> setValue,
        ListDataSource<StateRow> source) =>
        Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto, GridSize.Star()],
            TextField(value, setValue, placeholder: "Edit the string", header: "Value")
                .Grid(row: 0, column: 0)
                .Margin(0, 0, 0, 12),
            DataGrid(
                source,
                [
                    Column<StateRow>(
                        "Value",
                        row => row.Value,
                        editable: true,
                        displayName: "Value",
                        width: 320)
                ],
                onRowChanged: (_, row) =>
                {
                    setValue(row.Value);
                    return Task.CompletedTask;
                },
                editable: true)
                .Grid(row: 1, column: 0)
        )
        .Padding(16);

    static Element RenderPreviewTab(string value) =>
        Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Star()],
            Border(TextBlock(value).Foreground(Theme.PrimaryText))
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 0, column: 0)
        )
        .Padding(16);
}

