using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Reactor.Layout;
using static Microsoft.UI.Reactor.Factories;
using static Microsoft.UI.Reactor.Core.Theme;

ReactorApp.Run<App>("Master-detail DataGrid", width: 900, height: 560);

record Customer(int Id, string Name, string Status, string Detail);

class App : Component
{
    static readonly Customer[] Customers =
    [
        new(1, "Ada Lovelace", "Active", "First programmer and analytical engine collaborator."),
        new(2, "Grace Hopper", "Active", "Compiler pioneer and naval computer scientist."),
        new(3, "Katherine Johnson", "Review", "Orbital mechanics expert for early crewed spaceflight."),
        new(4, "Margaret Hamilton", "Active", "Led Apollo flight software development."),
    ];

    public override Element Render()
    {
        var (selectedDetail, setSelectedDetail) = UseState(Customers[0].Detail);

        var source = UseMemo(() =>
            new ListDataSource<Customer>(Customers, customer => (RowKey)customer.Id));

        var columns = UseMemo(() => new FieldDescriptor[]
        {
            Column<Customer>("Id", customer => customer.Id, width: 64),
            Column<Customer>("Name", customer => customer.Name, width: 220),
            Column<Customer>("Status", customer => customer.Status, width: 120),
        });

        return Grid(
            columns: ["2*", "3*"],
            rows: ["Auto", "*"],
            [
                Heading("Customers")
                    .Grid(row: 0, column: 0),

                Heading("Detail")
                    .Grid(row: 0, column: 1),

                Border(
                    DataGrid(
                        source: source,
                        columns: columns,
                        selectionMode: SelectionMode.Single,
                        onSelectionChanged: keys =>
                        {
                            var selectedKey = keys.FirstOrDefault();
                            var selectedCustomer = Customers.FirstOrDefault(customer => (RowKey)customer.Id == selectedKey);

                            if (selectedCustomer is not null)
                            {
                                setSelectedDetail(selectedCustomer.Detail);
                            }
                        },
                        rowHeight: 40)
                    .Flex(grow: 1, basis: 0))
                .Background(CardBackground)
                .WithBorder(CardStroke, 1)
                .CornerRadius(8)
                .Padding(12)
                .Grid(row: 1, column: 0),

                Border(
                    VStack(12,
                        TextBlock("Selected detail").SemiBold(),
                        TextField(selectedDetail, setSelectedDetail, placeholder: "Select a customer"))
                )
                .Background(CardBackground)
                .WithBorder(CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1, column: 1),
            ])
        .Padding(24)
        .ColumnSpacing(16)
        .RowSpacing(12);
    }
}

