using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog DataGrid Flow", width: 760, height: 520);

record DialogRow(int Id, string Value);

class App : Component
{
    public override Element Render()
    {
        var (dialogText, setDialogText) = UseState("Default value");
        var (isDialogOpen, setDialogOpen) = UseState(false);

        var rows = UseMemo(
            () => new[] { new DialogRow(1, dialogText) },
            dialogText);

        var source = UseMemo(
            () => new ListDataSource<DialogRow>(rows, row => (RowKey)row.Id),
            rows);

        var columns = UseMemo<IReadOnlyList<FieldDescriptor>>(
            () =>
            [
                Column<DialogRow>("Value", row => row.Value, displayName: "Bound string", width: 360),
            ]);

        return Grid(
            [GridSize.Star()],
            [GridSize.Auto, GridSize.Star()],
            Border(
                VStack(8,
                    Heading("Dialog DataGrid Flow"),
                    TextBlock("Open the dialog to edit a string and see the DataGrid reflect the same state.")
                        .Foreground(Theme.SecondaryText)
                )
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(8)
            .Padding(16)
            .Grid(row: 0, column: 0),

            Border(
                VStack(12,
                    TextBlock($"Current string: {dialogText}").Foreground(Theme.PrimaryText),
                    Button("Open dialog", () => setDialogOpen(true)),
                    ContentDialog(
                        "Edit bound string",
                        Grid(
                            [GridSize.Star()],
                            [GridSize.Auto, GridSize.Auto, GridSize.Star()],
                            TextField(dialogText, setDialogText, placeholder: "Enter a value", header: "String state")
                                .Grid(row: 0, column: 0),
                            Caption("The DataGrid below is built from the same string state.")
                                .Foreground(Theme.SecondaryText)
                                .Margin(0, 12, 0, 6)
                                .Grid(row: 1, column: 0),
                            DataGrid<DialogRow>(source, columns, emptyTemplate: TextBlock("No value"))
                                .Height(180)
                                .Grid(row: 2, column: 0)
                        ),
                        primaryButtonText: "Done") with
                    {
                        IsOpen = isDialogOpen,
                        DefaultButton = ContentDialogButton.Primary,
                        OnClosed = _ => setDialogOpen(false),
                    }
                )
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(8)
            .Padding(16)
            .Margin(0, 16, 0, 0)
            .Grid(row: 1, column: 0)
        )
        .Padding(24)
        .Background(Theme.SolidBackground);
    }
}

