using System.Globalization;
using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Slider Grid", width: 520, height: 320);

class App : Component
{
    public override Element Render()
    {
        var (valueText, setValueText) = UseState("50");
        var value = double.Parse(valueText, CultureInfo.InvariantCulture);

        return Border(
            Border(
                Grid(
                    columns: [GridSize.Star()],
                    rows: [GridSize.Auto(), GridSize.Auto(), GridSize.Auto()],
                    children:
                    [
                        Heading("Slider value")
                            .Grid(row: 0),

                        Slider(value, min: 0, max: 100, onChanged: next =>
                                setValueText(next.ToString("0", CultureInfo.InvariantCulture)))
                            .MinWidth(320)
                            .Margin(0, 16, 0, 12)
                            .Grid(row: 1),

                        TextBlock(valueText)
                            .Foreground(Theme.SecondaryText)
                            .Grid(row: 2)
                    ]))
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(12)
                .Padding(24))
            .Background(Theme.SolidBackground)
            .Padding(24);
    }
}

