using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("RadioButton Grid", width: 520, height: 360);

class App : Component
{
    private const string OptionOne = "Default";
    private const string OptionTwo = "Compact";
    private const string OptionThree = "Comfortable";
    private const string RadioGroupName = "display-density";

    public override Element Render()
    {
        var (selectedOption, setSelectedOption) = UseState(OptionOne);

        return Grid(
            columns: ["*"],
            rows: ["Auto", "Auto", "Auto"],
            children:
            [
                Heading("Choose a display density")
                    .Foreground(Theme.PrimaryText)
                    .Grid(row: 0, column: 0),

                VStack(8,
                    RadioOption(OptionOne, selectedOption, setSelectedOption),
                    RadioOption(OptionTwo, selectedOption, setSelectedOption),
                    RadioOption(OptionThree, selectedOption, setSelectedOption))
                    .Margin(top: 16)
                    .Grid(row: 1, column: 0),

                Border(
                    TextBlock($"Selected: {selectedOption}")
                        .Foreground(Theme.PrimaryText))
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(12)
                    .Margin(top: 20)
                    .Grid(row: 2, column: 0),
            ])
            .Background(Theme.DefaultBackground)
            .Padding(24);
    }

    private static Element RadioOption(string option, string selectedOption, Action<string> setSelectedOption) =>
        RadioButton(
            option,
            isChecked: selectedOption == option,
            onChecked: isChecked =>
            {
                if (isChecked)
                {
                    setSelectedOption(option);
                }
            },
            groupName: RadioGroupName);
}

