using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail", width: 900, height: 560);

sealed record DetailItem(string Id, string Title, string Description);

class App : Component
{
    static readonly DetailItem[] Items =
    [
        new("dashboard", "Dashboard", "Summary details for the dashboard item."),
        new("profile", "Profile", "Profile details for the selected item."),
        new("settings", "Settings", "Settings details for the selected item.")
    ];

    public override Element Render()
    {
        var (selectedId, setSelectedId) = UseState(Items[0].Id);
        var (toggleValue, setToggleValue) = UseState("Off");
        var selected = Items.First(item => item.Id == selectedId);

        return Grid([GridSize.Px(260), GridSize.Star()], [GridSize.Auto, GridSize.Star()],
            Heading("Master Detail").Margin(0, 0, 0, 16).Grid(row: 0, column: 0, columnSpan: 2),
            Border(
                VStack(8,
                    [
                        SubHeading("Master"),
                        ..Items.Select(item => (Element)
                        Button(item.Title, () => setSelectedId(item.Id))
                            .Background(item.Id == selectedId ? Theme.ControlFillSecondary : Theme.ControlFill)
                            .AutomationName(item.Title)
                            .WithKey(item.Id)
                    ]
                )
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .CornerRadius(8)
            .Padding(16)
            .Grid(row: 1, column: 0),
            Border(
                VStack(12,
                [
                    SubHeading(selected.Title),
                    TextBlock(selected.Description).Foreground(Theme.SecondaryText),
                    ToggleSwitch(
                        toggleValue == "On",
                        isOn => setToggleValue(isOn ? "On" : "Off"),
                        onContent: "On",
                        offContent: "Off",
                        header: "Toggle string state"),
                    TextBlock($"Current string value: {toggleValue}")
                ])
            )
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke)
            .CornerRadius(8)
            .Padding(20)
            .Margin(16, 0, 0, 0)
            .Grid(row: 1, column: 1)
        )
        .Background(Theme.SolidBackground)
        .Padding(24);
