using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog Flow", width: 560, height: 360);

class App : Component
{
    public override Element Render()
    {
        var (dialogOpen, setDialogOpen) = UseState(false);
        var (toggleValue, setToggleValue) = UseState("Off");

        var isOn = toggleValue == "On";

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Star(), GridSize.Auto()],
            Border(
                Grid(
                    columns: [GridSize.Star(), GridSize.Auto()],
                    rows: [GridSize.Auto(), GridSize.Auto(), GridSize.Auto()],
                    Heading("Dialog flow")
                        .Grid(row: 0, column: 0, columnSpan: 2),
                    TextBlock($"Toggle state: {toggleValue}")
                        .Foreground(Theme.SecondaryText)
                        .Grid(row: 1, column: 0, columnSpan: 2),
                    Button("Open dialog", () => setDialogOpen(true))
                        .Grid(row: 2, column: 1)
                ).Padding(20)
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
                .MaxWidth(420)
                .HAlign(HorizontalAlignment.Center)
                .VAlign(VerticalAlignment.Center)
                .Grid(row: 0, column: 0),
            ContentDialog(
                "Choose state",
                Grid(
                    columns: [GridSize.Star(), GridSize.Auto()],
                    rows: [GridSize.Auto(), GridSize.Auto()],
                    TextBlock("Dialog toggle")
                        .Foreground(Theme.PrimaryText)
                        .Grid(row: 0, column: 0),
                    ToggleSwitch(
                        isOn,
                        value => setToggleValue(value ? "On" : "Off"),
                        onContent: "On",
                        offContent: "Off")
                        .Grid(row: 0, column: 1),
                    TextBlock($"Current value: {toggleValue}")
                        .Foreground(Theme.SecondaryText)
                        .Grid(row: 1, column: 0, columnSpan: 2)
                ).Padding(4),
                primaryButtonText: "Done") with
            {
                IsOpen = dialogOpen,
                OnClosed = _ => setDialogOpen(false),
            }
        )
            .Background(Theme.SolidBackground)
            .Padding(24);
    }
}

