using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog Filter", width: 520, height: 440);

class App : Component
{
    static readonly string[] Items =
    [
        "Apple",
        "Apricot",
        "Banana",
        "Blueberry",
        "Cherry",
        "Clementine",
        "Date",
        "Dragon fruit",
    ];

    static readonly string[] Filters = ["All", "Starts with A", "Starts with B", "Starts with C"];

    public override Element Render()
    {
        var (dialogOpen, setDialogOpen) = UseState(false);
        var (activeFilter, setActiveFilter) = UseState("All");
        var (pendingFilterIndex, setPendingFilterIndex) = UseState(0);

        var visibleItems = Items
            .Where(item => activeFilter switch
            {
                "Starts with A" => item.StartsWith("A", StringComparison.OrdinalIgnoreCase),
                "Starts with B" => item.StartsWith("B", StringComparison.OrdinalIgnoreCase),
                "Starts with C" => item.StartsWith("C", StringComparison.OrdinalIgnoreCase),
                _ => true,
            })
            .ToArray();

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Auto(), GridSize.Star()],
            Heading("String filter").Grid(row: 0, column: 0),
            HStack(12,
                Button("Choose filter", () =>
                {
                    setPendingFilterIndex(Array.IndexOf(Filters, activeFilter));
                    setDialogOpen(true);
                }),
                Caption($"Current: {activeFilter}").Foreground(Theme.SecondaryText)
            ).Grid(row: 1, column: 0),
            Border(
                ScrollView(
                    VStack(8,
                        visibleItems.Select(item =>
                            Border(TextBlock(item).Foreground(Theme.PrimaryText))
                                .Background(Theme.CardBackground)
                                .WithBorder(Theme.CardStroke, 1)
                                .CornerRadius(6)
                                .Padding(10)
                                .WithKey(item)
                        ).ToArray()
                    ).Padding(12)
                )
            )
                .Background(Theme.SubtleFill)
                .CornerRadius(8)
                .Grid(row: 2, column: 0),
            ContentDialog(
                "Filter strings",
                VStack(8,
                    TextBlock("Show items matching:").Foreground(Theme.PrimaryText),
                    ComboBox(Filters, pendingFilterIndex, setPendingFilterIndex)
                ),
                primaryButtonText: "Apply") with
            {
                IsOpen = dialogOpen,
                SecondaryButtonText = "Cancel",
                OnClosed = result =>
                {
                    if (result == ContentDialogResult.Primary)
                    {
                        setActiveFilter(Filters[pendingFilterIndex]);
                    }

                    setDialogOpen(false);
                },
            }
        ).Padding(24);
    }
}

