using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail Filter", width: 760, height: 480);

class App : Component
{
    private static readonly string[] Items =
    [
        "Alpha",
        "Beta",
        "Gamma",
        "Delta",
        "Epsilon",
        "Zeta"
    ];

    public override Element Render()
    {
        var (showAOnly, setShowAOnly) = UseState(false);
        var (selectedItem, setSelectedItem) = UseState(Items[0]);

        var filteredItems = Items
            .Where(item => !showAOnly || item.Contains('a', StringComparison.OrdinalIgnoreCase))
            .ToArray();
        var effectiveSelection = filteredItems.Contains(selectedItem) ? selectedItem : filteredItems.FirstOrDefault();
        var selectedIndex = effectiveSelection is null ? -1 : Array.IndexOf(filteredItems, effectiveSelection);

        return Grid(
            columns: ["260", "*"],
            rows: ["Auto", "*"],
            children:
            [
                Header().Grid(row: 0, column: 0, columnSpan: 2),
                MasterPane(showAOnly, setShowAOnly, filteredItems, selectedIndex, setSelectedItem)
                    .Grid(row: 1, column: 0),
                DetailPane(effectiveSelection)
                    .Grid(row: 1, column: 1)
            ])
            .Background(Theme.SolidBackground)
            .Padding(24);
    }

    private static Element Header() =>
        VStack(4,
            Heading("Strings"),
            Caption("Select an item, or filter the master list with the checkbox.")
                .Foreground(Theme.SecondaryText))
        .Margin(bottom: 16);

    private static Element MasterPane(
        bool showAOnly,
        Action<bool> setShowAOnly,
        string[] filteredItems,
        int selectedIndex,
        Action<string> setSelectedItem) =>
        Border(
            VStack(12,
                SubHeading("Master"),
                CheckBox(showAOnly, setShowAOnly, "Only show strings containing \"a\""),
                ListBox(
                    filteredItems,
                    selectedIndex,
                    index =>
                    {
                        if (index >= 0 && index < filteredItems.Length)
                        {
                            setSelectedItem(filteredItems[index]);
                        }
