using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail", width: 760, height: 480);

sealed record DemoItem(string Name, string Category, string Detail);

class App : Component
{
    private static readonly string[] Categories = ["All", "Design", "Data", "Controls"];

    private static readonly DemoItem[] Items =
    [
        new("Accent colors", "Design", "Theme colors that adapt to the user's Windows accent settings."),
        new("Typography", "Design", "Headings, body text, and captions using default Reactor styling."),
        new("Customer list", "Data", "A string-based master list filtered by the selected category."),
        new("Order summary", "Data", "A compact detail view for the selected master row."),
        new("ComboBox", "Controls", "A selector used here to filter the visible strings."),
        new("ListView", "Controls", "The master area where each filtered string can be selected.")
    ];

    public override Element Render()
    {
        var (selectedCategoryIndex, setSelectedCategoryIndex) = UseState(0);
        var (selectedName, setSelectedName) = UseState(Items[0].Name);

        var selectedCategory = Categories[selectedCategoryIndex];
        var filteredItems = Items
            .Where(item => selectedCategory == "All" || item.Category == selectedCategory)
            .ToArray();
        var selectedItem = filteredItems.FirstOrDefault(item => item.Name == selectedName) ?? filteredItems.First();

        return Grid(
            [GridSize.Px(280), GridSize.Star()],
            [GridSize.Auto, GridSize.Star()],
            [
                VStack(6,
                    Caption("Filter"),
                    ComboBox(Categories, selectedCategoryIndex, index =>
                    {
                        setSelectedCategoryIndex(index);
                        var nextCategory = Categories[index];
                        var nextItem = Items.First(item => nextCategory == "All" || item.Category == nextCategory);
                        setSelectedName(nextItem.Name);
                    }).Placeholder("Choose a category")
                )
                .Grid(row: 0, column: 0, columnSpan: 2),

                Border(
                    VStack(8,
                        SubHeading("Strings"),
                        ListView<DemoItem>(
                            filteredItems,
                            item => item.Name,
                            (item, _) => Border(TextBlock(item.Name).Foreground(Theme.PrimaryText))
                                .Background(item.Name == selectedItem.Name ? Theme.SubtleFill : Theme.CardBackground)
                                .CornerRadius(6)
                                .Padding(10)
                                .OnTapped((_, _) => setSelectedName(item.Name))
                        )
                    )
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(12)
                .Grid(row: 1, column: 0),

                Border(
                    VStack(8,
                        Caption(selectedItem.Category),
                        Heading(selectedItem.Name),
                        TextBlock(selectedItem.Detail).TextWrapping(TextWrapping.Wrap).Foreground(Theme.SecondaryText)
                    )
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(18)
                .Grid(row: 1, column: 1)
            ]
        ).Padding(20).ColumnSpacing(16).RowSpacing(16);
    }
}

