                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(18)
                .Grid(row: 1, column: 1)
            ]
        ) with
        {
            ColumnSpacing = 16,
            RowSpacing = 16
        }).Padding(20);
    }
}

