        var filteredItems = UseMemo(
            () => Props.Items
                .Where(item => string.IsNullOrWhiteSpace(Props.Filter) ||
                    item.Value.Contains(Props.Filter, StringComparison.OrdinalIgnoreCase))
                .ToArray(),
