using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Core.Theme;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("String Catalog", width: 960, height: 640);

record CatalogItem(string Id, string Name, string Group, string Description);

class App : Component
{
    private static readonly CatalogItem[] Items =
    [
        new("alpha", "Alpha", "Greek", "The first letter of the Greek alphabet."),
        new("bravo", "Bravo", "Signal", "A clear acknowledgement in radio spelling."),
        new("charlie", "Charlie", "Signal", "The third word in the NATO phonetic alphabet."),
        new("delta", "Delta", "Greek", "A letter often used to mean change."),
        new("echo", "Echo", "Signal", "A reflected sound or repeated message."),
        new("foxtrot", "Foxtrot", "Dance", "A smooth ballroom dance in four-four time."),
        new("gamma", "Gamma", "Greek", "The third letter of the Greek alphabet."),
        new("hotel", "Hotel", "Signal", "A lodging word used in radio spelling."),
    ];

    private static readonly FieldDescriptor[] Columns =
    [
        Column<CatalogItem>("Name", item => item.Name, width: 180),
        Column<CatalogItem>("Group", item => item.Group, width: 120),
        Column<CatalogItem>("Description", item => item.Description, width: 360),
    ];

    public override Element Render()
    {
        var (filter, setFilter) = UseState("");
        var (selectedId, setSelectedId) = UseState<string?>(Items[0].Id);

        var filteredItems = UseMemo(
            () => FilterItems(filter),
            filter);

        var source = UseMemo(
            () => new ListDataSource<CatalogItem>(filteredItems, item => (RowKey)item.Id),
            filteredItems);

        var selected = filteredItems.FirstOrDefault(item => item.Id == selectedId)
            ?? filteredItems.FirstOrDefault();

        return Grid(
            columns: ["2*", "*"],
            rows: ["Auto", "*"],
            children:
            [
                VStack(6,
                    Heading("String catalog"),
                    TextBlock("Filter the master list and select a row to view details.")
                        .Foreground(SecondaryText),
                    TextField(filter, setFilter, placeholder: "Filter strings...")
                        .Width(320)
                ).Grid(row: 0, column: 0, columnSpan: 2),

                Border(
                    DataGrid(
                        source: source,
                        columns: Columns,
                        selectionMode: SelectionMode.Single,
                        onSelectionChanged: keys =>
                        {
                            var id = keys.Select(key => key.Value?.ToString()).FirstOrDefault();
                            setSelectedId(id);
                        },
                        rowHeight: 40,
                        emptyTemplate: EmptyState(filter))
                    .Flex(grow: 1, basis: 0)
                )
                .Background(CardBackground)
                .WithBorder(CardStroke, 1)
                .CornerRadius(8)
                .Padding(8)
                .Grid(row: 1, column: 0),

                DetailCard(selected)
                    .Grid(row: 1, column: 1)
            ])
            .Padding(24)
            .ColumnSpacing(16)
            .RowSpacing(16);
    }

    private static CatalogItem[] FilterItems(string filter)
    {
        var term = filter.Trim();
        if (term.Length == 0)
        {
            return Items;
        }

        return Items
            .Where(item =>
                item.Name.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                item.Group.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                item.Description.Contains(term, StringComparison.OrdinalIgnoreCase))
            .ToArray();
    }

    private static Element EmptyState(string filter) =>
        Border(
            TextBlock(string.IsNullOrWhiteSpace(filter)
                    ? "No strings available."
                    : $"No strings match \"{filter}\".")
                .Foreground(SecondaryText)
                .TextWrapping())
        .Padding(16);

    private static Element DetailCard(CatalogItem? item) =>
        Border(
            item is null
                ? VStack(8,
                    SubHeading("No selection"),
                    TextBlock("Adjust the filter to show matching strings.")
                        .Foreground(SecondaryText)
                        .TextWrapping())
                : VStack(10,
                    Caption(item.Group).Foreground(SecondaryText),
                    Heading(item.Name),
                    TextBlock(item.Description).TextWrapping(),
                    TextBlock($"Id: {item.Id}").Foreground(SecondaryText))
        )
        .Background(CardBackground)
        .WithBorder(CardStroke, 1)
        .CornerRadius(8)
        .Padding(18);
}

