        new("Harbor", "A working port with ferries, markets, and views across the water."),
        new("Meadow", "An open grassland with wildflowers and wide afternoon skies."),
        new("Orchard", "A cultivated landscape of fruit trees, lanes, and seasonal harvests."),
        new("Summit", "A high overlook with clear views and brisk weather.")
    ];

    public override Element Render()
    {
        var (filter, setFilter) = UseState("");
        var (selectedName, setSelectedName) = UseState(Items[0].Name);

        var filteredItems = UseMemo(
            () => Items
                .Where(item => item.Name.Contains(filter, StringComparison.OrdinalIgnoreCase))
                .ToArray(),
            filter);

        var selectedItem = Items.FirstOrDefault(item => item.Name == selectedName)
            ?? filteredItems.FirstOrDefault()
            ?? Items[0];

        return Grid(
            columns: ["320", "*"],
            rows: ["Auto", "*"],
            [
                TextField(filter, setFilter, placeholder: "Filter items", header: "Filter")
                    .Grid(row: 0, column: 0, columnSpan: 2)
