                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(8)
                    .Grid(row: 1, column: 0),

                Border(
                    VStack(12,
                        Heading(selectedItem.Name),
                        TextBlock(selectedItem.Description).Foreground(Theme.PrimaryText),
                        Caption("Select an item from the filtered list to view its details.")
                            .Foreground(Theme.SecondaryText)
                    )
                )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(24)
                    .Margin(left: 16)
                    .Grid(row: 1, column: 1)
