                    TextBlock("Open the dialog and type in the TextBox to filter the string list.")
                        .Foreground(Theme.SecondaryText),
                    Button("Open filter dialog", () => setDialogOpen(true))
                )
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1),
            ContentDialog(
                "Filter strings",
                Grid(
                    columns: ["*"],
                    rows: ["Auto", "Auto", "*"],
                    TextField(filterText, setFilterText, placeholder: "Type to filter...", header: "Filter")
                        .Grid(row: 0),
                    Caption($"{filteredItems.Length} match{(filteredItems.Length == 1 ? "" : "es")}")
                        .Foreground(Theme.SecondaryText)
                        .Grid(row: 1),
                    Border(
