    [
        "Fig",
        "Pear",
        "Apple",
        "Orange",
        "Blueberry",
        "Watermelon",
        "Pomegranate",
    ];

    public override Element Render()
    {
        var (minimumLength, setMinimumLength) = UseState(5.0);
        var (isDialogOpen, setDialogOpen) = UseState(false);

        var filteredItems = UseMemo(
            () => Items.Where(item => item.Length >= (int)minimumLength).ToArray(),
            minimumLength);

        return Grid(
            columns: ["*"],
            rows: ["Auto", "Auto", "*", "Auto"],
            Heading("String filter").Grid(0, 0),
            HStack(12,
                Button("Filter", () => setDialogOpen(true)),
                TextBlock($"Minimum length: {(int)minimumLength}")
                    .Foreground(Theme.SecondaryText)
            ).Grid(1, 0),
            Border(
                ScrollView(
                    filteredItems.Length == 0
                        ? VStack(Caption("No strings match the current filter."))
                        : VStack(6, filteredItems
                            .Select(item => Border(TextBlock(item))
                                .Background(Theme.CardBackground)
                                .WithBorder(Theme.CardStroke, 1)
                                .CornerRadius(6)
                                .Padding(10)
                                .WithKey(item))
                            .ToArray())
                )
            )
            .Background(Theme.SubtleFill)
            .CornerRadius(8)
            .Padding(8)
            .Grid(2, 0),
            Caption($"{filteredItems.Length} of {Items.Length} strings shown")
                .Foreground(Theme.SecondaryText)
                .Grid(3, 0),
            ContentDialog(
                "Filter strings",
                VStack(12,
                    TextBlock($"Show strings with at least {(int)minimumLength} characters."),
                    Slider(minimumLength, min: 1, max: 12, onChanged: setMinimumLength)
                ),
                primaryButtonText: "Done") with
            {
                IsOpen = isDialogOpen,
                OnClosed = _ => setDialogOpen(false),
            }
        )
        .Padding(24)
        .Background(Theme.DefaultBackground);
    }
}

