sealed record DetailItem(string Name, string Description, bool IsFramework);

class App : Component
{
    private static readonly DetailItem[] Items =
    [
        new("Microsoft.UI.Reactor", "A React-style C# framework for building WinUI apps.", true),
        new("WinUI", "The native Windows UI platform that Reactor renders to.", true),
        new("Grid layout", "A two-column layout for the master list and detail view.", false),
        new("Toggle filter", "A switch that narrows the string list to framework entries.", false),
        new("Theme tokens", "Default Reactor theme resources applied through fluent modifiers.", false),
    ];

    public override Element Render()
    {
        var (frameworkOnly, setFrameworkOnly) = UseState(false);
        var (selectedName, setSelectedName) = UseState(Items[0].Name);

        var visibleItems = Items
            .Where(item => !frameworkOnly || item.IsFramework)
            .ToArray();
        var selectedIndex = Math.Max(0, Array.FindIndex(visibleItems, item => item.Name == selectedName));
        var selectedItem = visibleItems.Length == 0 ? null : visibleItems[selectedIndex];

        return Grid(
            columns: ["320", "*"],
            rows: ["Auto", "*"],
            [
                Header(frameworkOnly, setFrameworkOnly).Grid(row: 0, column: 0, columnSpan: 2),
                MasterList(visibleItems, selectedIndex, index => setSelectedName(visibleItems[index].Name)).Grid(row: 1, column: 0),
                DetailPane(selectedItem).Grid(row: 1, column: 1),
            ])
            .Background(Theme.AppBackground)
            .Padding(24);
    }

    private static Element Header(bool frameworkOnly, Action<bool> setFrameworkOnly) =>
        Border(
            HStack(16,
                VStack(4,
                    Heading("Master-detail strings"),
                    Caption("Use the toggle to filter the master list.")
                        .Foreground(Theme.SecondaryText)
                ).Flex(grow: 1, basis: 0),
                ToggleSwitch(
                    frameworkOnly,
                    setFrameworkOnly,
                    onContent: "Frameworks only",
                    offContent: "All strings",
                    header: "Filter")
            ))
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(12)
            .Padding(16)
            .Margin(bottom: 16);

    private static Element MasterList(IReadOnlyList<DetailItem> items, int selectedIndex, Action<int> setSelectedIndex) =>
        Border(
            VStack(12,
                SubHeading("Master"),
                ListBox(
                    items.Select(item => item.Name).ToArray(),
                    selectedIndex,
                    setSelectedIndex)
                    .Flex(grow: 1, basis: 0)
            ))
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(12)
            .Padding(16)
            .Margin(right: 16);

    private static Element DetailPane(DetailItem? item) =>
        Border(
            item is null
                ? Caption("No item selected.").Foreground(Theme.SecondaryText)
