using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Record editor", width: 520, height: 360);

record EditableRecord(string Text);

class App : Component
{
    public override Element Render()
    {
        var (record, setRecord) = UseState(new EditableRecord("Initial record text"));
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (draftText, setDraftText) = UseState(record.Text);

        void BeginEdit()
        {
            setDraftText(record.Text);
            setDialogOpen(true);
        }

        return Grid(
            columns: [GridSize.Star],
            rows: [GridSize.Auto, GridSize.Star, GridSize.Auto],
            [
                Heading("Record editor")
                    .Grid(row: 0, column: 0),

                Border(
                    Grid(
                        columns: [GridSize.Auto, GridSize.Star],
                        rows: [GridSize.Auto, GridSize.Auto],
                        [
                            TextBlock("Current value")
                                .SemiBold()
                                .Foreground(Theme.PrimaryText)
                                .Grid(row: 0, column: 0),

                            TextBlock(record.Text)
                                .Foreground(Theme.SecondaryText)
                                .Grid(row: 1, column: 0, columnSpan: 2)
                        ])
                )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(16)
                    .Grid(row: 1, column: 0),

                Button("Edit record", BeginEdit)
                    .Grid(row: 2, column: 0),

                ContentDialog(
                    "Edit record",
                    Grid(
                        columns: [GridSize.Star],
                        rows: [GridSize.Auto],
                        [
                            TextField(
                                draftText,
                                setDraftText,
                                placeholder: "Enter record text",
                                header: "Text")
                            .Grid(row: 0, column: 0)
                        ]),
                    primaryButtonText: "Save") with
                {
                    IsOpen = isDialogOpen,
                    SecondaryButtonText = "Cancel",
                    OnClosed = result =>
                    {
                        if (result == ContentDialogResult.Primary)
                        {
                            setRecord(record with { Text = draftText });
                        }

                        setDialogOpen(false);
                    },
                }
            ])
            .Background(Theme.SolidBackground)
            .Padding(24);
    }
}

