class RecordEditorApp : Component
{
    public override Element Render()
    {
        var (record, setRecord) = UseState(new EditableRecord("Default record", false));
        var (draft, setDraft) = UseState<EditableRecord?>(null);

        return Border(
            VStack(16,
                Heading("Dialog record editor"),
                Grid(
                    columns: [GridSize.Auto, GridSize.Star()],
                    rows: [GridSize.Auto, GridSize.Auto],
                    children:
                    [
                        TextBlock("Label").SemiBold().Margin(left: 0, top: 0, right: 12, bottom: 8).Grid(0, 0),
                        TextBlock(record.Label)
                            .Foreground(Theme.PrimaryText)
                            .Margin(left: 0, top: 0, right: 0, bottom: 8)
                            .Grid(0, 1),
                        TextBlock("Reviewed").SemiBold().Margin(left: 0, top: 0, right: 12, bottom: 0).Grid(1, 0),
                        TextBlock(record.IsReviewed ? "Yes" : "No")
                            .Foreground(Theme.SecondaryText)
                            .Grid(1, 1),
                    ]),
                Button("Edit record", () => setDraft(record)),
                BuildEditDialog(draft, setDraft, setRecord)
            ))
            .Padding(24)
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(12);
    }

    private static Element BuildEditDialog(
        EditableRecord? draft,
        Action<EditableRecord?> setDraft,
        Action<EditableRecord> setRecord)
    {
        var currentDraft = draft ?? new EditableRecord(string.Empty, false);

        return ContentDialog(
            "Edit record",
            Grid(
                columns: [GridSize.Auto, GridSize.Star()],
                rows: [GridSize.Auto, GridSize.Auto],
                children:
                [
                    TextBlock("Label").Margin(left: 0, top: 0, right: 12, bottom: 12).Grid(0, 0),
                    TextField(
                        currentDraft.Label,
                        label => setDraft(currentDraft with { Label = label }),
                        placeholder: "Record label",
                        header: "Label").Margin(left: 0, top: 0, right: 0, bottom: 12).Grid(0, 1),
                    TextBlock("Reviewed").Margin(left: 0, top: 0, right: 12, bottom: 0).Grid(1, 0),
                    CheckBox(
                        currentDraft.IsReviewed,
                        isReviewed => setDraft(currentDraft with { IsReviewed = isReviewed }),
                        label: "Record has been reviewed").Grid(1, 1),
                ]),
            primaryButtonText: "Save") with
        {
            IsOpen = draft is not null,
            SecondaryButtonText = "Cancel",
            OnClosed = result =>
            {
                if (result == ContentDialogResult.Primary)
                {
                    setRecord(currentDraft);
                }

                setDraft(null);
            },
        };
    }
}

