using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Tabbed Record Editor", width: 720, height: 480);

record Profile(string DisplayName);

class App : Component
{
    private static readonly string[] DisplayNames = ["Ada", "Grace", "Katherine", "Margaret"];

    public override Element Render()
    {
        var (profile, setProfile) = UseState(new Profile(DisplayNames[0]));

        var selectedIndex = Array.IndexOf(DisplayNames, profile.DisplayName);
        if (selectedIndex < 0)
        {
            selectedIndex = 0;
        }

        return Grid(
            columns: [GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Star()],
            [
                Heading("Profile")
                    .Foreground(Theme.PrimaryText)
                    .Grid(row: 0, column: 0),

                TabView(
                    [
                        Tab("Edit", EditorTab(profile, selectedIndex, setProfile)),
                        Tab("Summary", SummaryTab(profile))
                    ])
                    .ShowAddButton(false)
                    .Grid(row: 1, column: 0)
            ])
            .Background(Theme.SolidBackground)
            .Padding(24);
    }

    private static Element EditorTab(Profile profile, int selectedIndex, Action<Profile> setProfile) =>
        Grid(
            columns: [GridSize.Px(160), GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Auto()],
            [
                TextBlock("Display name")
                    .Foreground(Theme.SecondaryText)
                    .VAlign(VerticalAlignment.Center)
                    .Grid(row: 0, column: 0),

                ComboBox(DisplayNames, selectedIndex, index => setProfile(profile with { DisplayName = DisplayNames[index] }))
                    .MinWidth(220)
                    .Grid(row: 0, column: 1),

                TextBlock("Record value")
                    .Foreground(Theme.SecondaryText)
                    .VAlign(VerticalAlignment.Center)
                    .Grid(row: 1, column: 0),

                Border(TextBlock(profile.DisplayName).Foreground(Theme.PrimaryText))
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(12)
                    .Grid(row: 1, column: 1)
            ])
            .Padding(16);

    private static Element SummaryTab(Profile profile) =>
        Border(
            VStack(8,
                SubHeading("Current record"),
                TextBlock($"DisplayName: {profile.DisplayName}").Foreground(Theme.PrimaryText)))
            .Background(Theme.CardBackground)
            .WithBorder(Theme.CardStroke, 1)
            .CornerRadius(8)
            .Padding(16)
            .Margin(16);
}

