using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Layout;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail", width: 720, height: 420);

record Customer(string Name, string Tier);

class App : Component
{
    static readonly Customer[] InitialCustomers =
    [
        new("Ada Lovelace", "Standard"),
        new("Grace Hopper", "Premium"),
        new("Katherine Johnson", "Enterprise"),
    ];

    static readonly string[] TierOptions = ["Standard", "Premium", "Enterprise"];

    public override Element Render()
    {
        var (customers, setCustomers) = UseState<IReadOnlyList<Customer>>(InitialCustomers);
        var (selectedIndex, setSelectedIndex) = UseState(0);

        var selectedCustomer = customers[selectedIndex];
        var selectedTierIndex = Array.IndexOf(TierOptions, selectedCustomer.Tier);

        void UpdateSelectedTier(int tierIndex)
        {
            var updated = customers
                .Select((customer, index) => index == selectedIndex
                    ? customer with { Tier = TierOptions[tierIndex] }
                    : customer)
                .ToArray();

            setCustomers(updated);
        }

        return Grid(
            columns: [GridSize.Px(260), GridSize.Star()],
            rows: [GridSize.Auto(), GridSize.Star()],
            children:
            [
                Heading("Customers").Margin(bottom: 12).Grid(row: 0, column: 0),
                Heading("Details").Margin(left: 12, bottom: 12).Grid(row: 0, column: 1),

                Border(
                    VStack(8,
                        TextBlock("Select a customer").Foreground(Theme.SecondaryText),
                        ComboBox(customers.Select(customer => customer.Name).ToArray(), selectedIndex, setSelectedIndex)
                    )
                )
                .Background(Theme.CardBackground)
                .CornerRadius(8)
                .Padding(16)
                .WithBorder(Theme.CardStroke, 1)
                .Grid(row: 1, column: 0),

                Border(
                    VStack(12,
                        SubHeading(selectedCustomer.Name),
                        TextBlock("Tier").Foreground(Theme.SecondaryText),
                        ComboBox(TierOptions, selectedTierIndex, UpdateSelectedTier),
                        Caption($"Current value: {selectedCustomer.Tier}").Foreground(Theme.SecondaryText)
                    )
                )
                .Background(Theme.CardBackground)
                .CornerRadius(8)
                .Padding(16)
                .WithBorder(Theme.CardStroke, 1)
                .Margin(left: 12)
                .Grid(row: 1, column: 1),
            ]
        )
        .Padding(24);
    }
}

