using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog ComboBox Flow", width: 520, height: 360);

record Profile(string DisplayName, string Role);

class App : Component
{
    static readonly string[] RoleOptions = ["Designer", "Developer", "Manager"];

    public override Element Render()
    {
        var (profile, setProfile) = UseState(new Profile("Ada Lovelace", "Developer"));
        var (isEditorOpen, setEditorOpen) = UseState(false);
        var (draftRoleIndex, setDraftRoleIndex) = UseState(Array.IndexOf(RoleOptions, profile.Role));

        var roleIndex = Math.Max(0, Array.IndexOf(RoleOptions, profile.Role));

        return Border(
            Grid(
                columns: ["Auto", "*"],
                rows: ["Auto", "Auto", "Auto", "Auto"],
                [
                    Heading("Profile").Grid(row: 0, column: 0, columnSpan: 2),

                    TextBlock("Name").Foreground(Theme.SecondaryText).Grid(row: 1, column: 0),
                    TextBlock(profile.DisplayName).Grid(row: 1, column: 1),

                    TextBlock("Role").Foreground(Theme.SecondaryText).Grid(row: 2, column: 0),
                    TextBlock(profile.Role).Grid(row: 2, column: 1),

                    Button("Edit role", () =>
                    {
                        setDraftRoleIndex(roleIndex);
                        setEditorOpen(true);
                    }).Grid(row: 3, column: 1).HAlign(HorizontalAlignment.Left),

                    ContentDialog(
                        "Edit role",
                        Grid(
                            columns: ["Auto", "*"],
                            rows: ["Auto", "Auto"],
                            [
                                TextBlock("Name").Foreground(Theme.SecondaryText).Grid(row: 0, column: 0),
                                TextBlock(profile.DisplayName).Grid(row: 0, column: 1),

                                TextBlock("Role").Foreground(Theme.SecondaryText).Grid(row: 1, column: 0),
                                ComboBox(RoleOptions, draftRoleIndex, setDraftRoleIndex)
                                    .Placeholder("Choose a role")
                                    .MinWidth(220)
                                    .Grid(row: 1, column: 1),
                            ]
                        ).ColumnSpacing(12).RowSpacing(12),
                        primaryButtonText: "Save") with
                    {
                        IsOpen = isEditorOpen,
                        SecondaryButtonText = "Cancel",
                        OnClosed = result =>
                        {
                            if (result == ContentDialogResult.Primary)
                            {
                                setProfile(profile with { Role = RoleOptions[draftRoleIndex] });
                            }

                            setEditorOpen(false);
                        },
                    },
                ]
            ).ColumnSpacing(16).RowSpacing(12)
        )
        .Background(Theme.CardBackground)
        .WithBorder(Theme.CardStroke, 1)
        .CornerRadius(12)
        .Padding(24)
        .Margin(24);
    }
}

