using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Controls;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Reactor.Data;
using Microsoft.UI.Reactor.Data.Providers;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<MasterDetailApp>("Master Detail", width: 900, height: 520);

record CustomerRecord(int Id, string Name);

class MasterDetailApp : Component
{
    static readonly IReadOnlyList<CustomerRecord> InitialRecords =
    [
        new(1, "Ada Lovelace"),
        new(2, "Grace Hopper"),
        new(3, "Katherine Johnson"),
        new(4, "Margaret Hamilton")
    ];

    public override Element Render()
    {
        var (records, updateRecords) = UseReducer(InitialRecords);
        var (selectedKeys, setSelectedKeys) = UseState<IReadOnlySet<RowKey>>(new HashSet<RowKey> { (RowKey)1 });

        var source = UseMemo(
            () => new ListDataSource<CustomerRecord>(records, record => (RowKey)record.Id),
            records);

        var columns = UseMemo(() => new FieldDescriptor[]
        {
            Column<CustomerRecord>("Id", record => record.Id, width: 80),
            Column<CustomerRecord>("Name", record => record.Name, editable: true, width: 220)
        });

        var selectedKey = selectedKeys.FirstOrDefault().Value;
        var selectedId = int.TryParse(selectedKey, out var id) ? id : 1;
        var selectedRecord = records.FirstOrDefault(record => record.Id == selectedId) ?? records[0];

        void UpdateName(string name)
        {
            updateRecords(items => items
                .Select(record => record.Id == selectedRecord.Id ? record with { Name = name } : record)
                .ToArray());
        }

        return Grid(
            columns: [GridSize.Star(), GridSize.Px(280)],
            rows: [GridSize.Auto, GridSize.Star],
            Heading("Records").Grid(row: 0, column: 0),
            SubHeading("Detail").Grid(row: 0, column: 1),
            Border(
                DataGrid(
                    source: source,
                    columns: columns,
                    selectionMode: SelectionMode.Single,
                    onSelectionChanged: setSelectedKeys,
                    onRowChanged: (key, record) =>
                    {
                        updateRecords(items => items
                            .Select(item => item.Id == record.Id ? record : item)
                            .ToArray());
                        return Task.CompletedTask;
                    },
                    editable: true,
                    editMode: EditMode.Cell,
                    rowHeight: 36
                ).Flex(grow: 1, basis: 0)
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(8)
                .Grid(row: 1, column: 0),
            Border(
                VStack(12,
                    Caption($"Record {selectedRecord.Id}").Foreground(Theme.SecondaryText),
                    TextField(selectedRecord.Name, UpdateName, header: "Name")
                )
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1, column: 1)
        )
        .Padding(24)
        .Background(Theme.SolidBackground);
    }
}

