using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail", width: 760, height: 420);

sealed record NoteRecord(int Id, string Name, string Text);

class App : Component
{
    private static readonly IReadOnlyList<NoteRecord> InitialRecords =
    [
        new(1, "First record", "This is the first editable string."),
        new(2, "Second record", "This record has its own editable value."),
        new(3, "Third record", "Select a record, then edit its text here.")
    ];

    public override Element Render()
    {
        var (records, updateRecords) = UseReducer(InitialRecords);
        var (selectedId, setSelectedId) = UseState(InitialRecords[0].Id);

        var selected = records.First(record => record.Id == selectedId);

        return Grid(
            columns: ["240", "*"],
            rows: ["Auto", "*"],
            Heading("Records")
                .Grid(row: 0, column: 0)
                .Margin(0, 0, 16, 12),
            Heading("Detail")
                .Grid(row: 0, column: 1)
                .Margin(0, 0, 0, 12),
            Border(
                VStack(8, records.Select(record =>
                    Button(record.Name, () => setSelectedId(record.Id))
                        .Background(record.Id == selectedId ? Theme.Accent : Theme.SubtleFill)
                        .Foreground(record.Id == selectedId ? Theme.TextOnAccent : Theme.PrimaryText)
                        .WithKey(record.Id)
                    ).ToArray())
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(12)
                .Grid(row: 1, column: 0)
                .Margin(0, 0, 16, 0),
            Border(
                VStack(12,
                    SubHeading(selected.Name),
                    TextField(
                        selected.Text,
                        text => updateRecords(items => items
                            .Select(record => record.Id == selected.Id ? record with { Text = text } : record)
                            .ToArray()),
                        placeholder: "Edit the record text")
                )
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1, column: 1)
        ).Padding(24);
    }
}

