            Heading("Records")
                .Grid(row: 0, column: 0)
                .Margin(0, 0, 16, 12),
            Heading("Detail")
                .Grid(row: 0, column: 1)
                .Margin(0, 0, 0, 12),
            Border(
                VStack(8, records.Select(record =>
                    Button(record.Name, () => setSelectedId(record.Id))
                        .Background(record.Id == selectedId ? Theme.Accent : Theme.SubtleFill)
                        .Foreground(record.Id == selectedId ? Theme.AccentText : Theme.PrimaryText)
                        .AutomationName(record.Name)
                        .WithKey(record.Id.ToString())
                    ).ToArray())
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(12)
                .Grid(row: 1, column: 0)
                .Margin(0, 0, 16, 0),
            Border(
                VStack(12,
                    SubHeading(selected.Name),
                    TextField(
                        selected.Text,
                        text => updateRecords(items => items
                            .Select(record => record.Id == selected.Id ? record with { Text = text } : record)
                            .ToArray()),
                        placeholder: "Edit the record text",
                        header: "Record text")
                )
            )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1, column: 1)
        ).Padding(24);
    }
}

