using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Slider Record Editor", width: 640, height: 360);

record MessageRecord(string Text);

class App : Component
{
    const string SourceText = "Reactor keeps record updates clear.";

    public override Element Render()
    {
        var initial = new MessageRecord(SourceText[..12]);
        var (message, setMessage) = UseState(initial);

        var length = message.Text.Length;

        return Grid(
            columns: ["Auto", "*"],
            rows: ["Auto", "Auto", "Auto"],
            [
                Heading("Record string editor")
                    .Grid(row: 0, column: 0, columnSpan: 2),

                TextBlock("Length")
                    .Foreground(Theme.SecondaryText)
                    .Margin(right: 16)
                    .VAlign(VerticalAlignment.Center)
                    .Grid(row: 1, column: 0),

                Slider(length, min: 1, max: SourceText.Length, onChanged: value =>
                    setMessage(message with { Text = SourceText[..(int)Math.Round(value)] }))
                    .Header($"{length} characters")
                    .StepFrequency(1)
                    .Grid(row: 1, column: 1),

                Border(
                    TextBlock(message.Text)
                        .TextWrapping()
                        .Foreground(Theme.PrimaryText)
                )
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke)
                    .CornerRadius(8)
                    .Padding(16)
                    .Grid(row: 2, column: 0, columnSpan: 2),
            ]
        ).Padding(24);
    }
}

