using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Master Detail Slider", width: 720, height: 420);

record DetailRecord(int Id, string Name, string Text);

class App : Component
{
    static readonly IReadOnlyList<DetailRecord> InitialRecords =
    [
        new(1, "Alpha", BuildText(6)),
        new(2, "Beta", BuildText(10)),
        new(3, "Gamma", BuildText(14)),
    ];

    public override Element Render()
    {
        var (records, updateRecords) = UseReducer(InitialRecords);
        var (selectedIndex, setSelectedIndex) = UseState(0);
        var selected = records[selectedIndex];
        var textLength = selected.Text.Length;

        return Grid(
            columns: ["220", "*"],
            rows: ["Auto", "*"],
            children:
            [
                Heading("Records")
                    .Grid(row: 0, column: 0, columnSpan: 2)
                    .Margin(bottom: 16),

                Border(
                    VStack(8,
                        SubHeading("Master"),
                        ListBox(records.Select(record => record.Name).ToArray(), selectedIndex, setSelectedIndex)
                    )
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(12)
                .Grid(row: 1, column: 0),

                Border(
                    VStack(12,
                        SubHeading(selected.Name),
                        TextBlock(selected.Text).Foreground(Theme.PrimaryText),
                        Caption($"String length: {textLength}").Foreground(Theme.SecondaryText),
                        Slider(textLength, min: 1, max: 24, onChanged: value =>
                            updateRecords(items => items
                                .Select((record, index) => index == selectedIndex
                                    ? record with { Text = BuildText(value) }
                                    : record)
                                .ToArray()))
                            .Header("Edit the record string")
                            .StepFrequency(1)
                    )
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke, 1)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1, column: 1)
            ])
            .Background(Theme.SolidBackground)
            .Padding(24);
    }

    static string BuildText(double value)
    {
        var length = Math.Clamp((int)Math.Round(value), 1, 24);
        return new string('*', length);
    }
}

