using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog Flow", width: 640, height: 420);

record ProfileSetting(string Label, double Priority);

class App : Component
{
    public override Element Render()
    {
        var (setting, setSetting) = UseState(new ProfileSetting("Default record", 42));
        var (dialogOpen, setDialogOpen) = UseState(false);
        var (draftLabel, setDraftLabel) = UseState(setting.Label);
        var (draftPriority, setDraftPriority) = UseState(setting.Priority);

        return Grid(
            new[] { GridSize.Star },
            new[] { GridSize.Auto, GridSize.Star },
            new Element[]
            {
                Heading("Record editor").Grid(row: 0, column: 0),

                Border(
                    Grid(
                        new[] { GridSize.Auto, GridSize.Star },
                        new[] { GridSize.Auto, GridSize.Auto, GridSize.Auto },
                        new Element[]
                        {
                            TextBlock("Label").Foreground(Theme.SecondaryText).Grid(row: 0, column: 0),
                            TextBlock(setting.Label).Grid(row: 0, column: 1),

                            TextBlock("Priority").Foreground(Theme.SecondaryText).Grid(row: 1, column: 0),
                            TextBlock($"{setting.Priority:0}").Grid(row: 1, column: 1),

                            Button("Edit record", () =>
                            {
                                setDraftLabel(setting.Label);
                                setDraftPriority(setting.Priority);
                                setDialogOpen(true);
                            }).Grid(row: 2, column: 1),
                        }
                    )
                )
                .Background(Theme.CardBackground)
                .WithBorder(Theme.CardStroke)
                .CornerRadius(8)
                .Padding(16)
                .Grid(row: 1, column: 0),

                ContentDialog(
                    "Edit record",
                    Grid(
                        new[] { GridSize.Auto, GridSize.Star },
                        new[] { GridSize.Auto, GridSize.Auto, GridSize.Auto },
                        new Element[]
                        {
                            TextBlock("Label").Grid(row: 0, column: 0),
                            TextField(draftLabel, setDraftLabel, placeholder: "Record label")
                                .AutomationName("Label")
                                .Grid(row: 0, column: 1),

                            TextBlock("Priority").Grid(row: 1, column: 0),
                            Slider(draftPriority, 0, 100, setDraftPriority)
                                .Header($"{draftPriority:0}")
                                .StepFrequency(1)
                                .Grid(row: 1, column: 1),

                            Caption("Saving updates the record with the edited string and slider value.")
                                .Foreground(Theme.SecondaryText)
                                .Grid(row: 2, column: 0, columnSpan: 2),
                        }
                    ),
                    primaryButtonText: "Save") with
                {
                    IsOpen = dialogOpen,
                    SecondaryButtonText = "Cancel",
                    OnClosed = result =>
                    {
                        if (result == ContentDialogResult.Primary)
                        {
                            setSetting(setting with
                            {
                                Label = draftLabel,
                                Priority = draftPriority,
                            });
                        }

                        setDialogOpen(false);
                    },
                },
            }
        )
        .Background(Theme.SolidBackground)
        .Padding(24);
    }
}

