using Microsoft.UI.Reactor;
using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Radio Record Editor", width: 520, height: 360);

record ChoiceRecord(string Value);

class App : Component
{
    public override Element Render()
    {
        var (record, setRecord) = UseState(new ChoiceRecord("Alpha"));

        void Select(string value, bool isChecked)
        {
            if (isChecked)
            {
                setRecord(record with { Value = value });
            }
        }

        return Grid(
            columns: ["Auto", "*"],
            rows: ["Auto", "Auto", "Auto", "Auto"],
            [
                Heading("Edit record").Grid(row: 0, column: 0, columnSpan: 2),

                TextBlock("Value").Grid(row: 1, column: 0).Margin(right: 16, bottom: 8),
                TextBlock(record.Value)
                    .Foreground(Theme.PrimaryText)
                    .Grid(row: 1, column: 1)
                    .Margin(bottom: 8),

                TextBlock("Choose").Grid(row: 2, column: 0).Margin(right: 16),
                VStack(8,
                    RadioButton("Alpha", record.Value == "Alpha", isChecked => Select("Alpha", isChecked), "record-value"),
                    RadioButton("Beta", record.Value == "Beta", isChecked => Select("Beta", isChecked), "record-value"),
                    RadioButton("Gamma", record.Value == "Gamma", isChecked => Select("Gamma", isChecked), "record-value")
                ).Grid(row: 2, column: 1),

                Border(Caption($"Current record: {record}"))
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(12)
                    .Grid(row: 3, column: 0, columnSpan: 2)
                    .Margin(top: 24)
            ]
        ).Padding(24);
    }
}

