sealed record Customer(int Id, string Name);

class App : Component
{
    private static readonly Customer[] InitialCustomers =
    [
        new(1, "Ada Lovelace"),
        new(2, "Grace Hopper"),
        new(3, "Katherine Johnson"),
    ];

    public override Element Render()
    {
        var (customers, setCustomers) = UseState(InitialCustomers);
        var (selectedId, setSelectedId) = UseState(InitialCustomers[0].Id);

