            Heading("Details").Grid(row: 0, column: 1).Margin(left: 24, bottom: 12),
            Border(
                VStack(8,
                    customers.Select(customer =>
                    {
                        var current = customer;
                        return RadioButton(
                                current.Name,
                                current.Id == selectedId,
                                isChecked =>
                                {
                                    if (isChecked)
                                    {
                                        setSelectedId(current.Id);
                                    }
                                },
                                groupName: "customers")
                            .WithKey(current.Id.ToString());
                    }).ToArray()
                )
            )
