using Microsoft.UI.Reactor.Core;
using Microsoft.UI.Xaml.Controls;
using static Microsoft.UI.Reactor.Factories;

ReactorApp.Run<App>("Dialog Radio Edit", width: 520, height: 360);

record CustomerNote(string Text);

class App : Component
{
    public override Element Render()
    {
        var (note, setNote) = UseState(new CustomerNote("Ready for review"));
        var (isDialogOpen, setDialogOpen) = UseState(false);
        var (draft, setDraft) = UseState(note);

        void OpenEditor()
        {
            setDraft(note);
            setDialogOpen(true);
        }

        return Grid(
            columns: ["*"],
            rows: ["Auto", "*"],
            [
                Heading("Record editor").Grid(row: 0, column: 0).Margin(bottom: 16),
                Border(
                    VStack(12,
                        Caption("Current record").Foreground(Theme.SecondaryText),
                        TextBlock(note.Text).Foreground(Theme.PrimaryText),
                        Button("Edit record", OpenEditor)
                    )
                )
                    .Grid(row: 1, column: 0)
                    .Background(Theme.CardBackground)
                    .WithBorder(Theme.CardStroke, 1)
                    .CornerRadius(8)
                    .Padding(16),
                ContentDialog(
                    "Edit record",
                    Grid(
                        columns: ["Auto", "*"],
                        rows: ["Auto", "Auto"],
                        [
                            RadioButton(
                                "Text",
                                isChecked: true,
                                onChecked: isChecked =>
                                {
                                    if (isChecked)
                                    {
                                        setDraft(draft with { Text = draft.Text });
                                    }
                                },
                                groupName: "recordField")
                                .Grid(row: 0, column: 0)
                                .Margin(right: 12, bottom: 12),
                            Caption("Record string").Grid(row: 0, column: 1).Margin(bottom: 12),
                            TextField(
                                draft.Text,
                                value => setDraft(draft with { Text = value }),
                                placeholder: "Enter text")
                                .Grid(row: 1, column: 0, columnSpan: 2)
                        ]
                    ),
                    primaryButtonText: "Save") with
                    {
                        IsOpen = isDialogOpen,
                        SecondaryButtonText = "Cancel",
                        OnClosed = result =>
                        {
                            if (result == ContentDialogResult.Primary)
                            {
                                setNote(draft);
                            }

                            setDialogOpen(false);
                        },
                    }
            ]
        ).Padding(24).Background(Theme.AppBackground);
    }
}

